export default "{\"schema\":\"ai-brain.inert-reference.v1\",\"trust\":\"untrusted_reference_only\",\"records\":[{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_app.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"65e0b07b8d24ec2107ec605abf9978b059454c58db49029594d8e284f607aed8\",\"content\":\"\\\"\\\"\\\"Unit tests for LFX CLI FastAPI serve app.\\\"\\\"\\\"\\n\\nimport hashlib\\nimport json\\nimport os\\nimport secrets\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom fastapi.testclient import TestClient\\nfrom lfx.cli.serve_app import (\\n    FlowMeta,\\n    FlowRegistry,\\n    create_multi_serve_app,\\n    verify_api_key,\\n)\\nfrom lfx.graph import Graph\\nfrom lfx.graph.schema import ResultData\\nfrom lfx.interface.components import component_cache\\nfrom lfx.schema.message import Message\\n\\n\\ndef _make_settings_service(*, allow_custom_components: bool = False):\\n    return SimpleNamespace(\\n        settings=SimpleNamespace(\\n            allow_custom_components=allow_custom_components,\\n        )\\n    )\\n\\n\\n_MISSING = object()\\n\\n\\ndef test_create_multi_serve_app_registers_variable_service():\\n    \\\"\\\"\\\"Regression: building the serve app must register the minimal VariableService.\\n\\n    The credential resolver (``get_api_key_for_provider``, ``get_all_variables_for_provider``,\\n    ``model_utils``, KB connectors) resolves request-scoped ``global_vars`` only *through*\\n    ``get_variable_service()``. Standalone lfx ships no VariableService factory, so before\\n    this fix the serve worker left it unregistered (``None``) and request-scoped model\\n    credentials silently fell through to ``os.environ`` \u2014 and to nothing under\\n    ``--no-env-fallback``. Building the serve app must register it so all of those paths\\n    become request-scope-aware.\\n    \\\"\\\"\\\"\\n    from lfx.services.deps import get_variable_service\\n    from lfx.services.manager import get_service_manager\\n    from lfx.services.schema import ServiceType\\n    from lfx.services.variable.service import VariableService\\n\\n    manager = get_service_manager()\\n    prev_class = manager.service_classes.get(ServiceType.VARIABLE_SERVICE, _MISSING)\\n    prev_instance = manager.services.get(ServiceType.VARIABLE_SERVICE, _MISSING)\\n    manager.services.pop(ServiceType.VARIABLE_SERVICE, None)\\n    manager.service_classes.pop(ServiceType.VARIABLE_SERVICE, None)\\n    try:\\n        assert get_variable_service() is None, \\\"precondition: standalone lfx has no VariableService\\\"\\n        create_multi_serve_app(registry=FlowRegistry())\\n        assert isinstance(get_variable_service(), VariableService)\\n    finally:\\n        manager.services.pop(ServiceType.VARIABLE_SERVICE, None)\\n        manager.service_classes.pop(ServiceType.VARIABLE_SERVICE, None)\\n        if prev_class is not _MISSING:\\n            manager.service_classes[ServiceType.VARIABLE_SERVICE] = prev_class\\n        if prev_instance is not _MISSING:\\n            manager.services[ServiceType.VARIABLE_SERVICE] = prev_instance\\n\\n\\nasync def test_serve_app_resolves_request_scoped_credential(monkeypatch):\\n    \\\"\\\"\\\"End-to-end: real registration resolves a request-scoped global_var under ``--no-env-fallback``.\\n\\n    The serve app's real registration lets a request-scoped global_var resolve through\\n    ``get_api_key_for_provider``. Unlike the ``variable_service_registered`` fixture in ``test_credentials.py``, this\\n    drives the *actual* registration path (``create_multi_serve_app``) \u2014 the exact chain\\n    the original bug broke (service unregistered -> request scope never consulted). A\\n    different value is left in ``os.environ`` to prove the request scope wins and env is\\n    not the source.\\n    \\\"\\\"\\\"\\n    from lfx.base.models.unified_models import (\\n        get_api_key_for_provider,\\n        get_model_provider_variable_mapping,\\n    )\\n    from lfx.services.deps import get_variable_service\\n    from lfx.services.manager import get_service_manager\\n    from lfx.services.schema import ServiceType\\n    from lfx.services.variable.request_scope import (\\n        activate_no_env_fallback,\\n        activate_request_variables,\\n        reset_no_env_fallback,\\n        reset_request_variables,\\n    )\\n\\n    var = get_model_provider_variable_mapping()[\\\"OpenAI\\\"]\\n    manager = get_service_manager()\\n    prev_class = manager.service_classes.get(ServiceType.VARIABLE_SERVICE, _MISSING)\\n    prev_instance = manager.services.get(ServiceType.VARIABLE_SERVICE, _MISSING)\\n    manager.services.pop(ServiceType.VARIABLE_SERVICE, None)\\n    manager.service_classes.pop(ServiceType.VARIABLE_SERVICE, None)\\n    monkeypatch.setenv(var, \\\"sk-env-must-not-win\\\")  # pragma: allowlist secret\\n\\n    scope_token = nofb_token = None\\n    try:\\n        # The serve app factory performs the registration \u2014 no test fixture involved.\\n        create_multi_serve_app(registry=FlowRegistry())\\n        assert get_variable_service() is not None\\n\\n        nofb_token = activate_no_env_fallback(disabled=True)\\n        scope_token = activate_request_variables({var: \\\"sk-from-request\\\"})  # pragma: allowlist secret\\n        resolved = get_api_key_for_provider(\\\"11111111-1111-1111-1111-111111111111\\\", \\\"OpenAI\\\", None)\\n        assert resolved == \\\"sk-from-request\\\"  # request scope wins; env ignored under no_env_fallback\\n    finally:\\n        if scope_token is not None:\\n            reset_request_variables(scope_token)\\n        if nofb_token is not None:\\n            reset_no_env_fallback(nofb_token)\\n        manager.services.pop(ServiceType.VARIABLE_SERVICE, None)\\n        manager.service_classes.pop(ServiceType.VARIABLE_SERVICE, None)\\n        if prev_class is not _MISSING:\\n            manager.service_classes[ServiceType.VARIABLE_SERVICE] = prev_class\\n        if prev_instance is not _MISSING:\\n            manager.services[ServiceType.VARIABLE_SERVICE] = prev_instance\\n\\n\\ndef _blocked_raw_graph() -> dict:\\n    return {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"id\\\": \\\"node-1\\\",\\n                \\\"data\\\": {\\n                    \\\"id\\\": \\\"node-1\\\",\\n                    \\\"type\\\": \\\"TotallyCustom\\\",\\n                    \\\"node\\\": {\\n                        \\\"display_name\\\": \\\"Blocked Node\\\",\\n                        \\\"template\\\": {\\n                            \\\"code\\\": {\\\"value\\\": \\\"print('blocked')\\\"},\\n                        },\\n                    },\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n\\n\\n@pytest.fixture(autouse=True)\\ndef allow_custom_components_by_default(monkeypatch):\\n    \\\"\\\"\\\"Keep constructor-level validation aligned with the serve_app test default path.\\\"\\\"\\\"\\n    from lfx.services.deps import get_settings_service\\n\\n    monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n\\nclass TestFlowRegistry:\\n    def _make_meta(self, flow_id: str) -> FlowMeta:\\n        return FlowMeta(id=flow_id, relative_path=f\\\"{flow_id}.json\\\", title=flow_id, description=None)\\n\\n    def test_add_and_get(self):\\n        registry = FlowRegistry()\\n        graph = MagicMock()\\n        meta = self._make_meta(\\\"flow-1\\\")\\n        registry.add(graph, meta)\\n        result = registry.get(\\\"flow-1\\\")\\n        assert result is not None\\n        assert result[0] is graph\\n        assert result[1] == meta\\n\\n    def test_get_missing_returns_none(self):\\n        assert FlowRegistry().get(\\\"nonexistent\\\") is None\\n\\n    def test_list_metas_empty(self):\\n        assert FlowRegistry().list_metas() == []\\n\\n    def test_list_metas_multiple(self):\\n        registry = FlowRegistry()\\n        graph = MagicMock()\\n        registry.add(graph, self._make_meta(\\\"a\\\"))\\n        registry.add(graph, self._make_meta(\\\"b\\\"))\\n        ids = {m.id for m in registry.list_metas()}\\n        assert ids == {\\\"a\\\", \\\"b\\\"}\\n\\n    def test_duplicate_add_raises_without_overwrite(self):\\n        from lfx.cli.serve_app import FlowAlreadyRegisteredError\\n\\n        registry = FlowRegistry()\\n        meta = self._make_meta(\\\"flow-1\\\")\\n        registry.add(MagicMock(), meta)\\n        with pytest.raises(FlowAlreadyRegisteredError, match=\\\"already registered\\\"):\\n            registry.add(MagicMock(), meta)\\n\\n    def test_duplicate_add_replaces_with_overwrite(self):\\n        registry = FlowRegistry()\\n        g1, g2 = MagicMock(), MagicMock()\\n        meta = self._make_meta(\\\"flow-1\\\")\\n        registry.add(g1, meta)\\n        registry.add(g2, meta, overwrite=True)\\n        assert registry.get(\\\"flow-1\\\")[0] is g2\\n\\n    def test_len(self):\\n        registry = FlowRegistry()\\n        assert len(registry) == 0\\n        registry.add(MagicMock(), self._make_meta(\\\"x\\\"))\\n        assert len(registry) == 1\\n\\n    def test_len_counts_store_only_flows(self):\\n        \\\"\\\"\\\"len() must include flows that are in the store but not yet cache-loaded.\\\"\\\"\\\"\\n        raw = {\\\"name\\\": \\\"Store-Only\\\", \\\"data\\\": {}, \\\"id\\\": \\\"store-only-id\\\"}\\n\\n        class StubStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"store-only-id\\\" else None\\n\\n            def delete(self, *_a):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"store-only-id\\\"]\\n\\n        registry = FlowRegistry(store=StubStore())\\n        # Nothing in memory yet \u2014 but len() must still report 1 via list_metas().\\n        assert len(registry) == 1\\n\\n    def test_len_not_double_counted_memory_and_store(self):\\n        \\\"\\\"\\\"len() must not double-count a flow that's both in memory and in the store.\\\"\\\"\\\"\\n        raw = {\\\"name\\\": \\\"Shared\\\", \\\"data\\\": {}, \\\"id\\\": \\\"shared-id\\\"}\\n\\n        class StubStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"shared-id\\\" else None\\n\\n            def delete(self, *_a):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"shared-id\\\"]\\n\\n        registry = FlowRegistry(store=StubStore())\\n        graph = MagicMock()\\n        graph.context = {}\\n        registry.add(graph, self._make_meta(\\\"shared-id\\\"))\\n        assert len(registry) == 1\\n\\n    def test_warm_from_store_skips_unloadable_flows(self, tmp_path):\\n        \\\"\\\"\\\"A single corrupt/unloadable store file must not abort warm-up of the rest.\\n\\n        On a shared/PVC store, one bad ``{id}.json`` would otherwise crash every\\n        worker's startup. warm_from_store must skip it and load the good flows.\\n        \\\"\\\"\\\"\\n        from lfx.cli.flow_store import FilesystemFlowStore\\n\\n        store = FilesystemFlowStore(tmp_path)\\n        # Corrupt file: read() returns None -> get() returns None (skipped silently).\\n        (tmp_path / \\\"corrupt.json\\\").write_text(\\\"{ not json \\\", encoding=\\\"utf-8\\\")\\n        # Valid JSON that fails to reconstruct -> get() raises -> warm_from_store must catch.\\n        store.write(\\\"unloadable\\\", {\\\"name\\\": \\\"Bad\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"id\\\": \\\"unloadable\\\"})\\n        # A good flow that reconstructs fine.\\n        store.write(\\\"good\\\", {\\\"name\\\": \\\"Good\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"id\\\": \\\"good\\\"})\\n\\n        registry = FlowRegistry(store=store)\\n        good_graph = MagicMock()\\n        good_graph.context = {}\\n\\n        def fake_load(raw_json):\\n            if raw_json.get(\\\"id\\\") == \\\"unloadable\\\":\\n                msg = \\\"component not available in this build\\\"\\n                raise ValueError(msg)\\n            return good_graph\\n\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", side_effect=fake_load):\\n            registry.warm_from_store()  # must NOT raise despite corrupt + unloadable files\\n            assert registry.get(\\\"good\\\") is not None\\n\\n    def test_remove_existing(self):\\n        registry = FlowRegistry()\\n        meta = self._make_meta(\\\"flow-1\\\")\\n        registry.add(MagicMock(), meta)\\n        assert registry.remove(\\\"flow-1\\\") is True\\n        assert registry.get(\\\"flow-1\\\") is None\\n\\n    def test_remove_nonexistent(self):\\n        assert FlowRegistry().remove(\\\"ghost\\\") is False\\n\\n    def test_registry_no_env_fallback_stamps_context_on_add(self):\\n        \\\"\\\"\\\"FlowRegistry(no_env_fallback=True) must set graph.context['no_env_fallback']=True on add.\\\"\\\"\\\"\\n        registry = FlowRegistry(no_env_fallback=True)\\n        graph = MagicMock()\\n        graph.context = {}\\n        meta = self._make_meta(\\\"test-flow\\\")\\n        registry.add(graph, meta)\\n        assert graph.context.get(\\\"no_env_fallback\\\") is True\\n\\n    def test_registry_default_does_not_stamp_no_env_fallback(self):\\n        \\\"\\\"\\\"FlowRegistry() (default) must NOT set no_env_fallback on the graph context.\\\"\\\"\\\"\\n        registry = FlowRegistry()\\n        graph = MagicMock()\\n        graph.context = {}\\n        meta = self._make_meta(\\\"test-flow\\\")\\n        registry.add(graph, meta)\\n        assert \\\"no_env_fallback\\\" not in graph.context\\n\\n    def test_registry_no_env_fallback_stamps_context_on_overwrite(self):\\n        \\\"\\\"\\\"Stamp must also be applied when overwrite=True.\\\"\\\"\\\"\\n        registry = FlowRegistry(no_env_fallback=True)\\n        first_graph = MagicMock()\\n        first_graph.context = {}\\n        meta = self._make_meta(\\\"test-flow\\\")\\n        registry.add(first_graph, meta)\\n\\n        replacement_graph = MagicMock()\\n        replacement_graph.context = {}\\n        registry.add(replacement_graph, meta, overwrite=True)\\n        assert replacement_graph.context.get(\\\"no_env_fallback\\\") is True\\n\\n    def test_registry_get_misses_to_store(self):\\n        \\\"\\\"\\\"Cache miss must load from store, cache result, and return it.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        raw = {\\n            \\\"name\\\": \\\"Stored Flow\\\",\\n            \\\"description\\\": \\\"from disk\\\",\\n            \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            \\\"id\\\": \\\"flow-from-store\\\",\\n        }\\n\\n        class StubStore:\\n            def write(self, flow_id, flow_json):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"flow-from-store\\\" else None\\n\\n            def delete(self, _flow_id):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"flow-from-store\\\"]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        registry = FlowRegistry(store=StubStore())\\n\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            result = registry.get(\\\"flow-from-store\\\")\\n\\n        assert result is not None\\n        graph, meta = result\\n        assert graph is mock_graph\\n        assert meta.id == \\\"flow-from-store\\\"\\n        assert meta.title == \\\"Stored Flow\\\"\\n        # second call must hit in-memory cache, not store\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", side_effect=AssertionError(\\\"should use cache\\\")):\\n            registry.get(\\\"flow-from-store\\\")\\n\\n    def test_list_metas_caches_store_reads(self):\\n        \\\"\\\"\\\"list_metas() must not re-read a store file it already parsed in a prior call.\\\"\\\"\\\"\\n        raw = {\\\"name\\\": \\\"Cached\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"id\\\": \\\"cached-id\\\"}\\n        read_count = 0\\n\\n        class CountingStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, _flow_id):\\n                nonlocal read_count\\n                read_count += 1\\n                return raw\\n\\n            def delete(self, *_a):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"cached-id\\\"]\\n\\n        registry = FlowRegistry(store=CountingStore())\\n        registry.list_metas()  # first call \u2014 reads from store, populates cache\\n        registry.list_metas()  # second call \u2014 must use cache, not read again\\n        assert read_count == 1, f\\\"Expected 1 store read, got {read_count}\\\"\\n\\n    def test_list_metas_cache_invalidated_after_remove(self):\\n        \\\"\\\"\\\"After remove(), a subsequent list_metas() must not serve stale cached metadata.\\\"\\\"\\\"\\n        raw = {\\\"name\\\": \\\"Gone\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"id\\\": \\\"gone-id\\\"}\\n\\n        class MemStore:\\n            def __init__(self):\\n                self._data = {\\\"gone-id\\\": raw}\\n\\n            def write(self, fid, v):\\n                self._data[fid] = v\\n\\n            def read(self, fid):\\n                return self._data.get(fid)\\n\\n            def delete(self, fid):\\n                return bool(self._data.pop(fid, None))\\n\\n            def list_ids(self):\\n                return list(self._data)\\n\\n        registry = FlowRegistry(store=MemStore())\\n        metas = registry.list_metas()\\n        assert any(m.id == \\\"gone-id\\\" for m in metas)\\n\\n        registry.remove(\\\"gone-id\\\")\\n        metas_after = registry.list_metas()\\n        assert not any(m.id == \\\"gone-id\\\" for m in metas_after)\\n\\n    def test_list_metas_skips_store_sourced_flow_deleted_by_other_worker(self):\\n        \\\"\\\"\\\"list_metas() must not return a flow that another worker deleted from the store.\\\"\\\"\\\"\\n        raw = {\\\"name\\\": \\\"Shared\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"id\\\": \\\"shared-id\\\"}\\n\\n        class DeletableStore:\\n            is_persistent = True\\n\\n            def __init__(self):\\n                self._data = {\\\"shared-id\\\": raw}\\n\\n            def write(self, fid, v):\\n                self._data[fid] = v\\n\\n            def read(self, fid):\\n                return self._data.get(fid)\\n\\n            def delete(self, fid):\\n                return bool(self._data.pop(fid, None))\\n\\n            def list_ids(self):\\n                return list(self._data)\\n\\n            def exists(self, fid):\\n                return fid in self._data\\n\\n        store = DeletableStore()\\n        registry = FlowRegistry(store=store)\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        # Load flow into registry via get() \u2014 simulates warm_from_store on startup\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            registry.get(\\\"shared-id\\\")\\n\\n        assert any(m.id == \\\"shared-id\\\" for m in registry.list_metas())\\n\\n        # Another worker deletes the file \u2014 simulate by removing from the store directly\\n        store.delete(\\\"shared-id\\\")\\n\\n        # list_metas() must now exclude the stale entry\\n        assert not any(m.id == \\\"shared-id\\\" for m in registry.list_metas())\\n\\n    def test_get_evicts_stale_store_sourced_flow(self):\\n        \\\"\\\"\\\"get() must return None and evict the entry when the store file was deleted by another worker.\\\"\\\"\\\"\\n        raw = {\\\"name\\\": \\\"Evictable\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"id\\\": \\\"evict-id\\\"}\\n\\n        class DeletableStore:\\n            is_persistent = True\\n\\n            def __init__(self):\\n                self._data = {\\\"evict-id\\\": raw}\\n\\n            def write(self, fid, v):\\n                self._data[fid] = v\\n\\n            def read(self, fid):\\n                return self._data.get(fid)\\n\\n            def delete(self, fid):\\n                return bool(self._data.pop(fid, None))\\n\\n            def list_ids(self):\\n                return list(self._data)\\n\\n        store = DeletableStore()\\n        registry = FlowRegistry(store=store)\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            assert registry.get(\\\"evict-id\\\") is not None\\n\\n        # Another worker deletes the file\\n        store.delete(\\\"evict-id\\\")\\n\\n        # get() must now return None and evict the stale entry\\n        assert registry.get(\\\"evict-id\\\") is None\\n        assert \\\"evict-id\\\" not in registry._flows\\n\\n    def test_registry_get_uses_json_id_over_filename_stem(self):\\n        \\\"\\\"\\\"When JSON has a different id than the filename stem, meta.id uses the JSON id.\\n\\n        The flow is reachable by that UUID (not just the filename stem).\\n        \\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        raw = {\\n            \\\"name\\\": \\\"prompt_one\\\",\\n            \\\"id\\\": json_uuid,\\n            \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n        }\\n\\n        class StubStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"prompt_one\\\" else None\\n\\n            def delete(self, *_a):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"prompt_one\\\"]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        registry = FlowRegistry(store=StubStore())\\n\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            result = registry.get(\\\"prompt_one\\\")\\n\\n        assert result is not None\\n        _, meta = result\\n        assert meta.id == json_uuid, \\\"meta.id must come from the JSON id field\\\"\\n        assert meta.title == \\\"prompt_one\\\"\\n        # flow must also be reachable by UUID without hitting the store again\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", side_effect=AssertionError(\\\"should use cache\\\")):\\n            by_uuid = registry.get(json_uuid)\\n        assert by_uuid is not None\\n\\n    def test_list_metas_deduplicates_filename_and_json_id_aliases(self):\\n        \\\"\\\"\\\"list_metas() must not return the same flow twice when it's cached under two keys.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        raw = {\\\"name\\\": \\\"prompt_one\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n\\n        class StubStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"prompt_one\\\" else None\\n\\n            def delete(self, *_a):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"prompt_one\\\"]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        registry = FlowRegistry(store=StubStore())\\n\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            registry.get(\\\"prompt_one\\\")\\n\\n        metas = registry.list_metas()\\n        assert len(metas) == 1, f\\\"expected 1 meta, got {len(metas)}: {[m.id for m in metas]}\\\"\\n        assert metas[0].id == json_uuid\\n\\n    def test_overwrite_aliased_flow_removes_old_store_file_and_alias(self):\\n        \\\"\\\"\\\"add(overwrite=True) on a pre-placed aliased flow must delete the old file.\\n\\n        Clears the stem alias so new workers don't reconstruct the stale version.\\n        \\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        old_raw = {\\\"name\\\": \\\"prompt_one\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        deleted: list[str] = []\\n        store_data: dict[str, dict] = {\\\"prompt_one\\\": old_raw}\\n\\n        class StubStore:\\n            def write(self, fid, data):\\n                store_data[fid] = data\\n\\n            def read(self, fid):\\n                return store_data.get(fid)\\n\\n            def delete(self, fid):\\n                existed = fid in store_data\\n                store_data.pop(fid, None)\\n                deleted.append(fid)\\n                return existed\\n\\n            def list_ids(self):\\n                return list(store_data)\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        registry = FlowRegistry(store=StubStore())\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            registry.get(\\\"prompt_one\\\")  # loads and aliases\\n\\n        # Overwrite via add() (simulating POST /flows/upload/ with replace=True)\\n        new_graph = MagicMock()\\n        new_graph.context = {}\\n        new_meta = FlowMeta(id=json_uuid, relative_path=\\\"<uploaded>\\\", title=\\\"prompt_one v2\\\", description=None)\\n        new_raw = {\\\"name\\\": \\\"prompt_one v2\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        registry.add(new_graph, new_meta, overwrite=True, raw_json=new_raw)\\n\\n        # Old file must be deleted; new file written under the UUID\\n        assert \\\"prompt_one\\\" in deleted, \\\"old store file must be deleted on overwrite\\\"\\n        assert json_uuid in store_data, \\\"new file must be written under the UUID\\\"\\n        assert \\\"prompt_one\\\" not in store_data, \\\"old file must be gone from store\\\"\\n\\n        # In-memory: stem alias gone, UUID key has new graph\\n        assert registry.get(json_uuid)[0] is new_graph\\n        assert \\\"prompt_one\\\" not in registry._flows, \\\"stem alias must be cleared\\\"\\n\\n        # Simulate a new worker: fresh registry warms from store\\n        new_registry = FlowRegistry(store=StubStore())\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=new_graph):\\n            new_registry.warm_from_store()\\n        result = new_registry.get(json_uuid)\\n        assert result is not None\\n        assert result[1].title == \\\"prompt_one v2\\\", \\\"new worker must serve the updated flow, not the old one\\\"\\n\\n    def test_overwrite_unaliased_preplaced_flow_removes_old_store_file(self):\\n        \\\"\\\"\\\"add(overwrite=True) must delete a pre-placed file even when get() never ran.\\n\\n        The replace path in upload_flow skips registry.get(), so _store_keys never\\n        records the stem alias and old_store_key is None. add() must still scan the\\n        store for a file whose JSON \\\"id\\\" matches and delete it \u2014 otherwise both\\n        prompt_one.json and {uuid}.json survive.\\n        \\\"\\\"\\\"\\n        from unittest.mock import MagicMock\\n\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        old_raw = {\\\"name\\\": \\\"prompt_one\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        deleted: list[str] = []\\n        store_data: dict[str, dict] = {\\\"prompt_one\\\": old_raw}\\n\\n        class StubStore:\\n            is_persistent = True\\n\\n            def write(self, fid, data):\\n                store_data[fid] = data\\n\\n            def read(self, fid):\\n                return store_data.get(fid)\\n\\n            def delete(self, fid):\\n                existed = fid in store_data\\n                store_data.pop(fid, None)\\n                deleted.append(fid)\\n                return existed\\n\\n            def list_ids(self):\\n                return list(store_data)\\n\\n        registry = FlowRegistry(store=StubStore())\\n\\n        # No registry.get(\\\"prompt_one\\\") here \u2014 the replace path skips it, so the\\n        # stem alias is never recorded.\\n        new_graph = MagicMock()\\n        new_graph.context = {}\\n        new_meta = FlowMeta(id=json_uuid, relative_path=\\\"<uploaded>\\\", title=\\\"prompt_one v2\\\", description=None)\\n        new_raw = {\\\"name\\\": \\\"prompt_one v2\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        registry.add(new_graph, new_meta, overwrite=True, raw_json=new_raw)\\n\\n        assert \\\"prompt_one\\\" in deleted, \\\"stale stem file must be deleted on overwrite\\\"\\n        assert json_uuid in store_data, \\\"new file must be written under the UUID\\\"\\n        assert \\\"prompt_one\\\" not in store_data, \\\"old stem file must be gone \u2014 no duplicate\\\"\\n        assert list(store_data) == [json_uuid], \\\"store must hold a single file\\\"\\n\\n    def test_registry_add_with_raw_json_writes_to_store(self):\\n        \\\"\\\"\\\"add(raw_json=...) must write to store.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock\\n\\n        written = {}\\n\\n        class SpyStore:\\n            def write(self, flow_id, flow_json):\\n                written[flow_id] = flow_json\\n\\n            def read(self, _flow_id):\\n                return None\\n\\n            def delete(self, _flow_id):\\n                return False\\n\\n            def list_ids(self):\\n                return []\\n\\n        registry = FlowRegistry(store=SpyStore())\\n        graph = MagicMock()\\n        graph.context = {}\\n        meta = self._make_meta(\\\"flow-1\\\")\\n        raw = {\\\"name\\\": \\\"flow-1\\\", \\\"data\\\": {}}\\n        registry.add(graph, meta, raw_json=raw)\\n\\n        assert written == {\\\"flow-1\\\": raw}\\n\\n    def test_registry_add_without_raw_json_skips_store(self):\\n        \\\"\\\"\\\"add() without raw_json must NOT write to store.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock\\n\\n        written = {}\\n\\n        class SpyStore:\\n            def write(self, flow_id, flow_json):\\n                written[flow_id] = flow_json\\n\\n            def read(self, _flow_id):\\n                return None\\n\\n            def delete(self, _flow_id):\\n                return False\\n\\n            def list_ids(self):\\n                return []\\n\\n        registry = FlowRegistry(store=SpyStore())\\n        graph = MagicMock()\\n        graph.context = {}\\n        registry.add(graph, self._make_meta(\\\"flow-1\\\"))\\n        assert written == {}\\n\\n    def test_registry_remove_deletes_from_store(self):\\n        \\\"\\\"\\\"remove() must delete from store in addition to clearing in-memory.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock\\n\\n        deleted = []\\n\\n        class SpyStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, *_a):\\n                return None\\n\\n            def delete(self, flow_id):\\n                deleted.append(flow_id)\\n                return True\\n\\n            def list_ids(self):\\n                return []\\n\\n        registry = FlowRegistry(store=SpyStore())\\n        graph = MagicMock()\\n        graph.context = {}\\n        registry.add(graph, self._make_meta(\\\"flow-1\\\"))\\n        registry.remove(\\\"flow-1\\\")\\n        assert \\\"flow-1\\\" in deleted\\n\\n    def test_list_metas_includes_store_only_flows(self):\\n        \\\"\\\"\\\"list_metas() must include flows that are in the store but not yet cached.\\\"\\\"\\\"\\n        raw = {\\\"name\\\": \\\"Store-Only Flow\\\", \\\"description\\\": None, \\\"data\\\": {}, \\\"id\\\": \\\"store-only\\\"}\\n\\n        class StubStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"store-only\\\" else None\\n\\n            def delete(self, *_a):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"store-only\\\"]\\n\\n        registry = FlowRegistry(store=StubStore())\\n        metas = registry.list_metas()\\n        assert any(m.id == \\\"store-only\\\" for m in metas)\\n        assert any(m.title == \\\"Store-Only Flow\\\" for m in metas)\\n\\n    def test_registry_remove_store_only_flow_returns_true(self):\\n        \\\"\\\"\\\"remove() must return True when the flow is in the store but not in memory.\\\"\\\"\\\"\\n        raw = {\\\"name\\\": \\\"Store-Only\\\", \\\"data\\\": {}, \\\"id\\\": \\\"store-only\\\"}\\n\\n        class StubStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"store-only\\\" else None\\n\\n            def delete(self, flow_id):\\n                return flow_id == \\\"store-only\\\"\\n\\n            def list_ids(self):\\n                return [\\\"store-only\\\"]\\n\\n        registry = FlowRegistry(store=StubStore())\\n        # do NOT call registry.get() first \u2014 flow is store-only, not in memory\\n        result = registry.remove(\\\"store-only\\\")\\n        assert result is True\\n\\n    def test_remove_by_uuid_clears_both_aliases(self):\\n        \\\"\\\"\\\"remove(uuid) must remove the filename-stem alias too, not leave a dangling entry.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        raw = {\\\"name\\\": \\\"prompt_one\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n\\n        class StubStore:\\n            def __init__(self):\\n                self._deleted: set[str] = set()\\n\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, fid):\\n                return None if fid in self._deleted else (raw if fid == \\\"prompt_one\\\" else None)\\n\\n            def delete(self, fid):\\n                existed = fid == \\\"prompt_one\\\" and fid not in self._deleted\\n                self._deleted.add(fid)\\n                return existed\\n\\n            def list_ids(self):\\n                return [f for f in [\\\"prompt_one\\\"] if f not in self._deleted]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        registry = FlowRegistry(store=StubStore())\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            registry.get(\\\"prompt_one\\\")\\n\\n        result = registry.remove(json_uuid)\\n        assert result is True\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", side_effect=AssertionError(\\\"store already deleted\\\")):\\n            assert registry.get(json_uuid) is None, \\\"flow must be gone by UUID\\\"\\n            assert registry.get(\\\"prompt_one\\\") is None, \\\"filename alias must be cleared too\\\"\\n        assert registry.list_metas() == [], \\\"list_metas must not return the removed flow\\\"\\n\\n    def test_remove_by_stem_clears_both_aliases(self):\\n        \\\"\\\"\\\"remove(stem) must remove the UUID alias too, not leave a dangling entry.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        raw = {\\\"name\\\": \\\"prompt_one\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n\\n        deleted: list[str] = []\\n\\n        class StubStore:\\n            def __init__(self):\\n                self._deleted: set[str] = set()\\n\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, fid):\\n                return None if fid in self._deleted else (raw if fid == \\\"prompt_one\\\" else None)\\n\\n            def delete(self, fid):\\n                deleted.append(fid)\\n                existed = fid == \\\"prompt_one\\\" and fid not in self._deleted\\n                self._deleted.add(fid)\\n                return existed\\n\\n            def list_ids(self):\\n                return [f for f in [\\\"prompt_one\\\"] if f not in self._deleted]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        registry = FlowRegistry(store=StubStore())\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            registry.get(\\\"prompt_one\\\")\\n\\n        result = registry.remove(\\\"prompt_one\\\")\\n        assert result is True\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", side_effect=AssertionError(\\\"store already deleted\\\")):\\n            assert registry.get(json_uuid) is None, \\\"UUID alias must be cleared too\\\"\\n            assert registry.get(\\\"prompt_one\\\") is None, \\\"stem must be gone\\\"\\n        assert \\\"prompt_one\\\" in deleted, \\\"must delete the correct file (by stem, not UUID)\\\"\\n\\n    def test_remove_deletes_both_stem_and_uuid_files_for_cross_worker_propagation(self):\\n        \\\"\\\"\\\"remove() must delete both the stem file and the UUID file.\\n\\n        Any worker, regardless of which key its stale check uses, must see the deletion.\\n\\n        Scenario: flow-dir has my-flow.json (pre-placed) and {uuid}.json (written by add()).\\n        Worker A deletes by UUID; Worker B cached by stem alias.  Both files must be gone.\\n        \\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        raw = {\\\"name\\\": \\\"my-flow\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n\\n        store_data: dict[str, dict] = {\\n            \\\"my-flow\\\": raw,  # pre-placed stem file\\n            json_uuid: raw,  # UUID file written by add() at startup\\n        }\\n        deleted: list[str] = []\\n\\n        class DualKeyStore:\\n            is_persistent = True  # required to trigger the stem-scan path in remove()\\n\\n            def write(self, fid, v):\\n                store_data[fid] = v\\n\\n            def read(self, fid):\\n                return store_data.get(fid)\\n\\n            def delete(self, fid):\\n                deleted.append(fid)\\n                existed = fid in store_data\\n                store_data.pop(fid, None)\\n                return existed\\n\\n            def list_ids(self):\\n                return list(store_data)\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        registry = FlowRegistry(store=DualKeyStore())\\n\\n        # Worker A: loaded via UUID (no stem alias created)\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            registry.get(json_uuid)\\n\\n        # Stale-check key for Worker A is UUID (no alias)\\n        assert registry._store_keys.get(json_uuid) is None\\n\\n        # Worker A deletes by UUID\\n        result = registry.remove(json_uuid)\\n        assert result is True\\n\\n        # Both the UUID file AND the stem file must be deleted\\n        assert json_uuid in deleted, \\\"UUID-keyed file must be deleted\\\"\\n        assert \\\"my-flow\\\" in deleted, (\\n            \\\"stem-keyed file must also be deleted so workers with stem alias don't pass stale check\\\"\\n        )\\n        assert not store_data, \\\"store must be empty after remove()\\\"\\n\\n    def test_list_metas_uncached_store_flow_uses_json_id(self):\\n        \\\"\\\"\\\"list_metas() uncached branch must use the JSON id, not the filename stem.\\\"\\\"\\\"\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        raw = {\\\"name\\\": \\\"prompt_one\\\", \\\"id\\\": json_uuid, \\\"data\\\": {}}\\n\\n        class StubStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"prompt_one\\\" else None\\n\\n            def delete(self, *_a):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"prompt_one\\\"]\\n\\n        registry = FlowRegistry(store=StubStore())\\n        # Do NOT call registry.get() first \u2014 flow stays uncached in the store branch\\n        metas = registry.list_metas()\\n        assert len(metas) == 1\\n        assert metas[0].id == json_uuid, \\\"uncached list_metas must use JSON id, not filename stem\\\"\\n\\n    def test_len_not_double_counted_with_aliases(self):\\n        \\\"\\\"\\\"len() must return 1 when a flow is cached under both filename stem and JSON UUID.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        raw = {\\\"name\\\": \\\"prompt_one\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n\\n        class StubStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"prompt_one\\\" else None\\n\\n            def delete(self, *_a):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"prompt_one\\\"]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        registry = FlowRegistry(store=StubStore())\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            registry.get(\\\"prompt_one\\\")\\n\\n        assert len(registry) == 1, f\\\"expected 1 distinct flow, got {len(registry)}\\\"\\n\\n    def test_warm_from_store_makes_flow_reachable_by_json_uuid(self):\\n        \\\"\\\"\\\"After warm_from_store(), a pre-placed file must be reachable by its JSON UUID.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        json_uuid = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        raw = {\\\"name\\\": \\\"prompt_one\\\", \\\"id\\\": json_uuid, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n\\n        class StubStore:\\n            def write(self, *_a):\\n                pass\\n\\n            def read(self, flow_id):\\n                return raw if flow_id == \\\"prompt_one\\\" else None\\n\\n            def delete(self, *_a):\\n                return False\\n\\n            def list_ids(self):\\n                return [\\\"prompt_one\\\"]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        registry = FlowRegistry(store=StubStore())\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            registry.warm_from_store()\\n\\n        result = registry.get(json_uuid)\\n        assert result is not None, \\\"flow must be reachable by its JSON UUID after warm_from_store()\\\"\\n        _, meta = result\\n        assert meta.id == json_uuid\\n\\n\\ndef _fake_request(expected_api_key=None):\\n    \\\"\\\"\\\"Minimal stand-in for a Starlette Request exposing ``app.state.expected_api_key``.\\n\\n    ``None`` mimics an app whose key was not snapshotted at startup, so verify_api_key falls\\n    back to the one-time live read; a value mimics the startup-snapshotted (cached) key.\\n    \\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    return SimpleNamespace(app=SimpleNamespace(state=SimpleNamespace(expected_api_key=expected_api_key)))\\n\\n\\nclass TestSecurityFunctions:\\n    \\\"\\\"\\\"Test security-related functions.\\\"\\\"\\\"\\n\\n    def test_verify_api_key_with_query_param(self):\\n        \\\"\\\"\\\"Test API key verification with query parameter.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key-123\\\"}):  # pragma: allowlist secret\\n            with patch(\\\"lfx.cli.serve_app.secrets.compare_digest\\\", wraps=secrets.compare_digest) as compare_digest:\\n                result = verify_api_key(_fake_request(), \\\"test-key-123\\\", None)\\n            assert result == \\\"test-key-123\\\"\\n            compare_digest.assert_called_once_with(b\\\"test-key-123\\\", b\\\"test-key-123\\\")\\n\\n    def test_verify_api_key_with_header_param(self):\\n        \\\"\\\"\\\"Test API key verification with header parameter.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key-123\\\"}):  # pragma: allowlist secret\\n            result = verify_api_key(_fake_request(), None, \\\"test-key-123\\\")\\n            assert result == \\\"test-key-123\\\"\\n\\n    def test_verify_api_key_query_param_takes_precedence(self):\\n        \\\"\\\"\\\"Query param is checked first; when both are provided the query param value is used.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key-123\\\"}):  # pragma: allowlist secret\\n            result = verify_api_key(_fake_request(), \\\"test-key-123\\\", \\\"wrong-key\\\")\\n            assert result == \\\"test-key-123\\\"\\n\\n    def test_verify_api_key_missing(self):\\n        \\\"\\\"\\\"Test error when no API key is provided.\\\"\\\"\\\"\\n        with pytest.raises(HTTPException) as exc_info:\\n            verify_api_key(_fake_request(), None, None)\\n        assert exc_info.value.status_code == 401\\n        assert exc_info.value.detail == \\\"API key required\\\"\\n\\n    def test_verify_api_key_invalid(self):\\n        \\\"\\\"\\\"Test error when API key is invalid.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"correct-key\\\"}):  # pragma: allowlist secret\\n            with pytest.raises(HTTPException) as exc_info:\\n                verify_api_key(_fake_request(), \\\"wrong-key\\\", None)\\n            assert exc_info.value.status_code == 401\\n            assert exc_info.value.detail == \\\"Invalid API key\\\"\\n\\n    def test_verify_api_key_env_not_set(self):\\n        \\\"\\\"\\\"Test error when environment variable is not set.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {}, clear=True):\\n            with pytest.raises(HTTPException) as exc_info:\\n                verify_api_key(_fake_request(), \\\"any-key\\\", None)\\n            assert exc_info.value.status_code == 500\\n            assert \\\"LANGFLOW_API_KEY environment variable is not set\\\" in exc_info.value.detail\\n\\n    def test_verify_api_key_uses_cached_startup_key_not_live_env(self):\\n        \\\"\\\"\\\"When the key was snapshotted at startup, auth uses it and never reads live os.environ.\\n\\n        This is the hardening for the --reset-environ race: even a flow that overwrites the auth\\n        key in os.environ cannot flip the auth decision, because verify_api_key reads the cached\\n        value, not the live environment.\\n        \\\"\\\"\\\"\\n        req = _fake_request(expected_api_key=\\\"cached-key\\\")  # pragma: allowlist secret\\n        # Empty env would 500 if the check read live; the cached key makes it succeed.\\n        with patch.dict(os.environ, {}, clear=True):\\n            assert verify_api_key(req, \\\"cached-key\\\", None) == \\\"cached-key\\\"\\n        # A live env value cannot override the cached key.\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"tampered\\\"}):  # pragma: allowlist secret\\n            with pytest.raises(HTTPException) as exc_info:\\n                verify_api_key(req, \\\"tampered\\\", None)\\n            assert exc_info.value.status_code == 401\\n\\n\\nclass TestCreateServeApp:\\n    \\\"\\\"\\\"Test FastAPI app creation.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def simple_chat_json(self):\\n        test_data_dir = Path(__file__).parent.parent.parent / \\\"data\\\"\\n        json_path = test_data_dir / \\\"simple_chat_no_llm.json\\\"\\n        with json_path.open() as f:\\n            return json.load(f)\\n\\n    @pytest.fixture\\n    def real_graph(self, simple_chat_json):\\n        return Graph.from_payload(simple_chat_json, flow_id=\\\"00000000-0000-0000-0000-000000000001\\\")\\n\\n    @pytest.fixture\\n    def mock_meta(self):\\n        return FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=\\\"A test flow\\\",\\n        )\\n\\n    def test_create_multi_serve_app_single_flow(self, real_graph, mock_meta):\\n        from lfx.cli.serve_app import FlowRegistry\\n\\n        registry = FlowRegistry()\\n        registry.add(real_graph, mock_meta)\\n\\n        app = create_multi_serve_app(registry=registry)\\n\\n        # FastAPI >=0.137 mounts included routers (the /api/v2 workflow router) as lazy\\n        # `_IncludedRouter` wrappers with no `.path`; skip them \u2014 this asserts the\\n        # directly-mounted serve paths only.\\n        routes = [route.path for route in app.routes if hasattr(route, \\\"path\\\")]\\n        assert \\\"/health\\\" in routes\\n        assert \\\"/flows\\\" in routes\\n        assert \\\"/flows/{flow_id}/run\\\" in routes\\n        assert \\\"/flows/{flow_id}/info\\\" in routes\\n        assert \\\"/flows/upload/\\\" in routes\\n\\n    def test_create_multi_serve_app_multiple_flows(self, real_graph, mock_meta, simple_chat_json):\\n        from lfx.cli.serve_app import FlowRegistry\\n\\n        graph2 = Graph.from_payload(simple_chat_json, flow_id=\\\"flow-2\\\")\\n        meta2 = FlowMeta(id=\\\"flow-2\\\", relative_path=\\\"flow2.json\\\", title=\\\"Flow 2\\\", description=None)\\n\\n        registry = FlowRegistry()\\n        registry.add(real_graph, mock_meta)\\n        registry.add(graph2, meta2)\\n\\n        app = create_multi_serve_app(registry=registry)\\n\\n        # FastAPI >=0.137 mounts included routers (the /api/v2 workflow router) as lazy\\n        # `_IncludedRouter` wrappers with no `.path`; skip them \u2014 this asserts the\\n        # directly-mounted serve paths only.\\n        routes = [route.path for route in app.routes if hasattr(route, \\\"path\\\")]\\n        assert \\\"/flows/{flow_id}/run\\\" in routes\\n        assert \\\"/flows/{flow_id}/info\\\" in routes\\n        # Single dispatch route covers all flow IDs \u2014 no per-flow routes\\n        assert \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\" not in routes\\n        assert \\\"/flows/flow-2/run\\\" not in routes\\n\\n\\nclass TestCreateServeAppFactory:\\n    \\\"\\\"\\\"Tests for the create_serve_app() ASGI factory used by uvicorn workers.\\\"\\\"\\\"\\n\\n    def test_create_serve_app_empty_start(self):\\n        \\\"\\\"\\\"create_serve_app() with no env vars produces an empty but functional app.\\\"\\\"\\\"\\n        import os\\n        from unittest.mock import patch\\n\\n        from lfx.cli.serve_app import create_serve_app\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}, clear=False):  # pragma: allowlist secret\\n            # Remove startup paths env if present\\n            env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"LFX_SERVE_\\\")}\\n            with patch.dict(os.environ, env, clear=True):\\n                os.environ[\\\"LANGFLOW_API_KEY\\\"] = \\\"test-key\\\"  # pragma: allowlist secret\\n                app = create_serve_app()\\n\\n        # FastAPI >=0.137 mounts included routers (the /api/v2 workflow router) as lazy\\n        # `_IncludedRouter` wrappers with no `.path`; skip them \u2014 this asserts the\\n        # directly-mounted serve paths only.\\n        routes = [r.path for r in app.routes if hasattr(r, \\\"path\\\")]\\n        assert \\\"/health\\\" in routes\\n        assert \\\"/flows\\\" in routes\\n        assert \\\"/flows/upload/\\\" in routes\\n\\n    def test_create_serve_app_startup_paths_cleaned_from_env_by_caller(self):\\n        \\\"\\\"\\\"LFX_SERVE_STARTUP_PATHS must be consumed by create_serve_app() but not deleted.\\n\\n        Cleanup is the caller's (serve_command's) responsibility via the prefix sweep.\\n        \\\"\\\"\\\"\\n        import json\\n        import os\\n        from unittest.mock import patch\\n\\n        from lfx.cli.serve_app import _SERVE_STARTUP_PATHS_ENV, create_serve_app\\n\\n        env_override = {\\n            \\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            _SERVE_STARTUP_PATHS_ENV: json.dumps([]),\\n        }\\n\\n        with patch.dict(os.environ, env_override):\\n            # Empty paths list \u2192 falls through to else branch\\n            app = create_serve_app()\\n            # The env var should still be present during the call (not deleted inside)\\n            assert _SERVE_STARTUP_PATHS_ENV in os.environ\\n\\n        assert len(app.state.registry) == 0\\n\\n    def test_create_serve_app_with_flow_dir_skips_startup_paths_uses_store(self, tmp_path):\\n        \\\"\\\"\\\"When flow_dir is set, create_serve_app() must NOT call build_registry_from_paths.\\n\\n        The parent already persisted startup flows to the store; workers load them via\\n        warm_from_store() only.  Re-reading files would cause redundant store writes and\\n        is wrong when the startup files are .py (can't be stored).\\n        \\\"\\\"\\\"\\n        import json\\n        import os\\n        from unittest.mock import MagicMock, patch\\n\\n        from lfx.cli.flow_store import FilesystemFlowStore\\n        from lfx.cli.serve_app import (\\n            _SERVE_FLOW_DIR_ENV,\\n            _SERVE_STARTUP_PATHS_ENV,\\n            create_serve_app,\\n        )\\n\\n        # Pre-place a flow in the store (simulating what the parent did)\\n        store = FilesystemFlowStore(tmp_path)\\n        raw = {\\\"name\\\": \\\"Pre-persisted\\\", \\\"description\\\": None, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"id\\\": \\\"pre-id\\\"}\\n        store.write(\\\"pre-id\\\", raw)\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        env_override = {\\n            \\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            _SERVE_FLOW_DIR_ENV: str(tmp_path),\\n            # Startup paths IS set but must be IGNORED since flow_dir is present\\n            _SERVE_STARTUP_PATHS_ENV: json.dumps([\\\"/some/startup/flow.json\\\"]),\\n        }\\n\\n        with (\\n            patch.dict(os.environ, env_override),\\n            patch(\\\"lfx.cli.commands.build_registry_from_paths\\\") as mock_brfp,\\n            patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph),\\n        ):\\n            app = create_serve_app()\\n\\n        # build_registry_from_paths must NOT have been called \u2014 flow_dir means use the store\\n        mock_brfp.assert_not_called()\\n        # Flow from the store must be in the registry (loaded via warm_from_store)\\n        assert len(app.state.registry) == 1\\n\\n    def test_create_serve_app_without_flow_dir_loads_startup_paths_from_files(self, tmp_path):\\n        \\\"\\\"\\\"When flow_dir is NOT set, create_serve_app() must load startup flows from file paths.\\\"\\\"\\\"\\n        import json\\n        import os\\n        from pathlib import Path\\n        from unittest.mock import MagicMock, patch\\n\\n        from lfx.cli.serve_app import _SERVE_STARTUP_PATHS_ENV, create_serve_app\\n\\n        src = Path(__file__).parent.parent.parent / \\\"data\\\" / \\\"simple_chat_no_llm.json\\\"\\n        flow_path = tmp_path / \\\"flow.json\\\"\\n        flow_path.write_bytes(src.read_bytes())\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n\\n        env_override = {\\n            \\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            # No LFX_SERVE_FLOW_DIR \u2014 no flow_dir\\n            _SERVE_STARTUP_PATHS_ENV: json.dumps([str(flow_path)]),\\n        }\\n\\n        with (\\n            patch.dict(os.environ, env_override),\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph),\\n        ):\\n            app = create_serve_app()\\n\\n        assert len(app.state.registry) == 1, \\\"worker must have loaded the startup flow from the file path\\\"\\n\\n    def test_create_serve_app_startup_path_load_error_propagates(self, tmp_path):\\n        \\\"\\\"\\\"create_serve_app() must raise (not swallow) if a startup flow file fails to load.\\n\\n        This exercises the ThreadPoolExecutor path: the coroutine raises inside the\\n        thread, and the exception must propagate back to the worker process so the\\n        worker fails fast instead of silently starting with an empty registry.\\n        \\\"\\\"\\\"\\n        import json\\n        import os\\n\\n        from lfx.cli.serve_app import _SERVE_STARTUP_PATHS_ENV, create_serve_app\\n\\n        bad_file = tmp_path / \\\"bad_flow.json\\\"\\n        bad_file.write_text(json.dumps({\\\"nodes\\\": [], \\\"edges\\\": []}))\\n\\n        env_override = {\\n            \\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            _SERVE_STARTUP_PATHS_ENV: json.dumps([str(bad_file)]),\\n            # No LFX_SERVE_FLOW_DIR \u2014 triggers the ThreadPoolExecutor path\\n        }\\n\\n        with (\\n            patch.dict(os.environ, env_override),\\n            patch(\\n                \\\"lfx.cli.commands.load_flow_from_json\\\",\\n                side_effect=ValueError(\\\"corrupt flow\\\"),\\n            ),\\n            pytest.raises(Exception, match=\\\"corrupt flow\\\"),\\n        ):\\n            create_serve_app()\\n\\n\\nclass TestServeAppEndpoints:\\n    \\\"\\\"\\\"Test the FastAPI endpoints.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def simple_chat_json(self):\\n        \\\"\\\"\\\"Load the simple chat JSON test data.\\\"\\\"\\\"\\n        test_data_dir = Path(__file__).parent.parent.parent / \\\"data\\\"\\n        json_path = test_data_dir / \\\"simple_chat_no_llm.json\\\"\\n        with json_path.open() as f:\\n            return json.load(f)\\n\\n    @pytest.fixture\\n    def real_graph_with_async(self, simple_chat_json):\\n        \\\"\\\"\\\"Create a real graph with async execution capability.\\\"\\\"\\\"\\n        # Create graph using from_payload with real test data\\n        graph = Graph.from_payload(simple_chat_json, flow_id=\\\"00000000-0000-0000-0000-000000000001\\\")\\n\\n        # Store original async_start to restore later if needed\\n        original_async_start = graph.async_start\\n\\n        # Mock successful execution with real ResultData\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            # Create real Message and ResultData objects\\n            message = Message(text=\\\"Hello from flow\\\")\\n            result_data = ResultData(\\n                results={\\\"message\\\": message},\\n                component_display_name=\\\"Chat Output\\\",\\n                component_id=graph.vertices[-1].id if graph.vertices else \\\"test-123\\\",\\n            )\\n\\n            # Create a mock result that mimics the real structure\\n            mock_result = MagicMock()\\n            mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n            mock_result.vertex.id = result_data.component_id\\n            mock_result.result_dict = result_data\\n\\n            yield mock_result\\n\\n        graph.async_start = mock_async_start\\n        graph._original_async_start = original_async_start\\n\\n        return graph\\n\\n    @pytest.fixture\\n    def app_client(self, real_graph_with_async, monkeypatch):\\n        \\\"\\\"\\\"Create test client with single flow app.\\\"\\\"\\\"\\n        from lfx.services.deps import get_settings_service\\n\\n        meta = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=\\\"A test flow\\\",\\n        )\\n\\n        registry = FlowRegistry()\\n        registry.add(real_graph_with_async, meta)\\n\\n        app = create_multi_serve_app(\\n            registry=registry,\\n        )\\n\\n        monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n        # Set up test API key\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}):  # pragma: allowlist secret\\n            return TestClient(app)\\n\\n    @pytest.fixture\\n    def multi_flow_client(self, real_graph_with_async, simple_chat_json, monkeypatch):\\n        \\\"\\\"\\\"Create test client with multiple flows.\\\"\\\"\\\"\\n        from lfx.services.deps import get_settings_service\\n\\n        # Create second real graph using the same JSON structure\\n        graph2 = Graph.from_payload(simple_chat_json, flow_id=\\\"flow-2\\\")\\n\\n        async def mock_async_start2(inputs, **kwargs):  # noqa: ARG001\\n            # Return empty results for this test\\n            yield MagicMock(outputs=[])\\n\\n        graph2.async_start = mock_async_start2\\n\\n        meta1 = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=\\\"First flow\\\",\\n        )\\n        meta2 = FlowMeta(\\n            id=\\\"flow-2\\\",\\n            relative_path=\\\"flow2.json\\\",\\n            title=\\\"Flow 2\\\",\\n            description=\\\"Second flow\\\",\\n        )\\n\\n        registry = FlowRegistry()\\n        registry.add(real_graph_with_async, meta1)\\n        registry.add(graph2, meta2)\\n\\n        app = create_multi_serve_app(\\n            registry=registry,\\n        )\\n\\n        monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}):  # pragma: allowlist secret\\n            return TestClient(app)\\n\\n    def test_health_endpoint(self, app_client):\\n        \\\"\\\"\\\"Test health check endpoint.\\\"\\\"\\\"\\n        response = app_client.get(\\\"/health\\\")\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"status\\\"] == \\\"healthy\\\"\\n        assert data[\\\"flow_count\\\"] == 1\\n\\n    def test_run_endpoint_success(self, app_client):\\n        \\\"\\\"\\\"Test successful flow execution.\\\"\\\"\\\"\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\"}\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.common.extract_structured_result\\\") as mock_extract,\\n        ):\\n            mock_extract.return_value = {\\n                \\\"result\\\": \\\"Hello from flow\\\",\\n                \\\"success\\\": True,\\n                \\\"type\\\": \\\"message\\\",\\n                \\\"component\\\": \\\"TestComponent\\\",\\n            }\\n            response = app_client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\", json=request_data, headers=headers\\n            )\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"result\\\"] == \\\"Hello from flow\\\"\\n        assert data[\\\"success\\\"] is True\\n        assert data[\\\"type\\\"] == \\\"message\\\"\\n\\n    def test_run_endpoint_no_auth(self, app_client):\\n        \\\"\\\"\\\"Test flow execution without authentication.\\\"\\\"\\\"\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\"}\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}):  # pragma: allowlist secret\\n            response = app_client.post(\\\"/flows/00000000-0000-0000-0000-000000000001/run\\\", json=request_data)\\n\\n        assert response.status_code == 401\\n        assert response.json()[\\\"detail\\\"] == \\\"API key required\\\"\\n\\n    def test_run_endpoint_wrong_auth(self, app_client):\\n        \\\"\\\"\\\"Test flow execution with wrong API key.\\\"\\\"\\\"\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\"}\\n        headers = {\\\"x-api-key\\\": \\\"wrong-key\\\"}\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}):  # pragma: allowlist secret\\n            response = app_client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\", json=request_data, headers=headers\\n            )\\n\\n        assert response.status_code == 401\\n        assert response.json()[\\\"detail\\\"] == \\\"Invalid API key\\\"\\n\\n    def test_run_endpoint_blocks_custom_components_when_disabled(\\n        self,\\n        real_graph_with_async,\\n    ):\\n        \\\"\\\"\\\"Test that /run fails closed before execution when custom components are blocked.\\\"\\\"\\\"\\n        real_graph_with_async.raw_graph_data = _blocked_raw_graph()\\n        meta = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=\\\"A test flow\\\",\\n        )\\n        registry = FlowRegistry()\\n        registry.add(real_graph_with_async, meta)\\n        app = create_multi_serve_app(\\n            registry=registry,\\n        )\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\n                \\\"lfx.services.deps.get_settings_service\\\",\\n                return_value=_make_settings_service(allow_custom_components=False),\\n            ),\\n            patch(\\n                \\\"lfx.utils.flow_validation.ensure_component_hash_lookups_loaded\\\",\\n                new=AsyncMock(return_value={\\\"ChatInput\\\": {hashlib.sha256(b\\\"known\\\").hexdigest()[:12]}}),\\n            ),\\n            patch.object(\\n                component_cache,\\n                \\\"type_to_current_hash\\\",\\n                {\\\"ChatInput\\\": {hashlib.sha256(b\\\"known\\\").hexdigest()[:12]}},\\n            ),\\n            patch(\\n                \\\"lfx.cli.serve_app.execute_graph_with_capture\\\",\\n                new=AsyncMock(return_value=([], \\\"\\\")),\\n            ) as mock_execute,\\n        ):\\n            client = TestClient(app)\\n            response = client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\",\\n                json={\\\"input_value\\\": \\\"Test input\\\"},\\n                headers=headers,\\n            )\\n\\n        assert response.status_code == 500\\n        assert response.json()[\\\"success\\\"] is False\\n        assert \\\"custom components are not allowed\\\" in response.json()[\\\"result\\\"]\\n        mock_execute.assert_not_called()\\n\\n    def test_run_endpoint_query_auth(self, app_client):\\n        \\\"\\\"\\\"Test flow execution with query parameter authentication.\\\"\\\"\\\"\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\"}\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.common.extract_structured_result\\\") as mock_extract,\\n        ):\\n            mock_extract.return_value = {\\n                \\\"result\\\": \\\"Hello from flow\\\",\\n                \\\"success\\\": True,\\n                \\\"type\\\": \\\"message\\\",\\n                \\\"component\\\": \\\"TestComponent\\\",\\n            }\\n            response = app_client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run?x-api-key=test-api-key\\\", json=request_data\\n            )\\n\\n        assert response.status_code == 200\\n        assert response.json()[\\\"success\\\"] is True\\n\\n    def test_run_endpoint_execution_error(self, app_client):\\n        \\\"\\\"\\\"Test flow execution with error.\\\"\\\"\\\"\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\"}\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        # Mock execute_graph_with_capture to raise an error\\n        async def mock_execute_error(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            msg = \\\"Flow execution failed\\\"\\n            raise RuntimeError(msg)\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_error),\\n        ):\\n            response = app_client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\", json=request_data, headers=headers\\n            )\\n\\n        assert response.status_code == 500\\n        data = response.json()\\n        assert data[\\\"success\\\"] is False\\n        assert data[\\\"result\\\"] == \\\"Flow execution failed: Flow execution failed\\\"\\n        assert data[\\\"type\\\"] == \\\"error\\\"\\n        assert \\\"ERROR: Flow execution failed\\\" in data[\\\"logs\\\"]\\n\\n    def test_run_endpoint_no_results(self, app_client):\\n        \\\"\\\"\\\"Test flow execution with no results.\\\"\\\"\\\"\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\"}\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        # Mock execute_graph_with_capture to return empty results\\n        async def mock_execute_empty(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            return [], \\\"\\\"  # Empty results and logs\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_empty),\\n        ):\\n            response = app_client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\", json=request_data, headers=headers\\n            )\\n\\n        assert response.status_code == 500\\n        data = response.json()\\n        assert data[\\\"result\\\"] == \\\"No response generated\\\"\\n        assert data[\\\"success\\\"] is False\\n        assert data[\\\"type\\\"] == \\\"error\\\"\\n\\n    def test_run_endpoint_forwards_session_id(self, app_client):\\n        \\\"\\\"\\\"The /run endpoint must forward session_id from RunRequest to the executor.\\\"\\\"\\\"\\n        captured: dict = {}\\n\\n        async def mock_execute_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"session_id\\\"] = session_id\\n            return [], \\\"\\\"\\n\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\", \\\"session_id\\\": \\\"my-conversation\\\"}\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_capture),\\n        ):\\n            app_client.post(\\\"/flows/00000000-0000-0000-0000-000000000001/run\\\", json=request_data, headers=headers)\\n\\n        assert captured[\\\"session_id\\\"] == \\\"my-conversation\\\"\\n\\n    def test_stream_endpoint_forwards_session_id(self, app_client):\\n        \\\"\\\"\\\"The /stream endpoint must forward session_id from StreamRequest to the executor.\\\"\\\"\\\"\\n        captured: dict = {}\\n\\n        async def mock_execute_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"session_id\\\"] = session_id\\n            return [], \\\"\\\"\\n\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\", \\\"session_id\\\": \\\"my-stream-conversation\\\"}\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_capture),\\n            # Drain the streaming response so the background task completes before we assert.\\n            app_client.stream(\\n                \\\"POST\\\", \\\"/flows/00000000-0000-0000-0000-000000000001/stream\\\", json=request_data, headers=headers\\n            ) as response,\\n        ):\\n            assert response.status_code == 200\\n            for _ in response.iter_bytes():\\n                pass\\n\\n        assert captured[\\\"session_id\\\"] == \\\"my-stream-conversation\\\"\\n\\n    def test_list_flows_endpoint(self, multi_flow_client):\\n        \\\"\\\"\\\"Test listing flows in multi-flow mode.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}):  # pragma: allowlist secret\\n            response = multi_flow_client.get(\\\"/flows\\\", headers={\\\"x-api-key\\\": \\\"test-api-key\\\"})\\n\\n        assert response.status_code == 200\\n        flows = response.json()\\n        assert len(flows) == 2\\n        assert any(f[\\\"id\\\"] == \\\"00000000-0000-0000-0000-000000000001\\\" for f in flows)\\n        assert any(f[\\\"id\\\"] == \\\"flow-2\\\" for f in flows)\\n\\n    def test_flow_info_endpoint(self, multi_flow_client):\\n        \\\"\\\"\\\"Test getting flow info in multi-flow mode.\\\"\\\"\\\"\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}):  # pragma: allowlist secret\\n            response = multi_flow_client.get(\\\"/flows/00000000-0000-0000-0000-000000000001/info\\\", headers=headers)\\n\\n        assert response.status_code == 200\\n        info = response.json()\\n        assert info[\\\"id\\\"] == \\\"00000000-0000-0000-0000-000000000001\\\"\\n        assert info[\\\"title\\\"] == \\\"Test Flow\\\"\\n        assert info[\\\"description\\\"] == \\\"First flow\\\"\\n\\n    def test_flow_run_endpoint_multi_flow(self, multi_flow_client):\\n        \\\"\\\"\\\"Test running specific flow in multi-flow mode.\\\"\\\"\\\"\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\"}\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.common.extract_structured_result\\\") as mock_extract,\\n        ):\\n            mock_extract.return_value = {\\n                \\\"result\\\": \\\"Hello from flow\\\",\\n                \\\"success\\\": True,\\n                \\\"type\\\": \\\"message\\\",\\n                \\\"component\\\": \\\"TestComponent\\\",\\n            }\\n            response = multi_flow_client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\", json=request_data, headers=headers\\n            )\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"result\\\"] == \\\"Hello from flow\\\"\\n        assert data[\\\"success\\\"] is True\\n\\n    def test_invalid_request_body(self, app_client):\\n        \\\"\\\"\\\"Test with invalid request body.\\\"\\\"\\\"\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}):  # pragma: allowlist secret\\n            response = app_client.post(\\\"/flows/00000000-0000-0000-0000-000000000001/run\\\", json={}, headers=headers)\\n\\n        assert response.status_code == 422  # Validation error\\n\\n    def test_run_endpoint_injects_global_vars_into_context(self, real_graph_with_async, monkeypatch):\\n        \\\"\\\"\\\"global_vars in RunRequest must appear in graph_copy.context['request_variables'].\\\"\\\"\\\"\\n        from lfx.services.deps import get_settings_service\\n\\n        meta = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=None,\\n        )\\n        registry = FlowRegistry()\\n        registry.add(real_graph_with_async, meta)\\n        app = create_multi_serve_app(registry=registry)\\n        monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n        captured: dict = {}\\n\\n        async def mock_execute_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"request_variables\\\"] = dict(graph.context.get(\\\"request_variables\\\") or {})\\n            return [], \\\"\\\"\\n\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_capture),\\n            TestClient(app) as client,\\n        ):\\n            client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\",\\n                json={\\n                    \\\"input_value\\\": \\\"hello\\\",\\n                    \\\"global_vars\\\": {\\\"MY_API_KEY\\\": \\\"secret-value\\\"},  # pragma: allowlist secret\\n                },\\n                headers=headers,\\n            )\\n\\n        assert captured[\\\"request_variables\\\"] == {\\\"MY_API_KEY\\\": \\\"secret-value\\\"}  # pragma: allowlist secret\\n\\n    def test_run_endpoint_global_vars_do_not_mutate_registry_graph(self, real_graph_with_async, monkeypatch):\\n        \\\"\\\"\\\"global_vars must only be set on the deepcopy; the registry's original graph must be unchanged.\\\"\\\"\\\"\\n        from lfx.services.deps import get_settings_service\\n\\n        meta = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=None,\\n        )\\n        registry = FlowRegistry()\\n        registry.add(real_graph_with_async, meta)\\n        app = create_multi_serve_app(registry=registry)\\n        monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n        async def mock_execute_noop(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            return [], \\\"\\\"\\n\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_noop),\\n            TestClient(app) as client,\\n        ):\\n            client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\",\\n                json={\\n                    \\\"input_value\\\": \\\"hello\\\",\\n                    \\\"global_vars\\\": {\\\"MY_API_KEY\\\": \\\"secret-value\\\"},  # pragma: allowlist secret\\n                },\\n                headers=headers,\\n            )\\n\\n        original_graph = registry.get(\\\"00000000-0000-0000-0000-000000000001\\\")[0]\\n        rv = original_graph.context.get(\\\"request_variables\\\") or {}\\n        assert \\\"MY_API_KEY\\\" not in rv\\n\\n    def test_run_endpoint_preserves_no_env_fallback_after_deepcopy(self, real_graph_with_async, monkeypatch):\\n        \\\"\\\"\\\"no_env_fallback must reach the executed graph_copy, not only the registry graph.\\n\\n        deepcopy() drops graph.context, so run_flow must re-apply the stamp after the copy.\\n        \\\"\\\"\\\"\\n        from lfx.services.deps import get_settings_service\\n\\n        meta = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=None,\\n        )\\n        registry = FlowRegistry(no_env_fallback=True)\\n        registry.add(real_graph_with_async, meta)\\n        app = create_multi_serve_app(registry=registry)\\n        monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n        captured: dict = {}\\n\\n        async def mock_execute_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"no_env_fallback\\\"] = graph.context.get(\\\"no_env_fallback\\\")\\n            return [], \\\"\\\"\\n\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_capture),\\n            TestClient(app) as client,\\n        ):\\n            client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\",\\n                json={\\\"input_value\\\": \\\"hello\\\"},\\n                headers=headers,\\n            )\\n\\n        assert captured[\\\"no_env_fallback\\\"] is True\\n\\n    def test_stream_endpoint_preserves_no_env_fallback_after_deepcopy(self, real_graph_with_async, monkeypatch):\\n        \\\"\\\"\\\"no_env_fallback must reach the executed graph_copy on the stream path too.\\\"\\\"\\\"\\n        from lfx.services.deps import get_settings_service\\n\\n        meta = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=None,\\n        )\\n        registry = FlowRegistry(no_env_fallback=True)\\n        registry.add(real_graph_with_async, meta)\\n        app = create_multi_serve_app(registry=registry)\\n        monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n        captured: dict = {}\\n\\n        async def mock_execute_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"no_env_fallback\\\"] = graph.context.get(\\\"no_env_fallback\\\")\\n            return [], \\\"\\\"\\n\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_capture),\\n            TestClient(app) as client,\\n            client.stream(\\n                \\\"POST\\\",\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/stream\\\",\\n                json={\\\"input_value\\\": \\\"hello\\\"},\\n                headers=headers,\\n            ) as response,\\n        ):\\n            assert response.status_code == 200\\n            for _ in response.iter_bytes():\\n                pass\\n\\n        assert captured[\\\"no_env_fallback\\\"] is True\\n\\n    def test_stream_endpoint_injects_global_vars_into_context(self, real_graph_with_async, monkeypatch):\\n        \\\"\\\"\\\"global_vars in StreamRequest must appear in graph_copy.context['request_variables'].\\\"\\\"\\\"\\n        from lfx.services.deps import get_settings_service\\n\\n        meta = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=None,\\n        )\\n        registry = FlowRegistry()\\n        registry.add(real_graph_with_async, meta)\\n        app = create_multi_serve_app(registry=registry)\\n        monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n        captured: dict = {}\\n\\n        async def mock_execute_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"request_variables\\\"] = dict(graph.context.get(\\\"request_variables\\\") or {})\\n            return [], \\\"\\\"\\n\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_capture),\\n            TestClient(app) as client,\\n            client.stream(\\n                \\\"POST\\\",\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/stream\\\",\\n                json={\\n                    \\\"input_value\\\": \\\"hello\\\",\\n                    \\\"global_vars\\\": {\\\"STREAM_KEY\\\": \\\"stream-secret\\\"},  # pragma: allowlist secret\\n                },\\n                headers=headers,\\n            ) as response,\\n        ):\\n            assert response.status_code == 200\\n            for _ in response.iter_bytes():\\n                pass\\n\\n        assert captured[\\\"request_variables\\\"] == {\\\"STREAM_KEY\\\": \\\"stream-secret\\\"}  # pragma: allowlist secret\\n\\n    def test_stream_endpoint_no_global_vars_leaves_context_clean(self, real_graph_with_async, monkeypatch):\\n        \\\"\\\"\\\"Omitting global_vars must not create request_variables in the graph context.\\\"\\\"\\\"\\n        from lfx.services.deps import get_settings_service\\n\\n        meta = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=None,\\n        )\\n        registry = FlowRegistry()\\n        registry.add(real_graph_with_async, meta)\\n        app = create_multi_serve_app(registry=registry)\\n        monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n        captured: dict = {}\\n\\n        async def mock_execute_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"request_variables\\\"] = graph.context.get(\\\"request_variables\\\")\\n            return [], \\\"\\\"\\n\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_capture),\\n            TestClient(app) as client,\\n            client.stream(\\n                \\\"POST\\\",\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/stream\\\",\\n                json={\\\"input_value\\\": \\\"hello\\\"},  # no global_vars key\\n                headers=headers,\\n            ) as response,\\n        ):\\n            assert response.status_code == 200\\n            for _ in response.iter_bytes():\\n                pass\\n\\n        assert not captured.get(\\\"request_variables\\\")\\n\\n    def test_stream_endpoint_global_vars_do_not_mutate_registry_graph(self, real_graph_with_async, monkeypatch):\\n        \\\"\\\"\\\"global_vars must only be set on the deepcopy; the registry's original graph must be unchanged.\\\"\\\"\\\"\\n        from lfx.services.deps import get_settings_service\\n\\n        meta = FlowMeta(\\n            id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            relative_path=\\\"test.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=None,\\n        )\\n        registry = FlowRegistry()\\n        registry.add(real_graph_with_async, meta)\\n        app = create_multi_serve_app(registry=registry)\\n        monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n        async def mock_execute_noop(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            return [], \\\"\\\"\\n\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute_noop),\\n            TestClient(app) as client,\\n            client.stream(\\n                \\\"POST\\\",\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/stream\\\",\\n                json={\\n                    \\\"input_value\\\": \\\"hello\\\",\\n                    \\\"global_vars\\\": {\\\"STREAM_KEY\\\": \\\"stream-secret\\\"},  # pragma: allowlist secret\\n                },\\n                headers=headers,\\n            ) as response,\\n        ):\\n            assert response.status_code == 200\\n            for _ in response.iter_bytes():\\n                pass\\n\\n        original_graph = registry.get(\\\"00000000-0000-0000-0000-000000000001\\\")[0]\\n        rv = original_graph.context.get(\\\"request_variables\\\") or {}\\n        assert \\\"STREAM_KEY\\\" not in rv\\n\\n    def test_flow_execution_with_message_output(self, app_client, real_graph_with_async):\\n        \\\"\\\"\\\"Test flow execution with message-type output.\\\"\\\"\\\"\\n\\n        # Create a real message output scenario\\n        async def mock_async_start_message(inputs, **kwargs):  # noqa: ARG001\\n            # Create real Message and ResultData objects\\n            message = Message(text=\\\"Message output\\\")\\n            result_data = ResultData(\\n                results={\\\"message\\\": message}, component_display_name=\\\"Chat Output\\\", component_id=\\\"test-123\\\"\\n            )\\n\\n            # Create result structure\\n            mock_result = MagicMock()\\n            mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n            mock_result.vertex.id = \\\"test-123\\\"\\n            mock_result.result_dict = result_data\\n            # Add message attribute for backwards compatibility\\n            mock_result.message = message\\n\\n            yield mock_result\\n\\n        real_graph_with_async.async_start = mock_async_start_message\\n\\n        request_data = {\\\"input_value\\\": \\\"Test input\\\"}\\n        headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.common.extract_structured_result\\\") as mock_extract,\\n        ):\\n            mock_extract.return_value = {\\n                \\\"result\\\": \\\"Message output\\\",\\n                \\\"success\\\": True,\\n                \\\"type\\\": \\\"message\\\",\\n                \\\"component\\\": \\\"Chat Output\\\",\\n            }\\n            response = app_client.post(\\n                \\\"/flows/00000000-0000-0000-0000-000000000001/run\\\", json=request_data, headers=headers\\n            )\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"result\\\"] == \\\"Message output\\\"\\n        assert data[\\\"success\\\"] is True\\n\\n\\nclass TestUploadEndpoint:\\n    \\\"\\\"\\\"Tests for POST /flows/upload/.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def app_with_empty_registry(self):\\n        from lfx.cli.serve_app import FlowRegistry\\n\\n        registry = FlowRegistry()\\n        app = create_multi_serve_app(registry=registry)\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}):  # pragma: allowlist secret\\n            yield TestClient(app)\\n\\n    @pytest.fixture\\n    def valid_flow_data(self):\\n        test_data_dir = Path(__file__).parent.parent.parent / \\\"data\\\"\\n        json_path = test_data_dir / \\\"simple_chat_no_llm.json\\\"\\n        with json_path.open() as f:\\n            return json.load(f)\\n\\n    @pytest.fixture\\n    def full_export(self):\\n        \\\"\\\"\\\"Full Langflow export JSON as exported from the UI (name/data/... at top level).\\n\\n        This is what a user sends when they run:\\n            curl -X POST .../flows/upload/ -d @myflow.json\\n\\n        body.data will be {\\\"edges\\\": [...], \\\"nodes\\\": [...]} \u2014 the inner graph with NO\\n        nested \\\"data\\\" key. A regression that calls load_flow_from_json(body.data)\\n        raises KeyError('data') here; the correct call passes body.model_dump(...).\\n        \\\"\\\"\\\"\\n        test_data_dir = Path(__file__).parent.parent.parent / \\\"data\\\"\\n        json_path = test_data_dir / \\\"simple_chat_no_llm.json\\\"\\n        with json_path.open() as f:\\n            return json.load(f)\\n\\n    def test_upload_full_export_as_body(self, app_with_empty_registry, full_export):\\n        \\\"\\\"\\\"Uploading a Langflow export JSON directly as the body must succeed.\\n\\n        Regression test: load_flow_from_json must be called with the full model dict\\n        (which has a top-level \\\"data\\\" key), not body.data alone (which is just the\\n        inner graph and has no \\\"data\\\" key).\\n        \\\"\\\"\\\"\\n        response = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json=full_export,\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert response.status_code == 201, response.json()\\n        body = response.json()\\n        assert body[\\\"name\\\"] == full_export[\\\"name\\\"]\\n        assert body[\\\"run_url\\\"].startswith(\\\"/flows/\\\")\\n        assert body[\\\"run_url\\\"].endswith(\\\"/run\\\")\\n\\n    def test_upload_valid_flow(self, app_with_empty_registry, valid_flow_data):\\n        response = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"My Uploaded Flow\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert response.status_code == 201\\n        body = response.json()\\n        assert body[\\\"name\\\"] == \\\"My Uploaded Flow\\\"\\n        assert body[\\\"run_url\\\"].startswith(\\\"/flows/\\\")\\n        assert body[\\\"run_url\\\"].endswith(\\\"/run\\\")\\n        assert \\\"id\\\" in body\\n\\n    def test_upload_requires_auth(self, app_with_empty_registry, valid_flow_data):\\n        response = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"Flow\\\", \\\"data\\\": valid_flow_data},\\n        )\\n        assert response.status_code == 401\\n\\n    def test_upload_invalid_flow_data_returns_422(self, app_with_empty_registry):\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", side_effect=ValueError(\\\"bad flow\\\")):\\n            response = app_with_empty_registry.post(\\n                \\\"/flows/upload/\\\",\\n                json={\\\"name\\\": \\\"Bad Flow\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}},\\n                headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n            )\\n        assert response.status_code == 422\\n        assert \\\"bad flow\\\" in response.json()[\\\"detail\\\"]\\n\\n    def test_upload_prepare_failure_returns_422(self, app_with_empty_registry):\\n        mock_graph = MagicMock()\\n        mock_graph.prepare.side_effect = RuntimeError(\\\"prepare failed\\\")\\n        with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n            response = app_with_empty_registry.post(\\n                \\\"/flows/upload/\\\",\\n                json={\\\"name\\\": \\\"Bad Flow\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}},\\n                headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n            )\\n        assert response.status_code == 422\\n        assert \\\"prepare failed\\\" in response.json()[\\\"detail\\\"]\\n\\n    def test_upload_flow_is_immediately_listed(self, app_with_empty_registry, valid_flow_data):\\n        upload_resp = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"Runnable Flow\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert upload_resp.status_code == 201\\n        flow_id = upload_resp.json()[\\\"id\\\"]\\n\\n        list_resp = app_with_empty_registry.get(\\\"/flows\\\", headers={\\\"x-api-key\\\": \\\"test-key\\\"})\\n        assert any(f[\\\"id\\\"] == flow_id for f in list_resp.json())\\n\\n    def test_upload_duplicate_without_replace_returns_409(self, app_with_empty_registry, valid_flow_data):\\n        fixed_id = \\\"aaaabbbb-1111-2222-3333-444455556666\\\"\\n        r1 = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"id\\\": fixed_id, \\\"name\\\": \\\"Flow A\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert r1.status_code == 201\\n\\n        r2 = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"id\\\": fixed_id, \\\"name\\\": \\\"Flow B\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert r2.status_code == 409\\n        assert \\\"already exists\\\" in r2.json()[\\\"detail\\\"]\\n\\n    def test_upload_replace_true_overwrites(self, app_with_empty_registry, valid_flow_data):\\n        fixed_id = \\\"bbbbcccc-1111-2222-3333-444455556666\\\"\\n        r1 = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"id\\\": fixed_id, \\\"name\\\": \\\"Original Name\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert r1.status_code == 201\\n        flow_id = r1.json()[\\\"id\\\"]\\n\\n        r2 = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"id\\\": fixed_id, \\\"name\\\": \\\"Updated Name\\\", \\\"data\\\": valid_flow_data, \\\"replace\\\": True},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert r2.status_code == 201\\n        assert r2.json()[\\\"id\\\"] == flow_id\\n        assert r2.json()[\\\"name\\\"] == \\\"Updated Name\\\"\\n\\n        flows = app_with_empty_registry.get(\\\"/flows\\\", headers={\\\"x-api-key\\\": \\\"test-key\\\"}).json()\\n        ids = [f[\\\"id\\\"] for f in flows]\\n        assert ids.count(flow_id) == 1\\n\\n    def test_upload_with_description(self, app_with_empty_registry, valid_flow_data):\\n        response = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"Flow\\\", \\\"data\\\": valid_flow_data, \\\"description\\\": \\\"my desc\\\"},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert response.status_code == 201\\n        assert response.json()[\\\"description\\\"] == \\\"my desc\\\"\\n\\n    # ------------------------------------------------------------------\\n    # Execution failures return HTTP 500 not HTTP 200\\n    # ------------------------------------------------------------------\\n\\n    def test_run_execution_exception_returns_500(self, app_with_empty_registry, valid_flow_data):\\n        \\\"\\\"\\\"An unhandled exception during graph execution must produce HTTP 500, not 200.\\\"\\\"\\\"\\n        upload = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"Failing Flow\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert upload.status_code == 201\\n        flow_id = upload.json()[\\\"id\\\"]\\n\\n        with patch(\\n            \\\"lfx.cli.serve_app.execute_graph_with_capture\\\",\\n            side_effect=RuntimeError(\\\"boom\\\"),\\n        ):\\n            response = app_with_empty_registry.post(\\n                f\\\"/flows/{flow_id}/run\\\",\\n                json={\\\"input_value\\\": \\\"hi\\\"},\\n                headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n            )\\n\\n        assert response.status_code == 500\\n        body = response.json()\\n        assert body[\\\"success\\\"] is False\\n        assert \\\"boom\\\" in body[\\\"result\\\"]\\n\\n    def test_run_flow_failure_result_returns_500(self, app_with_empty_registry, valid_flow_data):\\n        \\\"\\\"\\\"A flow that returns success=False in its result must also produce HTTP 500.\\\"\\\"\\\"\\n        upload = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"Bad Result Flow\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert upload.status_code == 201\\n        flow_id = upload.json()[\\\"id\\\"]\\n\\n        with (\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", return_value=([], \\\"\\\")),\\n            patch(\\n                \\\"lfx.cli.serve_app.extract_result_data\\\",\\n                return_value={\\\"success\\\": False, \\\"result\\\": \\\"flow failed\\\", \\\"type\\\": \\\"error\\\"},\\n            ),\\n        ):\\n            response = app_with_empty_registry.post(\\n                f\\\"/flows/{flow_id}/run\\\",\\n                json={\\\"input_value\\\": \\\"hi\\\"},\\n                headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n            )\\n\\n        assert response.status_code == 500\\n        body = response.json()\\n        assert body[\\\"success\\\"] is False\\n\\n    # ------------------------------------------------------------------\\n    # GET /flows requires authentication\\n    # ------------------------------------------------------------------\\n\\n    def test_list_flows_requires_auth(self, app_with_empty_registry):\\n        response = app_with_empty_registry.get(\\\"/flows\\\")\\n        assert response.status_code == 401\\n\\n    def test_list_flows_with_auth(self, app_with_empty_registry, valid_flow_data):\\n        upload = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"My Flow\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert upload.status_code == 201\\n\\n        response = app_with_empty_registry.get(\\\"/flows\\\", headers={\\\"x-api-key\\\": \\\"test-key\\\"})\\n        assert response.status_code == 200\\n        assert any(f[\\\"id\\\"] == upload.json()[\\\"id\\\"] for f in response.json())\\n\\n    # ------------------------------------------------------------------\\n    # Runtime flow removal via DELETE /flows/{flow_id}\\n    # ------------------------------------------------------------------\\n\\n    def test_delete_flow_removes_it(self, app_with_empty_registry, valid_flow_data):\\n        upload = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"Temp Flow\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert upload.status_code == 201\\n        flow_id = upload.json()[\\\"id\\\"]\\n\\n        delete_resp = app_with_empty_registry.delete(f\\\"/flows/{flow_id}\\\", headers={\\\"x-api-key\\\": \\\"test-key\\\"})\\n        assert delete_resp.status_code == 204\\n\\n        run_resp = app_with_empty_registry.post(\\n            f\\\"/flows/{flow_id}/run\\\",\\n            json={\\\"input_value\\\": \\\"hi\\\"},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert run_resp.status_code == 404\\n\\n    def test_delete_nonexistent_flow_returns_404(self, app_with_empty_registry):\\n        response = app_with_empty_registry.delete(\\\"/flows/does-not-exist\\\", headers={\\\"x-api-key\\\": \\\"test-key\\\"})\\n        assert response.status_code == 404\\n\\n    def test_delete_flow_requires_auth(self, app_with_empty_registry, valid_flow_data):\\n        upload = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"Flow\\\", \\\"data\\\": valid_flow_data},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        flow_id = upload.json()[\\\"id\\\"]\\n        response = app_with_empty_registry.delete(f\\\"/flows/{flow_id}\\\")\\n        assert response.status_code == 401\\n\\n    # ------------------------------------------------------------------\\n    # body.id must be a valid UUID to prevent path/store injection\\n    # ------------------------------------------------------------------\\n\\n    def test_upload_with_valid_uuid_id(self, app_with_empty_registry, valid_flow_data):\\n        explicit_id = \\\"b0529294-e297-41d1-9303-2c2128b7860a\\\"\\n        response = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"Flow\\\", \\\"data\\\": valid_flow_data, \\\"id\\\": explicit_id},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert response.status_code == 201\\n        assert response.json()[\\\"id\\\"] == explicit_id\\n\\n    def test_upload_with_invalid_id_returns_422(self, app_with_empty_registry, valid_flow_data):\\n        response = app_with_empty_registry.post(\\n            \\\"/flows/upload/\\\",\\n            json={\\\"name\\\": \\\"Flow\\\", \\\"data\\\": valid_flow_data, \\\"id\\\": \\\"not-a-uuid\\\"},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert response.status_code == 422\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_app_log_trace_correlation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d5071ed9ca98301b77d30e85791341cc27d8679d355edbce93562e0de375e6bf\",\"content\":\"\\\"\\\"\\\"Log-to-trace correlation for ``lfx serve``, driven against a real loopback OTLP collector.\\n\\nThe incident walk this exists for: an operator sees a slow or failing flow run in their APM,\\nclicks the trace, and expects the log lines emitted *inside* that run to be sitting there. That\\nonly works if the log records carry the same trace id as the exported span, and nothing in the\\ncode makes that true explicitly -- it falls out of the OTel context, which means it can break\\nsilently. Asserting that the log processor is installed would not catch that; this drives the\\nreal bootstrap, real OTLP exporters, and a real HTTP round trip, then reads the trace id off the\\nprotobuf that actually reached the collector.\\n\\nThe providers are process-global and installed once per process, so the run happens in a\\nsubprocess (same reason as tests/unit/services/telemetry in the langflow tree).\\n\\\"\\\"\\\"\\n\\nimport gzip\\nimport http.server\\nimport os\\nimport subprocess\\nimport sys\\nimport threading\\n\\nimport pytest\\nfrom opentelemetry.proto.collector.logs.v1.logs_service_pb2 import ExportLogsServiceRequest\\nfrom opentelemetry.proto.collector.trace.v1.trace_service_pb2 import ExportTraceServiceRequest\\n\\nFLOW_ID = \\\"00000000-0000-0000-0000-0000000000aa\\\"\\nAPI_KEY = \\\"correlation-probe-key\\\"  # pragma: allowlist secret\\n# Logged from inside a component, so it is emitted while the flow span is the unit of work --\\n# not from the request handler around it.\\nSENTINEL = \\\"component-log-line-emitted-inside-the-flow-run\\\"\\n\\nPROBE = f\\\"\\\"\\\"\\nimport os\\n\\nfrom fastapi.testclient import TestClient\\nfrom lfx.cli.serve_app import FlowMeta, FlowRegistry, create_multi_serve_app\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.graph import Graph\\nfrom lfx.io import MessageInput, Output\\nfrom lfx.log.logger import configure, logger\\nfrom lfx.schema.message import Message\\n\\n\\nclass LoggingComponent(Component):\\n    display_name = \\\"Logging\\\"\\n    inputs = [MessageInput(name=\\\"input_value\\\", display_name=\\\"Input\\\")]\\n    outputs = [Output(name=\\\"message\\\", display_name=\\\"Message\\\", method=\\\"passthrough\\\")]\\n\\n    def passthrough(self) -> Message:\\n        logger.info({SENTINEL!r})\\n        return self.input_value\\n\\n\\nchat_input = ChatInput()\\nlogging_component = LoggingComponent().set(input_value=chat_input.message_response)\\nchat_output = ChatOutput().set(input_value=logging_component.passthrough)\\ngraph = Graph(chat_input, chat_output, flow_id={FLOW_ID!r})\\n\\nconfigure(log_level=\\\"INFO\\\")\\nos.environ[\\\"LANGFLOW_API_KEY\\\"] = {API_KEY!r}\\n\\nregistry = FlowRegistry()\\nregistry.add(graph, FlowMeta(id={FLOW_ID!r}, relative_path=\\\"probe.py\\\", title=\\\"Probe\\\", description=None))\\n# Installs the OTLP providers from the OTEL_* env vars, exactly as a real `lfx serve` worker does.\\napp = create_multi_serve_app(registry=registry)\\n\\n# The context manager runs the lifespan, whose shutdown flushes the OTLP buffers.\\nwith TestClient(app) as client:\\n    response = client.post(\\n        \\\"/flows/{FLOW_ID}/run\\\",\\n        json={{\\\"input_value\\\": \\\"hello\\\"}},\\n        headers={{\\\"x-api-key\\\": {API_KEY!r}}},\\n    )\\n    assert response.status_code == 200, response.text\\n\\nprint(\\\"PROBE_RESULT ok\\\")\\n\\\"\\\"\\\"\\n\\n\\nclass _Collector(http.server.BaseHTTPRequestHandler):\\n    def do_POST(self) -> None:\\n        body = self.rfile.read(int(self.headers.get(\\\"Content-Length\\\", 0)))\\n        if self.headers.get(\\\"Content-Encoding\\\") == \\\"gzip\\\":\\n            body = gzip.decompress(body)\\n        self.server.requests.append((self.path, body))\\n        self.send_response(200)\\n        self.send_header(\\\"Content-Length\\\", \\\"0\\\")\\n        self.end_headers()\\n\\n    def log_message(self, *args) -> None:\\n        pass\\n\\n\\n@pytest.fixture\\ndef collector():\\n    server = http.server.HTTPServer((\\\"127.0.0.1\\\", 0), _Collector)\\n    server.requests = []\\n    thread = threading.Thread(target=server.serve_forever, daemon=True)\\n    thread.start()\\n    yield server\\n    server.shutdown()\\n    server.server_close()\\n    thread.join(timeout=5)\\n\\n\\n@pytest.fixture\\ndef exported(collector, tmp_path):\\n    \\\"\\\"\\\"Run one flow through a real serve app exporting to the collector; return its requests.\\\"\\\"\\\"\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env[\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\"] = f\\\"http://127.0.0.1:{collector.server_address[1]}\\\"\\n    # The sentinel is how this test finds its own log record, and the body boundary withholds\\n    # message bodies from the export by default. This test is about correlation, not about that\\n    # boundary, so ask for bodies explicitly rather than have the discriminator disappear. No-op\\n    # on a build that predates the setting.\\n    env[\\\"LANGFLOW_OTEL_LOG_BODIES\\\"] = \\\"all\\\"\\n    # A file rather than ``python -c``: Component.__init__ reads its own class source with\\n    # inspect.getsource, which has nothing to read for a class defined in a ``-c`` string.\\n    probe = tmp_path / \\\"probe.py\\\"\\n    probe.write_text(PROBE)\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, str(probe)],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=600,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    assert \\\"PROBE_RESULT ok\\\" in completed.stdout, completed.stdout\\n    return collector.requests\\n\\n\\ndef _spans(requests) -> list:\\n    spans = []\\n    for path, body in requests:\\n        if path != \\\"/v1/traces\\\":\\n            continue\\n        request = ExportTraceServiceRequest()\\n        request.ParseFromString(body)\\n        for rs in request.resource_spans:\\n            for ss in rs.scope_spans:\\n                spans.extend(ss.spans)\\n    return spans\\n\\n\\ndef _log_records(requests) -> list:\\n    records = []\\n    for path, body in requests:\\n        if path != \\\"/v1/logs\\\":\\n            continue\\n        request = ExportLogsServiceRequest()\\n        request.ParseFromString(body)\\n        for rl in request.resource_logs:\\n            for sl in rl.scope_logs:\\n                records.extend(sl.log_records)\\n    return records\\n\\n\\ndef test_the_flow_run_exports_a_span(exported):\\n    \\\"\\\"\\\"Precondition for the correlation assertion below: there is a flow span to correlate to.\\\"\\\"\\\"\\n    names = [s.name for s in _spans(exported)]\\n\\n    assert \\\"flow.execute\\\" in names, names\\n\\n\\ndef test_a_log_line_from_the_flow_run_carries_the_flow_span_trace_id(exported):\\n    \\\"\\\"\\\"The pivot from a flow's trace to its logs. Without it the two signals are separate silos.\\\"\\\"\\\"\\n    flow_span = next(s for s in _spans(exported) if s.name == \\\"flow.execute\\\")\\n    matching = [r for r in _log_records(exported) if r.body.string_value == SENTINEL]\\n\\n    assert matching, [r.body.string_value for r in _log_records(exported)]\\n    # A zeroed trace id is what \\\"no active span\\\" looks like on the wire, so it would pass a\\n    # naive equality check against another zeroed one.\\n    assert flow_span.trace_id != b\\\"\\\\x00\\\" * 16\\n    assert matching[0].trace_id == flow_span.trace_id, (\\n        f\\\"log trace_id {matching[0].trace_id.hex()} != span trace_id {flow_span.trace_id.hex()}\\\"\\n    )\\n\\n\\ndef test_the_request_span_shares_that_trace_id_too(exported):\\n    \\\"\\\"\\\"The pivot an operator actually starts from is the failing request, not the flow span.\\n\\n    Correlating the log to ``flow.execute`` alone would still hold if the flow span had started\\n    its own trace, and then the request an operator is looking at in their APM would not lead\\n    to either. Asserting all three share one id is what makes the walk end where it started.\\n    \\\"\\\"\\\"\\n    spans = _spans(exported)\\n    flow_span = next(s for s in spans if s.name == \\\"flow.execute\\\")\\n    # SPAN_KIND_SERVER is 2; the FastAPI instrumentation names it after the route.\\n    server_spans = [s for s in spans if s.kind == 2]\\n    matching = [r for r in _log_records(exported) if r.body.string_value == SENTINEL]\\n\\n    assert server_spans, [s.name for s in spans]\\n    assert matching\\n    assert server_spans[0].trace_id != b\\\"\\\\x00\\\" * 16\\n    assert server_spans[0].trace_id == flow_span.trace_id, (\\n        f\\\"request {server_spans[0].trace_id.hex()} != flow {flow_span.trace_id.hex()}\\\"\\n    )\\n    assert server_spans[0].trace_id == matching[0].trace_id\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_app_streaming.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"13d78f65af1a1f42450ef21c27084815c28dc18acb03d01a9bb7739677f330b6\",\"content\":\"\\\"\\\"\\\"Unit tests for streaming functionality in multi-serve app.\\\"\\\"\\\"\\n\\nimport asyncio\\nimport hashlib\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, patch\\n\\nimport pytest\\nfrom asgi_lifespan import LifespanManager\\nfrom httpx import ASGITransport, AsyncClient\\nfrom lfx.cli.serve_app import FlowMeta, FlowRegistry, StreamRequest, create_multi_serve_app\\nfrom lfx.interface.components import component_cache\\n\\n\\ndef _make_settings_service(*, allow_custom_components: bool = False):\\n    return SimpleNamespace(\\n        settings=SimpleNamespace(\\n            allow_custom_components=allow_custom_components,\\n        )\\n    )\\n\\n\\ndef _blocked_raw_graph() -> dict:\\n    return {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"id\\\": \\\"node-1\\\",\\n                \\\"data\\\": {\\n                    \\\"id\\\": \\\"node-1\\\",\\n                    \\\"type\\\": \\\"TotallyCustom\\\",\\n                    \\\"node\\\": {\\n                        \\\"display_name\\\": \\\"Blocked Node\\\",\\n                        \\\"template\\\": {\\n                            \\\"code\\\": {\\\"value\\\": \\\"print('blocked')\\\"},\\n                        },\\n                    },\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n\\n\\nclass MockNode:\\n    \\\"\\\"\\\"Mock node for testing graph structure.\\\"\\\"\\\"\\n\\n    def __init__(self, node_id: str, node_type: str = \\\"TestComponent\\\", display_name: str | None = None):\\n        self.data = {\\n            \\\"id\\\": node_id,\\n            \\\"type\\\": node_type,\\n            \\\"display_name\\\": display_name or node_type,\\n            \\\"description\\\": f\\\"Mock {node_type} component\\\",\\n            \\\"template\\\": {\\n                \\\"input_field\\\": {\\\"type\\\": \\\"str\\\", \\\"value\\\": \\\"default_value\\\"},\\n                \\\"output_field\\\": {\\\"type\\\": \\\"str\\\", \\\"value\\\": \\\"\\\"},\\n            },\\n        }\\n\\n\\nclass MockEdge:\\n    \\\"\\\"\\\"Mock edge for testing graph structure.\\\"\\\"\\\"\\n\\n    def __init__(self, source: str, target: str):\\n        self.source = source\\n        self.target = target\\n\\n\\nclass MockGraph:\\n    \\\"\\\"\\\"Mock graph for testing.\\\"\\\"\\\"\\n\\n    def __init__(self, nodes=None, edges=None):\\n        self.nodes = nodes or {\\n            \\\"input_node\\\": MockNode(\\\"input_node\\\", \\\"ChatInput\\\", \\\"Chat Input\\\"),\\n            \\\"output_node\\\": MockNode(\\\"output_node\\\", \\\"ChatOutput\\\", \\\"Chat Output\\\"),\\n        }\\n        self.edges = edges or [MockEdge(\\\"input_node\\\", \\\"output_node\\\")]\\n        self.raw_graph_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n\\n\\n@pytest.fixture\\ndef mock_graphs():\\n    \\\"\\\"\\\"Create mock graphs for testing.\\\"\\\"\\\"\\n    return {\\n        \\\"flow1\\\": MockGraph(),\\n        \\\"flow2\\\": MockGraph(\\n            nodes={\\n                \\\"text_input\\\": MockNode(\\\"text_input\\\", \\\"TextInput\\\", \\\"Text Input\\\"),\\n                \\\"processor\\\": MockNode(\\\"processor\\\", \\\"Processor\\\", \\\"Text Processor\\\"),\\n                \\\"text_output\\\": MockNode(\\\"text_output\\\", \\\"TextOutput\\\", \\\"Text Output\\\"),\\n            },\\n            edges=[MockEdge(\\\"text_input\\\", \\\"processor\\\"), MockEdge(\\\"processor\\\", \\\"text_output\\\")],\\n        ),\\n    }\\n\\n\\n@pytest.fixture\\ndef mock_metas():\\n    \\\"\\\"\\\"Create mock metadata for testing.\\\"\\\"\\\"\\n    return {\\n        \\\"flow1\\\": FlowMeta(\\n            id=\\\"flow1\\\", relative_path=\\\"flow1.json\\\", title=\\\"Test Flow 1\\\", description=\\\"A simple test flow for chat\\\"\\n        ),\\n        \\\"flow2\\\": FlowMeta(\\n            id=\\\"flow2\\\", relative_path=\\\"flow2.json\\\", title=\\\"Test Flow 2\\\", description=\\\"A test flow with text processing\\\"\\n        ),\\n    }\\n\\n\\n@pytest.fixture\\ndef multi_serve_app(mock_graphs, mock_metas, monkeypatch):\\n    \\\"\\\"\\\"Create a multi-serve app for testing.\\\"\\\"\\\"\\n    from lfx.services.deps import get_settings_service\\n\\n    # Set required environment variable\\n    monkeypatch.setenv(\\\"LANGFLOW_API_KEY\\\", \\\"test-api-key\\\")\\n    monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n    with patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\") as mock_execute:\\n        # Mock successful execution\\n        mock_execute.return_value = (\\n            [{\\\"result\\\": \\\"Test response\\\", \\\"type\\\": \\\"message\\\"}],\\n            \\\"Execution completed successfully\\\",\\n        )\\n\\n        registry = FlowRegistry()\\n        for flow_id, graph in mock_graphs.items():\\n            registry.add(graph, mock_metas[flow_id])\\n        app = create_multi_serve_app(registry=registry)\\n\\n        # Override the dependency after app creation\\n        def mock_verify_api_key(query_param: str | None = None, header_param: str | None = None) -> str:  # noqa: ARG001\\n            return \\\"test-api-key\\\"\\n\\n        # Import the original dependency\\n        from lfx.cli.serve_app import verify_api_key\\n\\n        app.dependency_overrides[verify_api_key] = mock_verify_api_key\\n\\n        yield app\\n\\n        # Clean up\\n        app.dependency_overrides.clear()\\n\\n\\n@pytest.fixture\\ndef mock_api_key(monkeypatch):\\n    \\\"\\\"\\\"Mock API key for authentication.\\\"\\\"\\\"\\n    # Set the required environment variable\\n    monkeypatch.setenv(\\\"LANGFLOW_API_KEY\\\", \\\"test-api-key\\\")\\n\\n    with patch(\\\"lfx.cli.serve_app.verify_api_key\\\") as mock_verify:\\n        mock_verify.return_value = True\\n        yield \\\"test-api-key\\\"\\n\\n\\nclass TestMultiServeStreaming:\\n    \\\"\\\"\\\"Test cases for multi-serve streaming functionality.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_stream_endpoint_exists(self, multi_serve_app, mock_api_key):\\n        \\\"\\\"\\\"Test that streaming endpoints are properly created.\\\"\\\"\\\"\\n        async with (\\n            LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n            AsyncClient(transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True) as client,\\n        ):\\n            # Test that stream endpoints exist for each flow\\n            response = await client.post(\\n                \\\"/flows/flow1/stream\\\", json={\\\"input_value\\\": \\\"Hello, world!\\\"}, headers={\\\"x-api-key\\\": mock_api_key}\\n            )\\n            # Should not be 404 (endpoint exists)\\n            assert response.status_code != 404\\n\\n    @pytest.mark.asyncio\\n    async def test_stream_basic_functionality(self, multi_serve_app, mock_api_key):\\n        \\\"\\\"\\\"Test basic streaming functionality.\\\"\\\"\\\"\\n        with patch(\\\"lfx.cli.serve_app.run_flow_generator_for_serve\\\") as mock_generator:\\n            # Mock the streaming generator\\n            async def mock_stream_generator(*args, **kwargs):  # noqa: ARG001\\n                event_manager = kwargs.get(\\\"event_manager\\\")\\n                client_consumed_queue = kwargs.get(\\\"client_consumed_queue\\\")\\n                if event_manager:\\n                    event_manager.on_end(data={\\\"result\\\": {\\\"result\\\": \\\"Streamed response\\\", \\\"success\\\": True}})\\n                    if client_consumed_queue:\\n                        await client_consumed_queue.get()\\n                    else:\\n                        msg = \\\"client_consumed_queue is None\\\"\\n                        raise RuntimeError(msg)\\n                    # Send the final None to close the stream\\n                    await event_manager.queue.put((None, None, 0))\\n\\n            mock_generator.side_effect = mock_stream_generator\\n\\n            async with (\\n                LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n                AsyncClient(\\n                    transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True\\n                ) as client,\\n            ):\\n                response = await client.post(\\n                    \\\"/flows/flow1/stream\\\",\\n                    json={\\\"input_value\\\": \\\"Test streaming input\\\"},\\n                    headers={\\\"x-api-key\\\": mock_api_key},\\n                )\\n\\n                # Debug output removed to pass linting\\n\\n                assert response.status_code == 200\\n                assert response.headers[\\\"content-type\\\"] == \\\"text/event-stream; charset=utf-8\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_stream_request_validation(self, multi_serve_app, mock_api_key):\\n        \\\"\\\"\\\"Test StreamRequest model validation.\\\"\\\"\\\"\\n        async with (\\n            LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n            AsyncClient(transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True) as client,\\n        ):\\n            # Test with minimal valid request\\n            response = await client.post(\\n                \\\"/flows/flow1/stream\\\", json={\\\"input_value\\\": \\\"test\\\"}, headers={\\\"x-api-key\\\": mock_api_key}\\n            )\\n            assert response.status_code == 200\\n\\n            # Test with full request\\n            response = await client.post(\\n                \\\"/flows/flow1/stream\\\",\\n                json={\\n                    \\\"input_value\\\": \\\"test input\\\",\\n                    \\\"input_type\\\": \\\"chat\\\",\\n                    \\\"output_type\\\": \\\"chat\\\",\\n                    \\\"session_id\\\": \\\"test-session-123\\\",\\n                    \\\"tweaks\\\": {\\\"component1\\\": {\\\"param1\\\": \\\"value1\\\"}},\\n                },\\n                headers={\\\"x-api-key\\\": mock_api_key},\\n            )\\n            assert response.status_code == 200\\n\\n    @pytest.mark.asyncio\\n    async def test_stream_authentication_required(self, multi_serve_app):\\n        \\\"\\\"\\\"Test that streaming endpoints require authentication.\\\"\\\"\\\"\\n        # Temporarily remove the auth override to test real auth behavior\\n        from lfx.cli.serve_app import verify_api_key\\n\\n        override = multi_serve_app.dependency_overrides.pop(verify_api_key, None)\\n\\n        try:\\n            async with (\\n                LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n                AsyncClient(\\n                    transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True\\n                ) as client,\\n            ):\\n                # Test without API key\\n                response = await client.post(\\\"/flows/flow1/stream\\\", json={\\\"input_value\\\": \\\"test\\\"})\\n                # Should fail authentication\\n                assert response.status_code in [401, 403]\\n        finally:\\n            # Restore the override for other tests\\n            if override:\\n                multi_serve_app.dependency_overrides[verify_api_key] = override\\n\\n    @pytest.mark.asyncio\\n    async def test_stream_flow_not_found(self, multi_serve_app, mock_api_key):\\n        \\\"\\\"\\\"Test streaming with non-existent flow.\\\"\\\"\\\"\\n        async with (\\n            LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n            AsyncClient(transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True) as client,\\n        ):\\n            response = await client.post(\\n                \\\"/flows/nonexistent/stream\\\", json={\\\"input_value\\\": \\\"test\\\"}, headers={\\\"x-api-key\\\": mock_api_key}\\n            )\\n            assert response.status_code == 404\\n\\n    @pytest.mark.asyncio\\n    async def test_stream_error_handling(self, multi_serve_app, mock_api_key):\\n        \\\"\\\"\\\"Test error handling in streaming endpoint.\\\"\\\"\\\"\\n        with patch(\\\"lfx.cli.serve_app.run_flow_generator_for_serve\\\") as mock_generator:\\n            # Mock an error in the generator that properly terminates the stream\\n            async def mock_error_generator(\\n                graph,  # noqa: ARG001\\n                input_request,  # noqa: ARG001\\n                flow_id,  # noqa: ARG001\\n                event_manager,\\n                client_consumed_queue,  # noqa: ARG001\\n                user_id=None,  # noqa: ARG001\\n            ):\\n                try:\\n                    msg = \\\"Test error during streaming\\\"\\n                    raise RuntimeError(msg)\\n                except Exception as e:\\n                    # Properly handle the error like the real function does\\n                    event_manager.on_error(data={\\\"error\\\": str(e)})\\n                finally:\\n                    # Always send termination signal\\n                    import time\\n\\n                    await event_manager.queue.put((None, None, time.time()))\\n\\n            mock_generator.side_effect = mock_error_generator\\n\\n            async with (\\n                LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n                AsyncClient(\\n                    transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True\\n                ) as client,\\n            ):\\n                response = await client.post(\\n                    \\\"/flows/flow1/stream\\\", json={\\\"input_value\\\": \\\"test\\\"}, headers={\\\"x-api-key\\\": mock_api_key}\\n                )\\n\\n                # Should still return 200 but with error stream\\n                assert response.status_code == 200\\n                assert response.headers[\\\"content-type\\\"] == \\\"text/event-stream; charset=utf-8\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_stream_multiple_flows(self, multi_serve_app, mock_api_key):\\n        \\\"\\\"\\\"Test streaming with multiple flows.\\\"\\\"\\\"\\n        async with (\\n            LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n            AsyncClient(transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True) as client,\\n        ):\\n            # Test streaming for flow1\\n            response1 = await client.post(\\n                \\\"/flows/flow1/stream\\\", json={\\\"input_value\\\": \\\"test flow 1\\\"}, headers={\\\"x-api-key\\\": mock_api_key}\\n            )\\n            assert response1.status_code == 200\\n\\n            # Test streaming for flow2\\n            response2 = await client.post(\\n                \\\"/flows/flow2/stream\\\", json={\\\"input_value\\\": \\\"test flow 2\\\"}, headers={\\\"x-api-key\\\": mock_api_key}\\n            )\\n            assert response2.status_code == 200\\n\\n    @pytest.mark.asyncio\\n    async def test_regular_run_endpoint_still_works(self, multi_serve_app, mock_api_key):\\n        \\\"\\\"\\\"Test that regular run endpoints still work alongside streaming.\\\"\\\"\\\"\\n        with patch(\\\"lfx.cli.serve_app.extract_result_data\\\") as mock_extract:\\n            mock_extract.return_value = {\\n                \\\"result\\\": \\\"Regular response\\\",\\n                \\\"success\\\": True,\\n                \\\"type\\\": \\\"message\\\",\\n                \\\"component\\\": \\\"test\\\",\\n            }\\n\\n            async with (\\n                LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n                AsyncClient(\\n                    transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True\\n                ) as client,\\n            ):\\n                response = await client.post(\\n                    \\\"/flows/flow1/run\\\", json={\\\"input_value\\\": \\\"test regular run\\\"}, headers={\\\"x-api-key\\\": mock_api_key}\\n                )\\n\\n                assert response.status_code == 200\\n                assert response.headers[\\\"content-type\\\"] == \\\"application/json\\\"\\n                data = response.json()\\n                assert data[\\\"result\\\"] == \\\"Regular response\\\"\\n                assert data[\\\"success\\\"] is True\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_endpoint(self, multi_serve_app):\\n        \\\"\\\"\\\"Test that the flows listing endpoint works.\\\"\\\"\\\"\\n        async with (\\n            LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n            AsyncClient(transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True) as client,\\n        ):\\n            response = await client.get(\\\"/flows\\\")\\n            assert response.status_code == 200\\n\\n            flows = response.json()\\n            assert len(flows) == 2\\n            assert any(flow[\\\"id\\\"] == \\\"flow1\\\" for flow in flows)\\n            assert any(flow[\\\"id\\\"] == \\\"flow2\\\" for flow in flows)\\n\\n    def test_stream_request_model(self):\\n        \\\"\\\"\\\"Test the StreamRequest model validation.\\\"\\\"\\\"\\n        # Test minimal request\\n        request = StreamRequest(input_value=\\\"test\\\")\\n        assert request.input_value == \\\"test\\\"\\n        assert request.input_type == \\\"chat\\\"  # default\\n        assert request.output_type == \\\"chat\\\"  # default\\n        assert request.session_id is None\\n        assert request.tweaks is None\\n\\n        # Test full request\\n        request = StreamRequest(\\n            input_value=\\\"test input\\\",\\n            input_type=\\\"text\\\",\\n            output_type=\\\"debug\\\",\\n            output_component=\\\"specific_component\\\",\\n            session_id=\\\"session123\\\",\\n            tweaks={\\\"comp1\\\": {\\\"param1\\\": \\\"value1\\\"}},\\n        )\\n        assert request.input_value == \\\"test input\\\"\\n        assert request.input_type == \\\"text\\\"\\n        assert request.output_type == \\\"debug\\\"\\n        assert request.output_component == \\\"specific_component\\\"\\n        assert request.session_id == \\\"session123\\\"\\n        assert request.tweaks == {\\\"comp1\\\": {\\\"param1\\\": \\\"value1\\\"}}\\n\\n    @pytest.mark.asyncio\\n    async def test_concurrent_streaming(self, multi_serve_app, mock_api_key):\\n        \\\"\\\"\\\"Test concurrent streaming requests.\\\"\\\"\\\"\\n        async with (\\n            LifespanManager(multi_serve_app, startup_timeout=None, shutdown_timeout=None) as manager,\\n            AsyncClient(transport=ASGITransport(app=manager.app), base_url=\\\"http://testserver/\\\", http2=True) as client,\\n        ):\\n            # Start multiple concurrent streaming requests\\n            tasks = []\\n            for i in range(3):\\n                task = asyncio.create_task(\\n                    client.post(\\n                        \\\"/flows/flow1/stream\\\",\\n                        json={\\\"input_value\\\": f\\\"concurrent test {i}\\\"},\\n                        headers={\\\"x-api-key\\\": mock_api_key},\\n                    )\\n                )\\n                tasks.append(task)\\n\\n            # Wait for all requests to complete\\n            responses = await asyncio.gather(*tasks)\\n\\n            # All should be successful\\n            for response in responses:\\n                assert response.status_code == 200\\n                assert response.headers[\\\"content-type\\\"] == \\\"text/event-stream; charset=utf-8\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_stream_blocks_custom_components_when_disabled(\\n        self,\\n        mock_graphs,\\n        mock_metas,\\n        monkeypatch,\\n    ):\\n        \\\"\\\"\\\"Test that /stream returns an error stream when validation blocks the flow.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_API_KEY\\\", \\\"test-api-key\\\")\\n        mock_graphs[\\\"flow1\\\"].raw_graph_data = _blocked_raw_graph()\\n\\n        registry = FlowRegistry()\\n        for flow_id, graph in mock_graphs.items():\\n            registry.add(graph, mock_metas[flow_id])\\n        app = create_multi_serve_app(registry=registry)\\n\\n        from lfx.cli.serve_app import verify_api_key\\n\\n        def mock_verify_api_key() -> str:\\n            return \\\"test-api-key\\\"\\n\\n        app.dependency_overrides[verify_api_key] = mock_verify_api_key\\n\\n        async with (\\n            LifespanManager(app, startup_timeout=None, shutdown_timeout=None) as manager,\\n            AsyncClient(\\n                transport=ASGITransport(app=manager.app),\\n                base_url=\\\"http://testserver/\\\",\\n                http2=True,\\n            ) as client,\\n        ):\\n            with (\\n                patch(\\n                    \\\"lfx.services.deps.get_settings_service\\\",\\n                    return_value=_make_settings_service(allow_custom_components=False),\\n                ),\\n                patch(\\n                    \\\"lfx.utils.flow_validation.ensure_component_hash_lookups_loaded\\\",\\n                    new=AsyncMock(return_value={\\\"ChatInput\\\": {hashlib.sha256(b\\\"known\\\").hexdigest()[:12]}}),\\n                ),\\n                patch.object(\\n                    component_cache,\\n                    \\\"type_to_current_hash\\\",\\n                    {\\\"ChatInput\\\": {hashlib.sha256(b\\\"known\\\").hexdigest()[:12]}},\\n                ),\\n                patch(\\n                    \\\"lfx.cli.serve_app.run_flow_generator_for_serve\\\",\\n                    new=AsyncMock(),\\n                ) as mock_run_flow,\\n            ):\\n                response = await client.post(\\n                    \\\"/flows/flow1/stream\\\",\\n                    json={\\\"input_value\\\": \\\"test\\\"},\\n                    headers={\\\"x-api-key\\\": \\\"test-api-key\\\"},\\n                )\\n\\n        assert response.status_code == 200\\n        assert \\\"custom components are not allowed\\\" in response.text\\n        mock_run_flow.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    async def test_stream_setup_error_returns_valid_json(self, mock_graphs, mock_metas, monkeypatch):\\n        \\\"\\\"\\\"Error messages with special characters must not break the SSE JSON payload.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_API_KEY\\\", \\\"test-api-key\\\")\\n\\n        registry = FlowRegistry()\\n        for flow_id, graph in mock_graphs.items():\\n            registry.add(graph, mock_metas[flow_id])\\n        app = create_multi_serve_app(registry=registry)\\n\\n        from lfx.cli.serve_app import verify_api_key\\n\\n        app.dependency_overrides[verify_api_key] = lambda: \\\"test-api-key\\\"\\n\\n        # Exception message contains characters that would break hand-crafted JSON\\n        nasty_message = 'failed: \\\"quotes\\\" and\\\\nnewlines'\\n\\n        async with (\\n            LifespanManager(app, startup_timeout=None, shutdown_timeout=None) as manager,\\n            AsyncClient(\\n                transport=ASGITransport(app=manager.app),\\n                base_url=\\\"http://testserver/\\\",\\n                http2=True,\\n            ) as client,\\n        ):\\n            with patch(\\n                \\\"lfx.cli.serve_app.validate_flow_for_current_settings\\\",\\n                side_effect=RuntimeError(nasty_message),\\n            ):\\n                response = await client.post(\\n                    \\\"/flows/flow1/stream\\\",\\n                    json={\\\"input_value\\\": \\\"test\\\"},\\n                    headers={\\\"x-api-key\\\": \\\"test-api-key\\\"},\\n                )\\n\\n        assert response.status_code == 200\\n        # Strip the SSE framing and parse as JSON \u2014 must not raise\\n        for line in response.text.splitlines():\\n            if line.startswith(\\\"data: \\\"):\\n                import json\\n\\n                payload = json.loads(line[len(\\\"data: \\\") :])\\n                assert payload[\\\"success\\\"] is False\\n                assert nasty_message in payload[\\\"error\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b69007647ff83e054a11e524877dd533b5a27f3051ad3d825bd513b72741f00c\",\"content\":\"\\\"\\\"\\\"Unit tests for serve components without CLI runner dependencies.\\\"\\\"\\\"\\n\\nimport json\\nimport tempfile\\nfrom pathlib import Path\\nfrom unittest.mock import Mock, patch\\n\\nimport pytest\\nimport typer\\nfrom fastapi.testclient import TestClient\\nfrom lfx.cli.common import flow_id_from_path, load_graph_from_path, validate_script_path\\nfrom lfx.cli.serve_app import (\\n    ErrorResponse,\\n    FlowMeta,\\n    FlowRegistry,\\n    RunRequest,\\n    RunResponse,\\n    create_multi_serve_app,\\n)\\nfrom lfx.graph import Graph\\nfrom pydantic import ValidationError\\n\\n\\nclass TestDataModels:\\n    \\\"\\\"\\\"Test Pydantic data models.\\\"\\\"\\\"\\n\\n    def test_flow_meta_model(self):\\n        \\\"\\\"\\\"Test FlowMeta model creation and validation.\\\"\\\"\\\"\\n        meta = FlowMeta(\\n            id=\\\"test-flow-123\\\",\\n            relative_path=\\\"flows/test_flow.json\\\",\\n            title=\\\"Test Flow\\\",\\n            description=\\\"A test flow for unit testing\\\",\\n        )\\n\\n        assert meta.id == \\\"test-flow-123\\\"\\n        assert meta.relative_path == \\\"flows/test_flow.json\\\"\\n        assert meta.title == \\\"Test Flow\\\"\\n        assert meta.description == \\\"A test flow for unit testing\\\"\\n\\n        # Test required fields\\n        with pytest.raises(ValidationError):\\n            FlowMeta()\\n\\n    def test_run_request_model(self):\\n        \\\"\\\"\\\"Test RunRequest model creation and validation.\\\"\\\"\\\"\\n        request = RunRequest(input_value=\\\"Hello, world!\\\")\\n        assert request.input_value == \\\"Hello, world!\\\"\\n\\n        # Test required field\\n        with pytest.raises(ValidationError):\\n            RunRequest()\\n\\n    def test_run_response_model(self):\\n        \\\"\\\"\\\"Test RunResponse model creation and validation.\\\"\\\"\\\"\\n        response = RunResponse(\\n            result=\\\"Processed successfully\\\",\\n            success=True,\\n            logs=\\\"Execution completed\\\",\\n            type=\\\"message\\\",\\n            component=\\\"TestComponent\\\",\\n        )\\n\\n        assert response.result == \\\"Processed successfully\\\"\\n        assert response.success is True\\n        assert response.logs == \\\"Execution completed\\\"\\n        assert response.type == \\\"message\\\"\\n        assert response.component == \\\"TestComponent\\\"\\n\\n    def test_error_response_model(self):\\n        \\\"\\\"\\\"Test ErrorResponse model creation.\\\"\\\"\\\"\\n        error = ErrorResponse(error=\\\"Something went wrong\\\")\\n        assert error.error == \\\"Something went wrong\\\"\\n        assert error.success is False\\n\\n\\nclass TestCommonFunctions:\\n    \\\"\\\"\\\"Test common utility functions.\\\"\\\"\\\"\\n\\n    def test_flow_id_from_path(self, tmp_path):\\n        \\\"\\\"\\\"Test flow ID generation from path.\\\"\\\"\\\"\\n        test_path = tmp_path / \\\"test_flow.json\\\"\\n        root_dir = tmp_path\\n        flow_id = flow_id_from_path(test_path, root_dir)\\n\\n        # Should be a deterministic UUID5\\n        assert isinstance(flow_id, str)\\n        assert len(flow_id.replace(\\\"-\\\", \\\"\\\")) == 32  # UUID without dashes\\n\\n        # Same path should produce same ID\\n        assert flow_id == flow_id_from_path(test_path, root_dir)\\n\\n    def test_validate_script_path_valid(self):\\n        \\\"\\\"\\\"Test script path validation with valid path.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(suffix=\\\".json\\\", delete=False) as tmp:\\n            tmp.write(b'{\\\"test\\\": \\\"data\\\"}')\\n            tmp.flush()\\n\\n            path = Path(tmp.name)\\n\\n            def verbose_print(msg):\\n                pass  # Real function\\n\\n            file_ext, result = validate_script_path(str(path), verbose_print)\\n            assert result == path\\n            assert file_ext == \\\".json\\\"\\n\\n    def test_validate_script_path_invalid(self):\\n        \\\"\\\"\\\"Test script path validation with invalid path.\\\"\\\"\\\"\\n\\n        def verbose_print(msg):\\n            pass  # Real function\\n\\n        with pytest.raises(typer.Exit):\\n            validate_script_path(\\\"/nonexistent/path.json\\\", verbose_print)\\n\\n    @patch(\\\"lfx.cli.common.load_flow_from_json\\\")\\n    @pytest.mark.asyncio\\n    async def test_load_graph_from_path_success(self, mock_load_flow):\\n        \\\"\\\"\\\"Test successful graph loading.\\\"\\\"\\\"\\n        mock_graph = Mock()\\n        mock_load_flow.return_value = mock_graph\\n\\n        with tempfile.NamedTemporaryFile(suffix=\\\".json\\\", delete=False) as tmp:\\n            tmp.write(b'{\\\"test\\\": \\\"flow\\\"}')\\n            tmp.flush()\\n\\n            def verbose_print(msg):\\n                pass  # Real function\\n\\n            graph = await load_graph_from_path(Path(tmp.name), \\\".json\\\", verbose_print, verbose=True)\\n            assert graph == mock_graph\\n            mock_load_flow.assert_called_once_with(Path(tmp.name), disable_logs=False)\\n\\n    @patch(\\\"lfx.cli.common.load_flow_from_json\\\")\\n    @pytest.mark.asyncio\\n    async def test_load_graph_from_path_error(self, mock_load_flow):\\n        \\\"\\\"\\\"Test graph loading with error.\\\"\\\"\\\"\\n        mock_load_flow.side_effect = Exception(\\\"Parse error\\\")\\n\\n        with tempfile.NamedTemporaryFile(suffix=\\\".json\\\", delete=False) as tmp:\\n            tmp.write(b\\\"invalid json\\\")\\n            tmp.flush()\\n\\n            def verbose_print(msg):\\n                pass  # Real function\\n\\n            with pytest.raises(typer.Exit):\\n                await load_graph_from_path(Path(tmp.name), \\\".json\\\", verbose_print, verbose=False)\\n            mock_load_flow.assert_called_once_with(Path(tmp.name), disable_logs=True)\\n\\n\\n# Removed create_mock_graph - use create_real_graph() instead\\n\\n\\ndef simple_chat_json():\\n    \\\"\\\"\\\"Load the simple chat JSON test data.\\\"\\\"\\\"\\n    test_data_dir = Path(__file__).parent.parent.parent / \\\"data\\\"\\n    json_path = test_data_dir / \\\"simple_chat_no_llm.json\\\"\\n    with json_path.open() as f:\\n        return json.load(f)\\n\\n\\ndef create_real_graph():\\n    \\\"\\\"\\\"Helper function to create a real LFX graph with nodes/edges for serve_app.\\\"\\\"\\\"\\n    # Load real JSON data and create graph using from_payload\\n    json_data = simple_chat_json()\\n    return Graph.from_payload(json_data, flow_id=\\\"00000000-0000-0000-0000-000000000001\\\")\\n\\n\\nclass TestFastAPIAppCreation:\\n    \\\"\\\"\\\"Test FastAPI application creation.\\\"\\\"\\\"\\n\\n    def test_create_multi_serve_app_basic(self):\\n        \\\"\\\"\\\"Test basic multi-serve app creation.\\\"\\\"\\\"\\n        meta = FlowMeta(id=\\\"test-flow\\\", relative_path=\\\"test.json\\\", title=\\\"Test Flow\\\")\\n        registry = FlowRegistry()\\n        registry.add(create_real_graph(), meta)\\n\\n        app = create_multi_serve_app(registry=registry)\\n\\n        assert app.title.startswith(\\\"LFX Multi-Flow Server\\\")\\n        assert \\\"1\\\" in app.title  # Should show count\\n\\n    def test_create_multi_serve_app_mismatched_keys(self):\\n        \\\"\\\"\\\"Test app creation \u2014 registry never has mismatched keys by design; verify basic creation.\\\"\\\"\\\"\\n        meta = FlowMeta(id=\\\"test-flow\\\", relative_path=\\\"test.json\\\", title=\\\"Test Flow\\\")\\n        registry = FlowRegistry()\\n        registry.add(create_real_graph(), meta)\\n\\n        # Registry always keeps graphs and metas in sync \u2014 no mismatch possible\\n        app = create_multi_serve_app(registry=registry)\\n        assert app is not None\\n\\n\\nclass TestFastAPIEndpoints:\\n    \\\"\\\"\\\"Test FastAPI endpoints using TestClient.\\\"\\\"\\\"\\n\\n    def setup_method(self, tmp_path=None):  # noqa: ARG002\\n        \\\"\\\"\\\"Set up test client with mock data.\\\"\\\"\\\"\\n        self.real_graph = create_real_graph()\\n        meta = FlowMeta(id=\\\"test-flow\\\", relative_path=\\\"test.json\\\", title=\\\"Test Flow\\\", description=\\\"A test flow\\\")\\n\\n        registry = FlowRegistry()\\n        registry.add(self.real_graph, meta)\\n        self.app = create_multi_serve_app(registry=registry)\\n\\n        # Override the dependency for testing\\n        def mock_verify_key():\\n            return \\\"test-key\\\"\\n\\n        # Import here to avoid circular import issues\\n        from lfx.cli.serve_app import verify_api_key\\n\\n        self.app.dependency_overrides[verify_api_key] = mock_verify_key\\n        self.client = TestClient(self.app)\\n\\n    def test_list_flows_endpoint(self):\\n        \\\"\\\"\\\"Test the /flows endpoint.\\\"\\\"\\\"\\n        response = self.client.get(\\\"/flows\\\")\\n        assert response.status_code == 200\\n\\n        flows = response.json()\\n        assert len(flows) == 1\\n        assert flows[0][\\\"id\\\"] == \\\"test-flow\\\"\\n        assert flows[0][\\\"title\\\"] == \\\"Test Flow\\\"\\n\\n    def test_health_endpoint(self):\\n        \\\"\\\"\\\"Test the /health endpoint.\\\"\\\"\\\"\\n        response = self.client.get(\\\"/health\\\")\\n        assert response.status_code == 200\\n\\n        health = response.json()\\n        assert health[\\\"status\\\"] == \\\"healthy\\\"\\n        assert health[\\\"flow_count\\\"] == 1\\n\\n    @patch(\\\"lfx.cli.common.execute_graph_with_capture\\\")\\n    @patch(\\\"lfx.cli.common.extract_result_data\\\")\\n    def test_flow_run_endpoint_success(self, mock_extract, mock_execute):\\n        \\\"\\\"\\\"Test successful flow execution path (without auth validation).\\\"\\\"\\\"\\n        mock_execute.return_value = ({\\\"result\\\": \\\"success\\\"}, \\\"execution logs\\\")\\n        mock_extract.return_value = {\\n            \\\"result\\\": \\\"Processed successfully\\\",\\n            \\\"success\\\": True,\\n            \\\"type\\\": \\\"message\\\",\\n            \\\"component\\\": \\\"TestComponent\\\",\\n        }\\n\\n        # Test that the execute and extract functions would be called properly\\n        # (Testing the business logic, not the HTTP layer)\\n        assert mock_execute.return_value == ({\\\"result\\\": \\\"success\\\"}, \\\"execution logs\\\")\\n        assert mock_extract.return_value[\\\"result\\\"] == \\\"Processed successfully\\\"\\n        assert mock_extract.return_value[\\\"success\\\"] is True\\n\\n    @patch(\\\"lfx.cli.common.execute_graph_with_capture\\\")\\n    @pytest.mark.asyncio\\n    async def test_flow_run_endpoint_error(self, mock_execute):\\n        \\\"\\\"\\\"Test flow execution error handling logic.\\\"\\\"\\\"\\n        mock_execute.side_effect = Exception(\\\"Execution failed\\\")\\n\\n        # Test that the exception would be raised properly\\n        with pytest.raises(Exception, match=\\\"Execution failed\\\"):\\n            await mock_execute(self.real_graph, \\\"test input\\\")\\n\\n    def test_flow_info_endpoint(self):\\n        \\\"\\\"\\\"Test the flow info endpoint returns basic metadata.\\\"\\\"\\\"\\n        response = self.client.get(\\\"/flows/test-flow/info\\\")\\n        # Just test that the endpoint exists and returns something\\n        # The exact response depends on auth which is complex to mock\\n        assert response.status_code in [200, 422]  # Either success or auth failure\\n\\n    def test_flow_run_without_auth(self):\\n        \\\"\\\"\\\"Test flow execution without authentication.\\\"\\\"\\\"\\n        # Clear the dependency override to test auth failure\\n        from lfx.cli.serve_app import verify_api_key\\n\\n        if verify_api_key in self.app.dependency_overrides:\\n            del self.app.dependency_overrides[verify_api_key]\\n\\n        response = self.client.post(\\\"/flows/test-flow/run\\\", json={\\\"input_value\\\": \\\"test input\\\"})\\n\\n        # Should fail due to missing auth (exact status depends on verify_api_key implementation)\\n        assert response.status_code in [401, 403, 422]\\n\\n\\nclass TestErrorHandling:\\n    \\\"\\\"\\\"Test error handling in various components.\\\"\\\"\\\"\\n\\n    def test_invalid_json_in_request(self):\\n        \\\"\\\"\\\"Test handling of invalid JSON in requests.\\\"\\\"\\\"\\n        from lfx.cli.serve_app import verify_api_key\\n\\n        meta = FlowMeta(id=\\\"test\\\", relative_path=\\\"test.json\\\", title=\\\"Test\\\")\\n        registry = FlowRegistry()\\n        registry.add(create_real_graph(), meta)\\n        app = create_multi_serve_app(registry=registry)\\n        app.dependency_overrides[verify_api_key] = lambda: \\\"test-key\\\"\\n        client = TestClient(app)\\n\\n        response = client.post(\\n            \\\"/flows/test/run\\\",\\n            data=\\\"invalid json\\\",\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\", \\\"Content-Type\\\": \\\"application/json\\\"},\\n        )\\n\\n        assert response.status_code == 422  # Validation error\\n\\n    def test_missing_flow_id(self):\\n        \\\"\\\"\\\"Test accessing non-existent flow.\\\"\\\"\\\"\\n        from lfx.cli.serve_app import verify_api_key\\n\\n        meta = FlowMeta(id=\\\"test\\\", relative_path=\\\"test.json\\\", title=\\\"Test\\\")\\n        registry = FlowRegistry()\\n        registry.add(create_real_graph(), meta)\\n        app = create_multi_serve_app(registry=registry)\\n        app.dependency_overrides[verify_api_key] = lambda: \\\"test-key\\\"\\n        client = TestClient(app)\\n\\n        response = client.post(\\n            \\\"/flows/nonexistent/run\\\", json={\\\"input_value\\\": \\\"test\\\"}, headers={\\\"x-api-key\\\": \\\"test-key\\\"}\\n        )\\n\\n        assert response.status_code == 404\\n\\n\\nclass TestIntegration:\\n    \\\"\\\"\\\"Integration tests combining multiple components.\\\"\\\"\\\"\\n\\n    @patch(\\\"lfx.cli.common.load_flow_from_json\\\")\\n    @pytest.mark.asyncio\\n    async def test_full_app_integration(self, mock_load_flow):\\n        \\\"\\\"\\\"Test full app integration with realistic data.\\\"\\\"\\\"\\n        # Setup real graph\\n        real_graph = create_real_graph()\\n        mock_load_flow.return_value = real_graph\\n\\n        # Create temporary flow file\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".json\\\", delete=False) as tmp:\\n            json.dump({\\\"nodes\\\": [], \\\"edges\\\": []}, tmp)\\n            tmp.flush()\\n\\n            flow_path = Path(tmp.name)\\n\\n            # Test flow loading\\n            def verbose_print(msg):\\n                pass  # Real function\\n\\n            mock_verbose_print = verbose_print\\n            loaded_graph = await load_graph_from_path(flow_path, \\\".json\\\", mock_verbose_print)\\n            assert loaded_graph == real_graph\\n\\n            # Test flow ID generation\\n            flow_id = flow_id_from_path(flow_path, flow_path.parent)\\n            assert isinstance(flow_id, str)\\n\\n            # Test metadata creation\\n            meta = FlowMeta(\\n                id=flow_id, relative_path=flow_path.name, title=flow_path.stem, description=\\\"Integration test flow\\\"\\n            )\\n\\n            # Test app creation\\n            from lfx.cli.serve_app import verify_api_key as _verify_api_key\\n\\n            registry = FlowRegistry()\\n            registry.add(loaded_graph, meta)\\n            app = create_multi_serve_app(registry=registry)\\n            app.dependency_overrides[_verify_api_key] = lambda: \\\"test-key\\\"\\n            client = TestClient(app)\\n\\n            # Test endpoints\\n            flows_response = client.get(\\\"/flows\\\")\\n            assert flows_response.status_code == 200\\n            assert len(flows_response.json()) == 1\\n\\n            health_response = client.get(\\\"/health\\\")\\n            assert health_response.status_code == 200\\n            assert health_response.json()[\\\"flow_count\\\"] == 1\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_durable.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b564a42d0b5fd519516ac3102e7060cf279fe4ad2b13978c02083c984a0a67d2\",\"content\":\"\\\"\\\"\\\"Durable background mode on bare ``lfx serve`` (LE-1695).\\n\\nReal-integration tests through the FastAPI surface: with ``LFX_SERVE_DURABLE_DB``\\nset, ``POST /api/v2/workflows`` accepts ``mode=\\\"background\\\"``, a HITL flow suspends\\ninto the SQLite job store, and ``POST /{job_id}/resume`` completes the chosen branch \u2014\\nincluding after a \\\"process restart\\\" (a fresh app + host on the same DB file).\\n\\\"\\\"\\\"\\n\\nimport contextlib\\nimport json\\nimport sqlite3\\nimport time\\nfrom datetime import datetime, timedelta, timezone\\n\\nimport pytest\\nfrom fastapi.testclient import TestClient\\nfrom lfx.cli.serve_app import FlowMeta, FlowRegistry, create_multi_serve_app\\nfrom lfx.components.flow_controls.human_input import HumanInput\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.graph import Graph\\nfrom lfx.graph.checkpoint.store import set_default_checkpoint_store\\n\\n_ECHO_FLOW_ID = \\\"67ccd2be-17f0-4190-81ff-3bb2cf6508e6\\\"\\n_HITL_FLOW_ID = \\\"aaccd2be-17f0-4190-81ff-3bb2cf6508e6\\\"\\n_API_KEY = \\\"test-key\\\"  # pragma: allowlist secret\\n_HEADERS = {\\\"x-api-key\\\": _API_KEY}\\n_WAIT_S = 20.0\\n\\n\\ndef _echo_graph() -> Graph:\\n    chat_input = ChatInput(_id=\\\"chat_input\\\")\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=chat_input.message_response)\\n    graph = Graph(chat_input, chat_output)\\n    graph.prepare()\\n    return graph\\n\\n\\ndef _node(component) -> dict:\\n    frontend = component.to_frontend_node()\\n    return {\\\"id\\\": frontend[\\\"id\\\"], \\\"data\\\": frontend[\\\"data\\\"]}\\n\\n\\ndef _edge(source: str, target: str, handle: str, field: str = \\\"input_value\\\") -> dict:\\n    return {\\n        \\\"source\\\": source,\\n        \\\"target\\\": target,\\n        \\\"id\\\": f\\\"{source}-{handle}-{target}\\\",\\n        \\\"data\\\": {\\n            \\\"sourceHandle\\\": {\\\"dataType\\\": \\\"x\\\", \\\"id\\\": source, \\\"name\\\": handle, \\\"output_types\\\": [\\\"Message\\\"]},\\n            \\\"targetHandle\\\": {\\\"fieldName\\\": field, \\\"id\\\": target, \\\"inputTypes\\\": [\\\"Message\\\"], \\\"type\\\": \\\"str\\\"},\\n        },\\n    }\\n\\n\\ndef _pausing_graph() -> Graph:\\n    payload = {\\n        \\\"nodes\\\": [\\n            _node(ChatInput(_id=\\\"chat_input\\\")),\\n            _node(HumanInput(_id=\\\"hitl1\\\")),\\n            _node(ChatOutput(_id=\\\"co_approve\\\")),\\n            _node(ChatOutput(_id=\\\"co_reject\\\")),\\n        ],\\n        \\\"edges\\\": [\\n            _edge(\\\"chat_input\\\", \\\"hitl1\\\", \\\"message\\\", field=\\\"prompt\\\"),\\n            _edge(\\\"hitl1\\\", \\\"co_approve\\\", \\\"branch_approve\\\"),\\n            _edge(\\\"hitl1\\\", \\\"co_reject\\\", \\\"branch_reject\\\"),\\n        ],\\n    }\\n    graph = Graph.from_payload(payload, flow_id=_HITL_FLOW_ID)\\n    graph.prepare()\\n    return graph\\n\\n\\ndef _build_registry() -> FlowRegistry:\\n    registry = FlowRegistry()\\n    registry.add(\\n        _echo_graph(),\\n        FlowMeta(id=_ECHO_FLOW_ID, relative_path=f\\\"{_ECHO_FLOW_ID}.json\\\", title=\\\"echo\\\", description=None),\\n    )\\n    registry.add(\\n        _pausing_graph(),\\n        FlowMeta(id=_HITL_FLOW_ID, relative_path=f\\\"{_HITL_FLOW_ID}.json\\\", title=\\\"hitl\\\", description=None),\\n    )\\n    return registry\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _reset_default_checkpoint_store():\\n    \\\"\\\"\\\"The durable host installs its store as the module fallback; undo it per test.\\\"\\\"\\\"\\n    yield\\n    set_default_checkpoint_store(None)\\n\\n\\n@pytest.fixture\\ndef durable_db(tmp_path, monkeypatch):\\n    db_path = tmp_path / \\\"serve-durable.db\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_API_KEY\\\", _API_KEY)\\n    monkeypatch.setenv(\\\"LFX_SERVE_DURABLE_DB\\\", str(db_path))\\n    return db_path\\n\\n\\n@pytest.fixture\\ndef client(durable_db):\\n    del durable_db\\n    app = create_multi_serve_app(registry=_build_registry())\\n    with TestClient(app) as test_client:\\n        yield test_client\\n\\n\\ndef _get_status(client: TestClient, job_id: str) -> dict:\\n    resp = client.get(\\\"/api/v2/workflows\\\", params={\\\"job_id\\\": job_id}, headers=_HEADERS)\\n    assert resp.status_code == 200, resp.text\\n    return resp.json()\\n\\n\\ndef _wait_for_status(client: TestClient, job_id: str, wanted: str) -> dict:\\n    deadline = time.monotonic() + _WAIT_S\\n    body = {}\\n    while time.monotonic() < deadline:\\n        body = _get_status(client, job_id)\\n        if body[\\\"status\\\"] == wanted:\\n            return body\\n        assert body[\\\"status\\\"] not in {\\\"failed\\\", \\\"cancelled\\\"}, body\\n        time.sleep(0.05)\\n    msg = f\\\"job {job_id} never reached {wanted}; last: {body}\\\"\\n    raise AssertionError(msg)\\n\\n\\ndef _submit(client: TestClient, flow_id: str, input_value: str = \\\"hello\\\") -> str:\\n    resp = client.post(\\n        \\\"/api/v2/workflows\\\",\\n        json={\\\"flow_id\\\": flow_id, \\\"input_value\\\": input_value, \\\"mode\\\": \\\"background\\\"},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 200, resp.text\\n    body = resp.json()\\n    assert body[\\\"status\\\"] == \\\"queued\\\"\\n    return body[\\\"job_id\\\"]\\n\\n\\ndef _pending_request(client: TestClient, job_id: str) -> dict:\\n    resp = client.get(f\\\"/api/v2/workflows/{job_id}/pending\\\", headers=_HEADERS)\\n    assert resp.status_code == 200, resp.text\\n    return resp.json()\\n\\n\\ndef _read_events(client: TestClient, job_id: str, *, last_event_id: str | None = None) -> list[dict]:\\n    headers = dict(_HEADERS)\\n    if last_event_id is not None:\\n        headers[\\\"Last-Event-ID\\\"] = last_event_id\\n    resp = client.get(f\\\"/api/v2/workflows/{job_id}/events\\\", headers=headers)\\n    assert resp.status_code == 200, resp.text\\n    assert resp.headers[\\\"content-type\\\"].startswith(\\\"text/event-stream\\\")\\n    events: list[dict] = []\\n    for block in resp.text.split(\\\"\\\\n\\\\n\\\"):\\n        data_line = next((line for line in block.splitlines() if line.startswith(\\\"data:\\\")), None)\\n        if data_line:\\n            events.append(json.loads(data_line[len(\\\"data:\\\") :].strip()))\\n    return events\\n\\n\\ndef test_background_echo_completes_with_execution_response(client):\\n    job_id = _submit(client, _ECHO_FLOW_ID)\\n    body = _wait_for_status(client, job_id, \\\"completed\\\")\\n    assert body[\\\"flow_id\\\"] == _ECHO_FLOW_ID\\n    assert \\\"hello\\\" in (body[\\\"output\\\"][\\\"text\\\"] or \\\"\\\")\\n    assert body[\\\"outputs\\\"]\\n\\n\\ndef test_background_hitl_suspends_and_exposes_pending_request(client):\\n    job_id = _submit(client, _HITL_FLOW_ID)\\n    body = _wait_for_status(client, job_id, \\\"suspended\\\")\\n    assert body[\\\"object\\\"] == \\\"job\\\"\\n    pending = _pending_request(client, job_id)\\n    assert pending[\\\"request_id\\\"]\\n    assert any(option.get(\\\"action_id\\\") == \\\"approve\\\" for option in pending.get(\\\"options\\\", []))\\n\\n\\ndef test_resubmit_supersedes_the_stale_suspended_run(client):\\n    \\\"\\\"\\\"Re-running a paused flow cancels the stale pause and tracks only the new one.\\\"\\\"\\\"\\n    stale_job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, stale_job_id, \\\"suspended\\\")\\n    stale_request_id = _pending_request(client, stale_job_id)[\\\"request_id\\\"]\\n\\n    new_job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, new_job_id, \\\"suspended\\\")\\n\\n    stale = _get_status(client, stale_job_id)\\n    assert stale[\\\"status\\\"] == \\\"cancelled\\\"\\n    resp = client.get(f\\\"/api/v2/workflows/{stale_job_id}/pending\\\", headers=_HEADERS)\\n    assert resp.status_code == 404\\n    pending = _pending_request(client, new_job_id)\\n    assert pending[\\\"request_id\\\"]\\n    assert pending[\\\"request_id\\\"] != stale_request_id\\n\\n\\ndef test_supersede_does_not_clobber_a_run_claimed_for_resume(tmp_path):\\n    \\\"\\\"\\\"A resume that wins the flip between supersede's select and cancel keeps its run.\\n\\n    No CANCELLED write, no lingering STOP signal, pending metadata intact.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    from lfx.cli.serve_durable import DurableServeWorkflowHost\\n    from lfx.services.durable.models import JobStatus as DurableJobStatus\\n\\n    host = DurableServeWorkflowHost(_build_registry(), lambda: None, db_path=tmp_path / \\\"race.db\\\")\\n\\n    async def scenario():\\n        job_id = \\\"job-race-1\\\"\\n        await host.jobs.create_job(job_id=job_id, flow_id=_HITL_FLOW_ID, user_id=\\\"\\\")\\n        await host.jobs.update_status(job_id, DurableJobStatus.SUSPENDED)\\n        await host.jobs.update_metadata(job_id, {\\\"pending\\\": {\\\"request_id\\\": \\\"req-1\\\"}})\\n\\n        # Deterministically lose the race: the resume claims the job AFTER\\n        # supersede's select returns it but BEFORE the cancel step runs.\\n        original_select = host.jobs.suspended_job_ids_for_flow\\n\\n        async def select_then_lose_to_resume(flow_id_arg):\\n            ids = await original_select(flow_id_arg)\\n            assert ids == [job_id]\\n            assert await host.jobs.claim_suspended_for_resume(job_id) is True\\n            return ids\\n\\n        host.jobs.suspended_job_ids_for_flow = select_then_lose_to_resume\\n\\n        await host._supersede_suspended(_HITL_FLOW_ID)\\n\\n        job = await host.jobs.get_job(job_id)\\n        assert job.status == DurableJobStatus.IN_PROGRESS\\n        assert (job.job_metadata or {}).get(\\\"pending\\\") == {\\\"request_id\\\": \\\"req-1\\\"}\\n        assert await host.jobs.unconsumed_signals(job_id) == []\\n\\n    asyncio.run(scenario())\\n\\n\\ndef test_resubmit_of_a_different_flow_leaves_the_pause_alone(client):\\n    suspended_job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, suspended_job_id, \\\"suspended\\\")\\n\\n    other_job_id = _submit(client, _ECHO_FLOW_ID)\\n    _wait_for_status(client, other_job_id, \\\"completed\\\")\\n\\n    assert _get_status(client, suspended_job_id)[\\\"status\\\"] == \\\"suspended\\\"\\n    assert _pending_request(client, suspended_job_id)[\\\"request_id\\\"]\\n\\n\\ndef test_resume_completes_only_the_chosen_branch(client):\\n    job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"suspended\\\")\\n    pending = _pending_request(client, job_id)\\n\\n    resp = client.post(\\n        f\\\"/api/v2/workflows/{job_id}/resume\\\",\\n        json={\\\"request_id\\\": pending[\\\"request_id\\\"], \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\", \\\"values\\\": {}}},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 200, resp.text\\n    assert resp.json()[\\\"status\\\"] == \\\"resuming\\\"\\n\\n    body = _wait_for_status(client, job_id, \\\"completed\\\")\\n    assert \\\"co_approve\\\" in body[\\\"outputs\\\"]\\n    assert \\\"co_reject\\\" not in body[\\\"outputs\\\"]\\n\\n\\n@pytest.mark.usefixtures(\\\"durable_db\\\")\\ndef test_resume_survives_process_restart():\\n    app = create_multi_serve_app(registry=_build_registry())\\n    with TestClient(app) as first_client:\\n        job_id = _submit(first_client, _HITL_FLOW_ID)\\n        _wait_for_status(first_client, job_id, \\\"suspended\\\")\\n        pending = _pending_request(first_client, job_id)\\n\\n    restarted_app = create_multi_serve_app(registry=_build_registry())\\n    with TestClient(restarted_app) as second_client:\\n        assert _get_status(second_client, job_id)[\\\"status\\\"] == \\\"suspended\\\"\\n        resp = second_client.post(\\n            f\\\"/api/v2/workflows/{job_id}/resume\\\",\\n            json={\\\"request_id\\\": pending[\\\"request_id\\\"], \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\", \\\"values\\\": {}}},\\n            headers=_HEADERS,\\n        )\\n        assert resp.status_code == 200, resp.text\\n        body = _wait_for_status(second_client, job_id, \\\"completed\\\")\\n        assert \\\"co_approve\\\" in body[\\\"outputs\\\"]\\n        assert \\\"co_reject\\\" not in body[\\\"outputs\\\"]\\n\\n\\ndef _backdate_pause(db_path, job_id: str, *, days: int) -> None:\\n    \\\"\\\"\\\"Rewrite the suspended job's ``paused_at`` so the pending request is already expired.\\\"\\\"\\\"\\n    stale = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()\\n    with contextlib.closing(sqlite3.connect(db_path)) as conn, conn:\\n        row = conn.execute(\\\"SELECT job_metadata FROM jobs WHERE job_id = ?\\\", (job_id,)).fetchone()\\n        meta = json.loads(row[0])\\n        meta[\\\"pending\\\"][\\\"paused_at\\\"] = stale\\n        conn.execute(\\\"UPDATE jobs SET job_metadata = ? WHERE job_id = ?\\\", (json.dumps(meta), job_id))\\n\\n\\ndef test_late_resume_records_human_input_expired_event(client, durable_db):\\n    job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"suspended\\\")\\n    pending = _pending_request(client, job_id)\\n    _backdate_pause(durable_db, job_id, days=10)\\n\\n    resp = client.post(\\n        f\\\"/api/v2/workflows/{job_id}/resume\\\",\\n        json={\\\"request_id\\\": pending[\\\"request_id\\\"], \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\", \\\"values\\\": {}}},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 200, resp.text\\n\\n    body = _wait_for_status(client, job_id, \\\"completed\\\")\\n    assert body[\\\"outputs\\\"] == {}, \\\"expired with no fallback takes no branch\\\"\\n\\n    events = _read_events(client, job_id)\\n    expired = [event for event in events if event[\\\"event\\\"] == \\\"human_input_expired\\\"]\\n    assert expired, f\\\"no human_input_expired event; got {[e['event'] for e in events]}\\\"\\n    payload = expired[0][\\\"data\\\"]\\n    assert payload[\\\"request_id\\\"] == pending[\\\"request_id\\\"]\\n    assert payload[\\\"requested_action\\\"] == \\\"approve\\\"\\n    assert payload[\\\"rerouted_to\\\"] == \\\"__expired__\\\"\\n\\n    decision_events = [event for event in events if event[\\\"event\\\"] == \\\"human_input_decision\\\"]\\n    assert decision_events\\n    assert decision_events[0][\\\"data\\\"][\\\"action_id\\\"] == \\\"__expired__\\\"\\n    assert expired[0][\\\"seq\\\"] < decision_events[0][\\\"seq\\\"]\\n\\n\\ndef test_ontime_resume_records_no_expired_event(client):\\n    job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"suspended\\\")\\n    pending = _pending_request(client, job_id)\\n\\n    resp = client.post(\\n        f\\\"/api/v2/workflows/{job_id}/resume\\\",\\n        json={\\\"request_id\\\": pending[\\\"request_id\\\"], \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\", \\\"values\\\": {}}},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 200, resp.text\\n    _wait_for_status(client, job_id, \\\"completed\\\")\\n\\n    events = _read_events(client, job_id)\\n    assert not [event for event in events if event[\\\"event\\\"] == \\\"human_input_expired\\\"]\\n\\n\\ndef test_events_endpoint_replays_completed_run(client):\\n    job_id = _submit(client, _ECHO_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"completed\\\")\\n    events = _read_events(client, job_id)\\n    assert events, \\\"expected at least the terminal 'end' event\\\"\\n    assert any(event[\\\"event\\\"] == \\\"end\\\" for event in events)\\n    assert all(event[\\\"seq\\\"] >= 1 for event in events)\\n\\n\\ndef test_events_endpoint_streams_hitl_request_and_ends_at_suspend(client):\\n    job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"suspended\\\")\\n    events = _read_events(client, job_id)\\n    request_events = [event for event in events if event[\\\"event\\\"] == \\\"human_input_request\\\"]\\n    assert request_events, events\\n    assert request_events[0][\\\"data\\\"].get(\\\"request_id\\\")\\n\\n\\ndef test_events_endpoint_resumes_from_last_event_id_after_resume(client):\\n    job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"suspended\\\")\\n    pending = _pending_request(client, job_id)\\n\\n    before = _read_events(client, job_id)\\n    assert before\\n    last_seq = str(before[-1][\\\"seq\\\"])\\n\\n    resp = client.post(\\n        f\\\"/api/v2/workflows/{job_id}/resume\\\",\\n        json={\\\"request_id\\\": pending[\\\"request_id\\\"], \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\", \\\"values\\\": {}}},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 200, resp.text\\n    _wait_for_status(client, job_id, \\\"completed\\\")\\n\\n    after = _read_events(client, job_id, last_event_id=last_seq)\\n    assert after, \\\"reconnect from Last-Event-ID should deliver post-resume events\\\"\\n    assert all(event[\\\"seq\\\"] > int(last_seq) for event in after)\\n    assert any(event[\\\"event\\\"] == \\\"human_input_decision\\\" for event in after)\\n    assert any(event[\\\"event\\\"] == \\\"end\\\" for event in after)\\n\\n\\ndef test_events_endpoint_unknown_job_404(client):\\n    resp = client.get(\\n        \\\"/api/v2/workflows/00000000-0000-4000-8000-000000000000/events\\\",\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 404\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"JOB_NOT_FOUND\\\"\\n\\n\\ndef test_events_endpoint_requires_api_key(client):\\n    job_id = _submit(client, _ECHO_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"completed\\\")\\n    resp = client.get(f\\\"/api/v2/workflows/{job_id}/events\\\")\\n    assert resp.status_code == 401\\n\\n\\ndef test_resume_unknown_job_404(client):\\n    resp = client.post(\\n        \\\"/api/v2/workflows/00000000-0000-4000-8000-000000000000/resume\\\",\\n        json={\\\"request_id\\\": \\\"whatever\\\", \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 404\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"JOB_NOT_FOUND\\\"\\n\\n\\ndef test_resume_disallowed_decision_422(client):\\n    job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"suspended\\\")\\n    pending = _pending_request(client, job_id)\\n    resp = client.post(\\n        f\\\"/api/v2/workflows/{job_id}/resume\\\",\\n        json={\\\"request_id\\\": pending[\\\"request_id\\\"], \\\"decision\\\": {\\\"action_id\\\": \\\"not-a-real-option\\\"}},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 422\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"INVALID_DECISION\\\"\\n    assert _get_status(client, job_id)[\\\"status\\\"] == \\\"suspended\\\"\\n\\n\\ndef test_resume_stale_request_id_409(client):\\n    job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"suspended\\\")\\n    resp = client.post(\\n        f\\\"/api/v2/workflows/{job_id}/resume\\\",\\n        json={\\\"request_id\\\": \\\"stale-id\\\", \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 409\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"NOT_RESUMABLE\\\"\\n\\n\\ndef test_resume_completed_job_409(client):\\n    job_id = _submit(client, _ECHO_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"completed\\\")\\n    resp = client.post(\\n        f\\\"/api/v2/workflows/{job_id}/resume\\\",\\n        json={\\\"request_id\\\": \\\"anything\\\", \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 409\\n\\n\\ndef test_stop_suspended_job_cancels(client):\\n    job_id = _submit(client, _HITL_FLOW_ID)\\n    _wait_for_status(client, job_id, \\\"suspended\\\")\\n    resp = client.post(\\n        \\\"/api/v2/workflows/stop\\\",\\n        json={\\\"job_id\\\": job_id},\\n        headers=_HEADERS,\\n    )\\n    assert resp.status_code == 200, resp.text\\n    assert _get_status(client, job_id)[\\\"status\\\"] == \\\"cancelled\\\"\\n\\n\\ndef test_background_requires_api_key(client):\\n    resp = client.post(\\n        \\\"/api/v2/workflows\\\",\\n        json={\\\"flow_id\\\": _ECHO_FLOW_ID, \\\"input_value\\\": \\\"x\\\", \\\"mode\\\": \\\"background\\\"},\\n    )\\n    assert resp.status_code == 401\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_env_isolation_integration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4028a31fcb07f734baa799332ff7182d03ea3b225ef44c196acac96adc21ac76\",\"content\":\"\\\"\\\"\\\"End-to-end env-isolation tests for `lfx serve` (spawns a live multi-worker server).\\n\\nDemonstrates the actual security guarantee \u2014 caller A writes os.environ, caller B\\nmust not read it \u2014 across real worker processes, which can only be observed with\\nlive processes, not in-process unit tests.\\n\\nProbe flow: a component writes a canary to os.environ and reports whether it SAW a\\nprior write. What the scenarios establish about each isolation knob:\\n- ``--workers 1 --reset-environ``: single persistent process, yet ``clean`` every\\n  request \u2014 isolation comes from the per-run os.environ snapshot/restore, not a fresh\\n  process. (Without --reset-environ this same setup LEAKS, proving the hazard is real.)\\n- ``--workers 2 --max-requests 1 --reset-environ``: warm workers (recycling does the\\n  work of hygiene, --reset-environ does the work of isolation) -> ``clean``.\\n- ``--workers 2 --use-sync-workers``: the blocking sync worker exits synchronously after\\n  each request, so requests land on fresh processes -> ``clean``.\\n- ``--workers 2 --max-requests 1`` ALONE (async, no --reset-environ): XFAILS -> the\\n  async worker recycles gracefully, so a winding-down worker still serves later\\n  requests and LEAKS. Recycling is NOT a per-request isolation guarantee here; only\\n  --use-sync-workers or --reset-environ are.\\n\\nSkipped in CI (spawns gunicorn + a real server; slow) \u2014 run locally as a harness.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport socket\\nimport subprocess\\nimport sys\\nimport time\\nimport urllib.error\\nimport urllib.request\\nfrom contextlib import contextmanager\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n_is_ci = os.environ.get(\\\"CI\\\", \\\"\\\").lower() in {\\\"1\\\", \\\"true\\\", \\\"yes\\\"}\\npytestmark = [\\n    pytest.mark.skipif(_is_ci, reason=\\\"spawns a live multi-worker server; not for fast CI\\\"),\\n    pytest.mark.skipif(sys.platform == \\\"win32\\\", reason=\\\"isolation path uses gunicorn (Unix-only)\\\"),\\n]\\n\\nPROBE_FLOW = \\\"\\\"\\\"\\nimport os\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.custom import Component\\nfrom lfx.graph import Graph\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.schema.message import Message\\n\\nPROBE_KEY = \\\"LFX_LEAK_PROBE\\\"\\nCANARY = \\\"SECRET-CANARY-VALUE\\\"\\n\\n\\nclass EnvLeakProbe(Component):\\n    display_name = \\\"Env Leak Probe\\\"\\n    inputs = [MessageTextInput(name=\\\"input_value\\\", display_name=\\\"Input\\\")]\\n    outputs = [Output(name=\\\"status\\\", display_name=\\\"Status\\\", method=\\\"get_status\\\")]\\n\\n    def get_status(self) -> Message:\\n        seen = os.environ.get(PROBE_KEY)\\n        os.environ[PROBE_KEY] = CANARY\\n        status = \\\"LEAKED\\\" if seen == CANARY else \\\"clean\\\"\\n        return Message(text=f\\\"{status}|pid={os.getpid()}\\\")\\n\\n\\nchat_input = ChatInput()\\nleak = EnvLeakProbe().set(input_value=chat_input.message_response)\\nchat_output = ChatOutput().set(input_value=leak.get_status)\\ngraph = Graph(chat_input, chat_output)\\n\\\"\\\"\\\"\\n\\n_API_KEY = \\\"leak-test-key\\\"  # pragma: allowlist secret\\n\\n\\ndef _free_port() -> int:\\n    s = socket.socket()\\n    s.bind((\\\"127.0.0.1\\\", 0))\\n    port = s.getsockname()[1]\\n    s.close()\\n    return port\\n\\n\\ndef _get(url: str):\\n    req = urllib.request.Request(url, headers={\\\"x-api-key\\\": _API_KEY})  # noqa: S310\\n    with urllib.request.urlopen(req, timeout=5) as resp:  # noqa: S310\\n        return json.load(resp)\\n\\n\\ndef _run_flow(port: int, flow_id: str, value: str) -> str:\\n    req = urllib.request.Request(\\n        f\\\"http://127.0.0.1:{port}/flows/{flow_id}/run\\\",\\n        data=json.dumps({\\\"input_value\\\": value}).encode(),\\n        method=\\\"POST\\\",\\n        headers={\\\"x-api-key\\\": _API_KEY, \\\"content-type\\\": \\\"application/json\\\"},\\n    )\\n    with urllib.request.urlopen(req, timeout=30) as resp:  # noqa: S310\\n        return json.load(resp)[\\\"result\\\"]\\n\\n\\n@contextmanager\\ndef _serve(tmp_path: Path, extra_args: list[str]):\\n    flow = tmp_path / \\\"leak_flow.py\\\"\\n    flow.write_text(PROBE_FLOW, encoding=\\\"utf-8\\\")\\n    port = _free_port()\\n    log = (tmp_path / \\\"server.log\\\").open(\\\"w\\\")\\n    env = {**os.environ, \\\"LANGFLOW_API_KEY\\\": _API_KEY}\\n    proc = subprocess.Popen(  # noqa: S603\\n        [sys.executable, \\\"-m\\\", \\\"lfx\\\", \\\"serve\\\", str(flow), \\\"--host\\\", \\\"127.0.0.1\\\", \\\"--port\\\", str(port), *extra_args],\\n        env=env,\\n        stdout=log,\\n        stderr=subprocess.STDOUT,\\n    )\\n    try:\\n        flow_id = _wait_ready(port, proc, tmp_path)\\n        yield port, flow_id\\n    finally:\\n        proc.terminate()\\n        try:\\n            proc.wait(timeout=10)\\n        except subprocess.TimeoutExpired:\\n            proc.kill()\\n        log.close()\\n\\n\\ndef _wait_ready(port: int, proc: subprocess.Popen, tmp_path: Path, timeout: float = 120.0) -> str:\\n    deadline = time.time() + timeout\\n    while time.time() < deadline:\\n        if proc.poll() is not None:\\n            log = (tmp_path / \\\"server.log\\\").read_text(encoding=\\\"utf-8\\\")\\n            msg = f\\\"serve exited early (code {proc.returncode}):\\\\n{log[-2000:]}\\\"\\n            raise RuntimeError(msg)\\n        try:\\n            flows = _get(f\\\"http://127.0.0.1:{port}/flows\\\")\\n            if flows:\\n                return flows[0][\\\"id\\\"]\\n        except (urllib.error.URLError, ConnectionError, TimeoutError, OSError):\\n            pass\\n        time.sleep(1)\\n    msg = \\\"serve did not become ready in time\\\"\\n    raise RuntimeError(msg)\\n\\n\\ndef _statuses(results):\\n    # Each result is \\\"clean|pid=NNNN\\\" or \\\"LEAKED|pid=NNNN\\\".\\n    return [r.split(\\\"|\\\", 1)[0] for r in results]\\n\\n\\ndef test_no_env_leak_multi_worker_warm(tmp_path):\\n    \\\"\\\"\\\"workers=2 with warm long-lived workers (--max-requests 0, no recycling) -> no env leak.\\n\\n    This is the production model: workers are NOT recycled per request, so isolation comes\\n    entirely from per-request os.environ snapshot/restore, even as each warm worker serves\\n    many requests.\\n    \\\"\\\"\\\"\\n    with _serve(tmp_path, [\\\"--workers\\\", \\\"2\\\", \\\"--max-requests\\\", \\\"0\\\", \\\"--reset-environ\\\"]) as (port, fid):\\n        results = [_run_flow(port, fid, f\\\"req{i}\\\") for i in range(12)]\\n    assert _statuses(results) == [\\\"clean\\\"] * 12, results\\n\\n\\ndef test_no_env_leak_single_worker(tmp_path):\\n    \\\"\\\"\\\"workers=1 (single persistent process, NO recycling) -> still no cross-request leak.\\n\\n    This is the strongest demonstration that per-request os.environ snapshot/restore in\\n    ``guarded_execute`` is what enforces isolation: every request is served by the SAME\\n    process (recycling never happens here), yet none sees a prior request's env write.\\n    Before that fix, this exact scenario leaked from the 2nd request onward.\\n    \\\"\\\"\\\"\\n    with _serve(tmp_path, [\\\"--workers\\\", \\\"1\\\", \\\"--reset-environ\\\"]) as (port, fid):\\n        results = [_run_flow(port, fid, f\\\"req{i}\\\") for i in range(12)]\\n    assert _statuses(results) == [\\\"clean\\\"] * 12, results\\n    # All requests served by the same process (no recycling) -> isolation came from\\n    # per-request env restore, not from a fresh process.\\n    pids = {r.split(\\\"pid=\\\", 1)[1] for r in results if \\\"pid=\\\" in r}\\n    assert len(pids) == 1, f\\\"expected a single reused worker process, got pids={pids} results={results}\\\"\\n\\n\\n@pytest.mark.xfail(\\n    # Non-strict: the leak is timing-dependent (the async worker's deferred-exit window is a\\n    # race), so on some setups all 12 requests happen to land 'clean' and the test XPASSes.\\n    # strict=True would turn that XPASS into a hard failure for anyone running the module.\\n    strict=False,\\n    reason=(\\n        \\\"KNOWN LIMITATION: async --max-requests recycling does NOT give per-request isolation. \\\"\\n        \\\"uvicorn honors limit_max_requests (logs 'Maximum request limit exceeded. Terminating \\\"\\n        \\\"process.') but the async worker shuts down GRACEFULLY/asynchronously \u2014 during the \\\"\\n        \\\"deferred-exit window the still-alive worker keeps accepting and serving new requests, so \\\"\\n        \\\"os.environ written by an earlier request LEAKS into a later one before the process exits. \\\"\\n        \\\"Observed (workers=2, max_requests=1): recurring LEAKED across requests. Strict per-request \\\"\\n        \\\"isolation IS available via --use-sync-workers (synchronous handle->check->exit; verified 8/8 \\\"\\n        \\\"clean, 8 distinct PIDs) or via --reset-environ (env snapshot/restore). Remove this xfail \\\"\\n        \\\"only if the async path is made to isolate (e.g. disable HTTP keep-alive + stop accepting \\\"\\n        \\\"on the recycling worker so a dying worker cannot serve a second request).\\\"\\n    ),\\n)\\ndef test_no_env_leak_multi_worker_recycle_async(tmp_path):\\n    \\\"\\\"\\\"workers=2 async worker with --max-requests 1 (no --reset-environ) -> SHOULD isolate, but leaks.\\n\\n    The module docstring's structural-isolation model assumes each request runs in a freshly-forked,\\n    recycled worker. On the async (uvicorn) worker that does not hold: recycling is graceful/deferred,\\n    so a worker keeps serving while it winds down and leaks a prior request's os.environ write.\\n\\n    Currently XFAILS \u2014 see decorator. The working isolation paths are --use-sync-workers and\\n    --reset-environ; this test documents the async gap and will flip to passing if it's closed.\\n    \\\"\\\"\\\"\\n    with _serve(tmp_path, [\\\"--workers\\\", \\\"2\\\", \\\"--max-requests\\\", \\\"1\\\"]) as (port, fid):\\n        results = [_run_flow(port, fid, f\\\"req{i}\\\") for i in range(12)]\\n    assert _statuses(results) == [\\\"clean\\\"] * 12, results\\n\\n\\ndef test_sync_workers_serves_requests(tmp_path):\\n    \\\"\\\"\\\"--use-sync-workers (gunicorn sync worker + a2wsgi bridge) serves requests via the real CLI.\\n\\n    Proves the opt-in sync-worker path boots and the ASGI->WSGI bridge handles requests,\\n    and that --reset-environ still enforces isolation under the sync worker.\\n    \\\"\\\"\\\"\\n    with _serve(tmp_path, [\\\"--workers\\\", \\\"2\\\", \\\"--use-sync-workers\\\", \\\"--reset-environ\\\"]) as (port, fid):\\n        results = [_run_flow(port, fid, f\\\"req{i}\\\") for i in range(8)]\\n    assert all(\\\"pid=\\\" in r for r in results), results  # the a2wsgi bridge served every request\\n    assert _statuses(results) == [\\\"clean\\\"] * 8, results  # reset-environ holds under sync worker\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_identity.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a11f88949e49336eca1cb72c156e063fd850b731bad57aa0054a9d0fad0819cc\",\"content\":\"\\\"\\\"\\\"Tests for per-user identity forwarding in ``lfx serve`` (verified JWT / header).\\n\\nCrypto is exercised with locally generated RSA and EC P-256 keypairs and an\\nin-memory fake JWKS endpoint \u2014 no network. See ``lfx.cli.serve_identity``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport base64\\nimport json\\nimport os\\nimport re\\nimport time\\nfrom pathlib import Path\\nfrom unittest.mock import MagicMock, patch\\n\\nimport httpx\\nimport jwt\\nimport pytest\\nfrom cryptography.hazmat.primitives.asymmetric import ec, rsa\\nfrom fastapi import HTTPException\\nfrom fastapi.testclient import TestClient\\nfrom jwt.algorithms import ECAlgorithm, RSAAlgorithm\\nfrom lfx.cli.common import execute_graph_with_capture\\nfrom lfx.cli.serve_app import FlowMeta, FlowRegistry, create_multi_serve_app, create_serve_app\\nfrom lfx.cli.serve_identity import (\\n    IdentityConfig,\\n    IdentityConfigError,\\n    IdentityVerifier,\\n    _fetch_json,\\n    build_identity_verifier,\\n)\\nfrom lfx.graph import Graph\\n\\nISSUER = \\\"https://accounts.example.com\\\"\\nAUDIENCE = \\\"my-oauth-client-id\\\"\\nKID = \\\"test-key-1\\\"\\nEC_KID = \\\"test-key-ec\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Crypto / JWKS test helpers (no network)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_keypair() -> rsa.RSAPrivateKey:\\n    return rsa.generate_private_key(public_exponent=65537, key_size=2048)\\n\\n\\ndef _jwks_for(public_key, kid: str = KID) -> dict:\\n    \\\"\\\"\\\"Build a JWKS document exposing an RSA ``public_key`` under ``kid``.\\\"\\\"\\\"\\n    jwk = json.loads(RSAAlgorithm.to_jwk(public_key))\\n    jwk.update({\\\"kid\\\": kid, \\\"use\\\": \\\"sig\\\", \\\"alg\\\": \\\"RS256\\\"})\\n    return {\\\"keys\\\": [jwk]}\\n\\n\\ndef _make_ec_keypair() -> ec.EllipticCurvePrivateKey:\\n    return ec.generate_private_key(ec.SECP256R1())\\n\\n\\ndef _ec_jwks_for(public_key, kid: str = EC_KID) -> dict:\\n    \\\"\\\"\\\"Build a JWKS document exposing an EC P-256 ``public_key`` under ``kid``.\\\"\\\"\\\"\\n    jwk = json.loads(ECAlgorithm.to_jwk(public_key))\\n    jwk.update({\\\"kid\\\": kid, \\\"use\\\": \\\"sig\\\", \\\"alg\\\": \\\"ES256\\\"})\\n    return {\\\"keys\\\": [jwk]}\\n\\n\\ndef _sign(private_key, claims: dict, *, kid: str = KID, alg: str = \\\"RS256\\\") -> str:\\n    payload = {\\\"iss\\\": ISSUER, \\\"aud\\\": AUDIENCE, \\\"exp\\\": int(time.time()) + 3600, **claims}\\n    return jwt.encode(payload, private_key, algorithm=alg, headers={\\\"kid\\\": kid})\\n\\n\\ndef _alg_none_token(claims: dict, *, kid: str = KID) -> str:\\n    \\\"\\\"\\\"Hand-craft an ``alg: none`` token (unsigned).\\\"\\\"\\\"\\n\\n    def b64(obj: dict) -> str:\\n        return base64.urlsafe_b64encode(json.dumps(obj).encode()).rstrip(b\\\"=\\\").decode()\\n\\n    payload = {\\\"iss\\\": ISSUER, \\\"aud\\\": AUDIENCE, \\\"exp\\\": int(time.time()) + 3600, **claims}\\n    return f\\\"{b64({'alg': 'none', 'typ': 'JWT', 'kid': kid})}.{b64(payload)}.\\\"\\n\\n\\nclass _CountingFetcher:\\n    \\\"\\\"\\\"A fake JWKS fetcher that counts calls and can be flipped to fail.\\\"\\\"\\\"\\n\\n    def __init__(self, jwks: dict) -> None:\\n        self.jwks = jwks\\n        self.calls = 0\\n        self.fail = False\\n\\n    def __call__(self, _url: str) -> dict:\\n        self.calls += 1\\n        if self.fail:\\n            msg = \\\"simulated JWKS endpoint down\\\"\\n            raise OSError(msg)\\n        return self.jwks\\n\\n\\n@pytest.fixture\\ndef keypair():\\n    return _make_keypair()\\n\\n\\n@pytest.fixture\\ndef jwks(keypair):\\n    return _jwks_for(keypair.public_key())\\n\\n\\n@pytest.fixture\\ndef fetcher(jwks):\\n    return _CountingFetcher(jwks)\\n\\n\\n@pytest.fixture\\ndef jwt_config():\\n    # Explicit jwks_url avoids OIDC discovery so the fake fetcher serves the JWKS directly.\\n    return IdentityConfig(\\n        mode=\\\"jwt\\\",\\n        jwt_issuer=ISSUER,\\n        jwt_audience=AUDIENCE,\\n        jwt_jwks_url=\\\"https://accounts.example.com/jwks\\\",\\n        claim=\\\"email\\\",\\n    )\\n\\n\\n@pytest.fixture\\ndef verifier(jwt_config, fetcher):\\n    v = IdentityVerifier(jwt_config, jwks_fetcher=fetcher)\\n    v.prefetch()\\n    return v\\n\\n\\n# ---------------------------------------------------------------------------\\n# IdentityConfig\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestIdentityConfig:\\n    def test_off_is_default_and_disabled(self):\\n        cfg = IdentityConfig()\\n        assert cfg.mode == \\\"off\\\"\\n        assert cfg.enabled is False\\n        assert cfg.to_env() == {\\\"LFX_SERVE_IDENTITY_MODE\\\": \\\"off\\\"}\\n\\n    def test_jwt_requires_issuer_and_audience(self):\\n        with pytest.raises(IdentityConfigError):\\n            IdentityConfig(mode=\\\"jwt\\\", jwt_audience=AUDIENCE)\\n        with pytest.raises(IdentityConfigError):\\n            IdentityConfig(mode=\\\"jwt\\\", jwt_issuer=ISSUER)\\n\\n    def test_unknown_mode_rejected(self):\\n        with pytest.raises(IdentityConfigError):\\n            IdentityConfig(mode=\\\"bogus\\\")  # type: ignore[arg-type]\\n\\n    def test_non_http_jwks_url_rejected_offline(self):\\n        # A bad scheme must fail fast at config construction, not at first fetch.\\n        with pytest.raises(IdentityConfigError):\\n            IdentityConfig(mode=\\\"jwt\\\", jwt_issuer=ISSUER, jwt_audience=AUDIENCE, jwt_jwks_url=\\\"file:///etc/passwd\\\")\\n\\n    def test_http_jwks_url_rejected_by_default(self):\\n        # Plaintext http:// is MITM-able (forged JWKS), so HTTPS is required by default.\\n        with pytest.raises(IdentityConfigError):\\n            IdentityConfig(\\n                mode=\\\"jwt\\\", jwt_issuer=ISSUER, jwt_audience=AUDIENCE, jwt_jwks_url=\\\"http://issuer.test/jwks.json\\\"\\n            )\\n\\n    def test_http_jwks_url_allowed_with_insecure_flag(self):\\n        cfg = IdentityConfig(\\n            mode=\\\"jwt\\\",\\n            jwt_issuer=ISSUER,\\n            jwt_audience=AUDIENCE,\\n            jwt_jwks_url=\\\"http://issuer.test/jwks.json\\\",\\n            allow_insecure_http=True,\\n        )\\n        assert cfg.jwt_jwks_url == \\\"http://issuer.test/jwks.json\\\"\\n\\n    def test_http_issuer_for_discovery_rejected_by_default(self):\\n        # No explicit jwks_url \u2192 the issuer is fetched for OIDC discovery, so its\\n        # scheme is subject to the same HTTPS policy.\\n        with pytest.raises(IdentityConfigError):\\n            IdentityConfig(mode=\\\"jwt\\\", jwt_issuer=\\\"http://accounts.example.com\\\", jwt_audience=AUDIENCE, claim=\\\"email\\\")\\n\\n    def test_http_issuer_for_discovery_allowed_with_insecure_flag(self):\\n        cfg = IdentityConfig(\\n            mode=\\\"jwt\\\",\\n            jwt_issuer=\\\"http://accounts.example.com\\\",\\n            jwt_audience=AUDIENCE,\\n            claim=\\\"email\\\",\\n            allow_insecure_http=True,\\n        )\\n        assert cfg.jwt_issuer == \\\"http://accounts.example.com\\\"\\n\\n    def test_insecure_http_flag_still_rejects_non_http_schemes(self):\\n        # The escape hatch widens to http:// only \u2014 it must not re-open file://.\\n        with pytest.raises(IdentityConfigError):\\n            IdentityConfig(\\n                mode=\\\"jwt\\\",\\n                jwt_issuer=ISSUER,\\n                jwt_audience=AUDIENCE,\\n                jwt_jwks_url=\\\"file:///etc/passwd\\\",\\n                allow_insecure_http=True,\\n            )\\n\\n    def test_allow_insecure_http_env_round_trip(self):\\n        cfg = IdentityConfig(\\n            mode=\\\"jwt\\\",\\n            jwt_issuer=ISSUER,\\n            jwt_audience=AUDIENCE,\\n            jwt_jwks_url=\\\"http://issuer.test/jwks.json\\\",\\n            claim=\\\"email\\\",\\n            allow_insecure_http=True,\\n        )\\n        assert IdentityConfig.from_env(cfg.to_env()) == cfg\\n\\n    def test_env_round_trip_preserves_all_fields(self):\\n        cfg = IdentityConfig(\\n            mode=\\\"jwt\\\",\\n            jwt_issuer=ISSUER,\\n            jwt_audience=AUDIENCE,\\n            jwt_jwks_url=\\\"https://example.com/jwks\\\",\\n            claim=\\\"email\\\",\\n            jwt_header=\\\"X-Auth-Request-Access-Token\\\",\\n            trusted_header=\\\"X-Consumer-Username\\\",\\n        )\\n        assert IdentityConfig.from_env(cfg.to_env()) == cfg\\n\\n    def test_env_round_trip_header_mode(self):\\n        cfg = IdentityConfig(mode=\\\"header\\\", trusted_header=\\\"X-Consumer-Username\\\")\\n        assert IdentityConfig.from_env(cfg.to_env()) == cfg\\n\\n    def test_from_env_absent_is_off(self):\\n        assert IdentityConfig.from_env({}) == IdentityConfig(mode=\\\"off\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# IdentityVerifier \u2014 JWT mode\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestIdentityVerifierJwt:\\n    def _headers(self, token: str) -> dict:\\n        return {\\\"Authorization\\\": f\\\"Bearer {token}\\\"}\\n\\n    def test_valid_token_returns_identity_claim(self, verifier, keypair):\\n        token = _sign(keypair, {\\\"email\\\": \\\"alice@example.com\\\"})\\n        assert verifier.authenticate(self._headers(token)) == \\\"alice@example.com\\\"\\n\\n    def test_missing_token_rejected(self, verifier):\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate({})\\n        assert exc.value.status_code == 401\\n\\n    def test_bad_signature_rejected(self, verifier):\\n        other_key = _make_keypair()\\n        token = _sign(other_key, {\\\"email\\\": \\\"mallory@example.com\\\"})  # signed by wrong key, valid kid\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(token))\\n        assert exc.value.status_code == 401\\n\\n    def test_wrong_issuer_rejected(self, verifier, keypair):\\n        token = jwt.encode(\\n            {\\\"iss\\\": \\\"https://evil.example.com\\\", \\\"aud\\\": AUDIENCE, \\\"exp\\\": int(time.time()) + 3600, \\\"email\\\": \\\"a@b.c\\\"},\\n            keypair,\\n            algorithm=\\\"RS256\\\",\\n            headers={\\\"kid\\\": KID},\\n        )\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(token))\\n        assert exc.value.status_code == 401\\n\\n    def test_wrong_audience_rejected(self, verifier, keypair):\\n        token = jwt.encode(\\n            {\\\"iss\\\": ISSUER, \\\"aud\\\": \\\"some-other-client\\\", \\\"exp\\\": int(time.time()) + 3600, \\\"email\\\": \\\"a@b.c\\\"},\\n            keypair,\\n            algorithm=\\\"RS256\\\",\\n            headers={\\\"kid\\\": KID},\\n        )\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(token))\\n        assert exc.value.status_code == 401\\n\\n    def test_expired_token_rejected(self, verifier, keypair):\\n        token = jwt.encode(\\n            {\\\"iss\\\": ISSUER, \\\"aud\\\": AUDIENCE, \\\"exp\\\": int(time.time()) - 3600, \\\"email\\\": \\\"a@b.c\\\"},\\n            keypair,\\n            algorithm=\\\"RS256\\\",\\n            headers={\\\"kid\\\": KID},\\n        )\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(token))\\n        assert exc.value.status_code == 401\\n\\n    def test_alg_none_rejected(self, verifier):\\n        token = _alg_none_token({\\\"email\\\": \\\"a@b.c\\\"})\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(token))\\n        assert exc.value.status_code == 401\\n\\n    def test_hs256_alg_confusion_rejected(self, verifier, keypair):\\n        # Attacker signs with HMAC using the PUBLIC key bytes as the shared secret.\\n        # pyjwt refuses to use an asymmetric key for HMAC, so hand-craft the token.\\n        import hashlib\\n        import hmac\\n\\n        from cryptography.hazmat.primitives import serialization\\n\\n        public_pem = keypair.public_key().public_bytes(\\n            encoding=serialization.Encoding.PEM,\\n            format=serialization.PublicFormat.SubjectPublicKeyInfo,\\n        )\\n\\n        def b64(raw: bytes) -> str:\\n            return base64.urlsafe_b64encode(raw).rstrip(b\\\"=\\\").decode()\\n\\n        header = b64(json.dumps({\\\"alg\\\": \\\"HS256\\\", \\\"typ\\\": \\\"JWT\\\", \\\"kid\\\": KID}).encode())\\n        payload = b64(\\n            json.dumps(\\n                {\\\"iss\\\": ISSUER, \\\"aud\\\": AUDIENCE, \\\"exp\\\": int(time.time()) + 3600, \\\"email\\\": \\\"mallory@example.com\\\"}\\n            ).encode()\\n        )\\n        signing_input = f\\\"{header}.{payload}\\\".encode()\\n        signature = b64(hmac.new(public_pem, signing_input, hashlib.sha256).digest())\\n        forged = f\\\"{header}.{payload}.{signature}\\\"\\n\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(forged))\\n        assert exc.value.status_code == 401\\n\\n    def test_missing_claim_rejected(self, verifier, keypair):\\n        token = _sign(keypair, {\\\"sub\\\": \\\"no-email-here\\\"})  # claim is 'email'\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(token))\\n        assert exc.value.status_code == 401\\n\\n    @pytest.mark.parametrize(\\\"blank\\\", [\\\"\\\", \\\"   \\\", \\\"\\\\t\\\", \\\"\\\\n \\\"])\\n    def test_blank_claim_rejected(self, verifier, keypair, blank):\\n        # An empty or whitespace-only claim must not become a (blank) user_id.\\n        token = _sign(keypair, {\\\"email\\\": blank})\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(token))\\n        assert exc.value.status_code == 401\\n\\n    def test_missing_kid_rejected(self, verifier, keypair):\\n        # Token with no `kid` in its header \u2014 distinct from an unknown kid.\\n        token = jwt.encode(\\n            {\\\"iss\\\": ISSUER, \\\"aud\\\": AUDIENCE, \\\"exp\\\": int(time.time()) + 3600, \\\"email\\\": \\\"a@b.c\\\"},\\n            keypair,\\n            algorithm=\\\"RS256\\\",  # no headers={\\\"kid\\\": ...}\\n        )\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(token))\\n        assert exc.value.status_code == 401\\n        assert \\\"key id\\\" in exc.value.detail.lower()\\n\\n    def test_unknown_kid_triggers_one_rate_limited_refresh_then_401(self, verifier, fetcher, keypair):\\n        assert fetcher.calls == 1  # prefetch\\n        token = _sign(keypair, {\\\"email\\\": \\\"a@b.c\\\"}, kid=\\\"rotated-kid-not-in-jwks\\\")\\n\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate(self._headers(token))\\n        assert exc.value.status_code == 401\\n        assert fetcher.calls == 2  # one refresh attempt on the unknown kid\\n\\n        # A second immediate unknown-kid request is rate-limited: no extra fetch.\\n        with pytest.raises(HTTPException):\\n            verifier.authenticate(self._headers(token))\\n        assert fetcher.calls == 2\\n\\n    def test_cold_cache_fetch_is_rate_limited_during_outage(self, jwt_config, fetcher, keypair):\\n        # Prefetch fails and the issuer stays down: a flood of requests must NOT each\\n        # trigger its own (blocking) fetch \u2014 the cooldown floors bound it to a few.\\n        fetcher.fail = True\\n        v = IdentityVerifier(jwt_config, jwks_fetcher=fetcher)\\n        v.prefetch()  # fails; cache stays empty\\n        headers = self._headers(_sign(keypair, {\\\"email\\\": \\\"a@b.c\\\"}))\\n\\n        for _ in range(10):\\n            with pytest.raises(HTTPException) as exc:\\n                v.authenticate(headers)\\n            assert exc.value.status_code == 401\\n\\n        # 1 prefetch + at most one fetch per path before both cooldown floors engage.\\n        assert fetcher.calls <= 4\\n\\n    def test_jwks_down_with_warm_cache_still_verifies(self, verifier, fetcher, keypair):\\n        assert fetcher.calls == 1\\n        fetcher.fail = True  # endpoint goes down\\n        token = _sign(keypair, {\\\"email\\\": \\\"alice@example.com\\\"})\\n        # Known kid is already cached \u2192 verifies without re-fetching.\\n        assert verifier.authenticate(self._headers(token)) == \\\"alice@example.com\\\"\\n        assert fetcher.calls == 1\\n\\n    def test_custom_jwt_header_with_bearer_prefix(self, fetcher, keypair):\\n        cfg = IdentityConfig(\\n            mode=\\\"jwt\\\",\\n            jwt_issuer=ISSUER,\\n            jwt_audience=AUDIENCE,\\n            jwt_jwks_url=\\\"https://accounts.example.com/jwks\\\",\\n            claim=\\\"email\\\",\\n            jwt_header=\\\"X-Auth-Request-Access-Token\\\",\\n        )\\n        v = IdentityVerifier(cfg, jwks_fetcher=fetcher)\\n        v.prefetch()\\n        token = _sign(keypair, {\\\"email\\\": \\\"alice@example.com\\\"})\\n        assert v.authenticate({\\\"X-Auth-Request-Access-Token\\\": f\\\"Bearer {token}\\\"}) == \\\"alice@example.com\\\"\\n        # Raw token without Bearer prefix also accepted.\\n        assert v.authenticate({\\\"X-Auth-Request-Access-Token\\\": token}) == \\\"alice@example.com\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# IdentityVerifier \u2014 ES256 (the second accepted algorithm)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestIdentityVerifierEs256:\\n    \\\"\\\"\\\"ES256 (ECDSA P-256) is accepted alongside RS256; keys are matched by ``kid``.\\\"\\\"\\\"\\n\\n    def _verifier(self, jwks_doc: dict) -> IdentityVerifier:\\n        cfg = IdentityConfig(\\n            mode=\\\"jwt\\\",\\n            jwt_issuer=ISSUER,\\n            jwt_audience=AUDIENCE,\\n            jwt_jwks_url=\\\"https://accounts.example.com/jwks\\\",\\n            claim=\\\"email\\\",\\n        )\\n        v = IdentityVerifier(cfg, jwks_fetcher=lambda _u: jwks_doc)\\n        v.prefetch()\\n        return v\\n\\n    def test_valid_es256_token_returns_identity_claim(self):\\n        ec_key = _make_ec_keypair()\\n        v = self._verifier(_ec_jwks_for(ec_key.public_key()))\\n        token = _sign(ec_key, {\\\"email\\\": \\\"ec-alice@example.com\\\"}, kid=EC_KID, alg=\\\"ES256\\\")\\n        assert v.authenticate({\\\"Authorization\\\": f\\\"Bearer {token}\\\"}) == \\\"ec-alice@example.com\\\"\\n\\n    def test_es256_bad_signature_rejected(self):\\n        ec_key = _make_ec_keypair()\\n        other = _make_ec_keypair()  # advertised key differs from the signer\\n        v = self._verifier(_ec_jwks_for(ec_key.public_key()))\\n        token = _sign(other, {\\\"email\\\": \\\"mallory@example.com\\\"}, kid=EC_KID, alg=\\\"ES256\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            v.authenticate({\\\"Authorization\\\": f\\\"Bearer {token}\\\"})\\n        assert exc.value.status_code == 401\\n\\n    def test_es256_wrong_audience_rejected(self):\\n        ec_key = _make_ec_keypair()\\n        v = self._verifier(_ec_jwks_for(ec_key.public_key()))\\n        token = jwt.encode(\\n            {\\\"iss\\\": ISSUER, \\\"aud\\\": \\\"some-other-client\\\", \\\"exp\\\": int(time.time()) + 3600, \\\"email\\\": \\\"a@b.c\\\"},\\n            ec_key,\\n            algorithm=\\\"ES256\\\",\\n            headers={\\\"kid\\\": EC_KID},\\n        )\\n        with pytest.raises(HTTPException) as exc:\\n            v.authenticate({\\\"Authorization\\\": f\\\"Bearer {token}\\\"})\\n        assert exc.value.status_code == 401\\n\\n    def test_mixed_jwks_verifies_both_rs256_and_es256_by_kid(self):\\n        # A single JWKS carrying one RSA and one EC key; the verifier picks by kid.\\n        rsa_key = _make_keypair()\\n        ec_key = _make_ec_keypair()\\n        jwks_doc = {\\\"keys\\\": _jwks_for(rsa_key.public_key())[\\\"keys\\\"] + _ec_jwks_for(ec_key.public_key())[\\\"keys\\\"]}\\n        v = self._verifier(jwks_doc)\\n        rs_token = _sign(rsa_key, {\\\"email\\\": \\\"rs@example.com\\\"})  # RS256, kid=test-key-1\\n        es_token = _sign(ec_key, {\\\"email\\\": \\\"es@example.com\\\"}, kid=EC_KID, alg=\\\"ES256\\\")\\n        assert v.authenticate({\\\"Authorization\\\": f\\\"Bearer {rs_token}\\\"}) == \\\"rs@example.com\\\"\\n        assert v.authenticate({\\\"Authorization\\\": f\\\"Bearer {es_token}\\\"}) == \\\"es@example.com\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Startup prefetch\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestJwksSourceResolution:\\n    \\\"\\\"\\\"OIDC discovery (when no explicit jwks_url) and the SSRF scheme guard.\\\"\\\"\\\"\\n\\n    def _disco_config(self):\\n        # No jwt_jwks_url \u2192 the verifier must discover it from the issuer.\\n        return IdentityConfig(mode=\\\"jwt\\\", jwt_issuer=ISSUER, jwt_audience=AUDIENCE, claim=\\\"email\\\")\\n\\n    def test_oidc_discovery_resolves_jwks_uri_then_verifies(self, jwks, keypair):\\n        seen = {}\\n\\n        def openid_fetch(url):\\n            seen[\\\"openid\\\"] = url\\n            return {\\\"jwks_uri\\\": \\\"https://accounts.example.com/discovered-jwks\\\"}\\n\\n        def jwks_fetch(url):\\n            seen[\\\"jwks\\\"] = url\\n            return jwks\\n\\n        v = IdentityVerifier(self._disco_config(), jwks_fetcher=jwks_fetch, openid_fetcher=openid_fetch)\\n        v.prefetch()\\n        token = _sign(keypair, {\\\"email\\\": \\\"alice@example.com\\\"})\\n        assert v.authenticate({\\\"Authorization\\\": f\\\"Bearer {token}\\\"}) == \\\"alice@example.com\\\"\\n        # Discovery hit the well-known doc, then fetched the URL it advertised.\\n        assert seen[\\\"openid\\\"] == \\\"https://accounts.example.com/.well-known/openid-configuration\\\"\\n        assert seen[\\\"jwks\\\"] == \\\"https://accounts.example.com/discovered-jwks\\\"\\n\\n    def test_oidc_discovery_without_jwks_uri_degrades_to_401(self, keypair):\\n        # Discovery doc missing jwks_uri \u2192 IdentityConfigError, swallowed at fetch,\\n        # cache stays empty, prefetch does not raise, requests fail closed (401).\\n        v = IdentityVerifier(self._disco_config(), jwks_fetcher=lambda _u: {\\\"keys\\\": []}, openid_fetcher=lambda _u: {})\\n        v.prefetch()\\n        token = _sign(keypair, {\\\"email\\\": \\\"a@b.c\\\"})\\n        with pytest.raises(HTTPException) as exc:\\n            v.authenticate({\\\"Authorization\\\": f\\\"Bearer {token}\\\"})\\n        assert exc.value.status_code == 401\\n\\n    def test_fetch_json_rejects_non_http_scheme(self):\\n        # The SSRF guard: a file:// (or other non-http) URL must be refused.\\n        with pytest.raises(IdentityConfigError):\\n            _fetch_json(\\\"file:///etc/passwd\\\")\\n\\n    def test_fetch_json_refuses_redirect(self):\\n        # A redirect (e.g. https -> http) must be refused, not followed: following it\\n        # would issue the plaintext request before any scheme check could run.\\n        redirect = httpx.Response(status_code=302, headers={\\\"location\\\": \\\"http://evil.example/jwks\\\"})\\n        with (\\n            patch.object(httpx.Client, \\\"get\\\", return_value=redirect),\\n            pytest.raises(IdentityConfigError, match=\\\"redirect\\\"),\\n        ):\\n            _fetch_json(\\\"https://accounts.example.com/jwks\\\")\\n\\n    def _assert_fails_closed(self, verifier, keypair):\\n        \\\"\\\"\\\"A malformed external shape must not raise out of prefetch/auth \u2014 401.\\\"\\\"\\\"\\n        assert verifier.prefetch() is False  # empty cache, no AttributeError/500\\n        token = _sign(keypair, {\\\"email\\\": \\\"a@b.c\\\"})\\n        with pytest.raises(HTTPException) as exc:\\n            verifier.authenticate({\\\"Authorization\\\": f\\\"Bearer {token}\\\"})\\n        assert exc.value.status_code == 401\\n\\n    def test_jwks_non_object_fails_closed(self, keypair):\\n        # A JWKS endpoint returning a JSON array (not an object) must fail closed,\\n        # not raise AttributeError out of PyJWKSet.from_dict.\\n        cfg = IdentityConfig(\\n            mode=\\\"jwt\\\", jwt_issuer=ISSUER, jwt_audience=AUDIENCE, jwt_jwks_url=\\\"https://x/jwks\\\", claim=\\\"email\\\"\\n        )\\n        v = IdentityVerifier(cfg, jwks_fetcher=lambda _u: [])\\n        self._assert_fails_closed(v, keypair)\\n\\n    def test_oidc_discovery_non_object_fails_closed(self, keypair):\\n        # Discovery doc that is a JSON array (no .get) must fail closed, not raise.\\n        v = IdentityVerifier(self._disco_config(), jwks_fetcher=lambda _u: {\\\"keys\\\": []}, openid_fetcher=lambda _u: [])\\n        self._assert_fails_closed(v, keypair)\\n\\n    def test_oidc_discovery_non_string_jwks_uri_fails_closed(self, keypair):\\n        # jwks_uri present but not a string must fail closed, not slip through to\\n        # a later AttributeError when the non-string is fetched.\\n        v = IdentityVerifier(\\n            self._disco_config(),\\n            jwks_fetcher=lambda _u: {\\\"keys\\\": []},\\n            openid_fetcher=lambda _u: {\\\"jwks_uri\\\": 123},\\n        )\\n        self._assert_fails_closed(v, keypair)\\n\\n    def test_oidc_discovery_http_jwks_uri_rejected_by_default(self, keypair):\\n        # A discovered jwks_uri over plaintext http:// is refused under the default\\n        # HTTPS policy (defense-in-depth even when the issuer itself was https).\\n        v = IdentityVerifier(\\n            self._disco_config(),\\n            jwks_fetcher=lambda _u: {\\\"keys\\\": []},\\n            openid_fetcher=lambda _u: {\\\"jwks_uri\\\": \\\"http://accounts.example.com/jwks\\\"},\\n        )\\n        self._assert_fails_closed(v, keypair)\\n\\n\\nclass TestStartupPrefetch:\\n    def test_prefetch_fetches_before_first_request(self, jwt_config, fetcher, keypair):\\n        v = IdentityVerifier(jwt_config, jwks_fetcher=fetcher)\\n        assert fetcher.calls == 0\\n        assert v.prefetch() is True  # warm cache reported so callers can stay quiet\\n        assert fetcher.calls == 1  # JWKS fetched at startup, not on first request\\n        token = _sign(keypair, {\\\"email\\\": \\\"alice@example.com\\\"})\\n        assert v.authenticate({\\\"Authorization\\\": f\\\"Bearer {token}\\\"}) == \\\"alice@example.com\\\"\\n        assert fetcher.calls == 1  # first request paid no fetch round-trip\\n\\n    def test_failed_prefetch_does_not_raise_and_recovers(self, jwt_config, fetcher, keypair):\\n        fetcher.fail = True\\n        v = IdentityVerifier(jwt_config, jwks_fetcher=fetcher)\\n        assert v.prefetch() is False  # empty cache reported so the caller can warn loudly\\n        assert fetcher.calls == 1\\n\\n        fetcher.fail = False  # issuer recovers\\n        token = _sign(keypair, {\\\"email\\\": \\\"alice@example.com\\\"})\\n        # First real request re-fetches (cache was empty) and now succeeds.\\n        assert v.authenticate({\\\"Authorization\\\": f\\\"Bearer {token}\\\"}) == \\\"alice@example.com\\\"\\n        assert fetcher.calls == 2\\n\\n\\n# ---------------------------------------------------------------------------\\n# Header mode\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestIdentityVerifierHeader:\\n    def test_reads_configured_header(self):\\n        cfg = IdentityConfig(mode=\\\"header\\\", trusted_header=\\\"X-Consumer-Username\\\")\\n        v = IdentityVerifier(cfg)\\n        assert v.authenticate({\\\"X-Consumer-Username\\\": \\\"kong-user-7\\\"}) == \\\"kong-user-7\\\"\\n\\n    def test_missing_header_rejected(self):\\n        cfg = IdentityConfig(mode=\\\"header\\\", trusted_header=\\\"X-Consumer-Username\\\")\\n        v = IdentityVerifier(cfg)\\n        with pytest.raises(HTTPException) as exc:\\n            v.authenticate({})\\n        assert exc.value.status_code == 401\\n\\n    def test_header_mode_emits_startup_warning(self):\\n        cfg = IdentityConfig(mode=\\\"header\\\", trusted_header=\\\"X-Consumer-Username\\\")\\n        registry = FlowRegistry()\\n        with patch(\\\"lfx.cli.serve_app.logger\\\") as mock_logger:\\n            create_multi_serve_app(registry=registry, identity_config=cfg)\\n        assert mock_logger.warning.called\\n        warned = \\\" \\\".join(str(c.args[0]) for c in mock_logger.warning.call_args_list)\\n        assert \\\"X-Consumer-Username\\\" in warned\\n        assert \\\"topology\\\" in warned.lower()\\n\\n    def test_header_mode_warns_on_guaranteed_console_channel(self):\\n        # The structlog logger is not reliably surfaced on the serve stdout path, so the\\n        # header trust warning must also reach the operator via the stderr console.\\n        cfg = IdentityConfig(mode=\\\"header\\\", trusted_header=\\\"X-Consumer-Username\\\")\\n        registry = FlowRegistry()\\n        with patch(\\\"lfx.cli.serve_app._startup_console\\\") as mock_console:\\n            create_multi_serve_app(registry=registry, identity_config=cfg)\\n        assert mock_console.print.called\\n        printed = \\\" \\\".join(str(c.args[0]) for c in mock_console.print.call_args_list)\\n        assert \\\"X-Consumer-Username\\\" in printed\\n\\n\\n# ---------------------------------------------------------------------------\\n# Startup notices on the guaranteed (stderr console) channel\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStartupConsoleNotices:\\n    def _jwt_config(self):\\n        return IdentityConfig(\\n            mode=\\\"jwt\\\",\\n            jwt_issuer=ISSUER,\\n            jwt_audience=AUDIENCE,\\n            jwt_jwks_url=\\\"https://accounts.example.com/jwks.json\\\",\\n            claim=\\\"email\\\",\\n        )\\n\\n    def test_failed_jwt_prefetch_warns_on_console(self):\\n        # A failed prefetch must not abort startup, but it must warn loudly on the\\n        # guaranteed channel so the operator knows every request will 401.\\n        stub = MagicMock()\\n        stub.prefetch.return_value = False\\n        with (\\n            patch(\\\"lfx.cli.serve_app.build_identity_verifier\\\", return_value=stub),\\n            patch(\\\"lfx.cli.serve_app._startup_console\\\") as mock_console,\\n        ):\\n            create_multi_serve_app(registry=FlowRegistry(), identity_config=self._jwt_config())\\n        assert stub.prefetch.called\\n        printed = \\\" \\\".join(str(c.args[0]) for c in mock_console.print.call_args_list)\\n        assert \\\"JWKS prefetch failed\\\" in printed\\n        assert \\\"401\\\" in printed\\n\\n    def test_successful_jwt_prefetch_is_quiet_on_console(self):\\n        stub = MagicMock()\\n        stub.prefetch.return_value = True\\n        with (\\n            patch(\\\"lfx.cli.serve_app.build_identity_verifier\\\", return_value=stub),\\n            patch(\\\"lfx.cli.serve_app._startup_console\\\") as mock_console,\\n        ):\\n            create_multi_serve_app(registry=FlowRegistry(), identity_config=self._jwt_config())\\n        assert stub.prefetch.called\\n        assert not mock_console.print.called\\n\\n\\n# ---------------------------------------------------------------------------\\n# Token never logged\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestTokenNeverLogged:\\n    def test_token_absent_from_all_log_calls(self, jwt_config, fetcher, keypair):\\n        v = IdentityVerifier(jwt_config, jwks_fetcher=fetcher)\\n        v.prefetch()\\n        token = _sign(keypair, {\\\"email\\\": \\\"alice@example.com\\\"})\\n        headers = {\\\"Authorization\\\": f\\\"Bearer {token}\\\"}\\n\\n        with patch(\\\"lfx.cli.serve_identity.logger\\\") as mock_logger:\\n            v.authenticate(headers)  # success path\\n            with pytest.raises(HTTPException):\\n                v.authenticate({\\\"Authorization\\\": \\\"Bearer not.a.jwt\\\"})  # malformed\\n            fetcher.fail = True\\n            bad_kid = _sign(keypair, {\\\"email\\\": \\\"a@b.c\\\"}, kid=\\\"rotated\\\")\\n            with pytest.raises(HTTPException):\\n                v.authenticate({\\\"Authorization\\\": f\\\"Bearer {bad_kid}\\\"})  # forces failing refresh + logging\\n\\n        logged = \\\" \\\".join(str(a) for call in mock_logger.mock_calls if call.args for a in call.args)\\n        assert token not in logged\\n        assert \\\"not.a.jwt\\\" not in logged\\n\\n\\n# ---------------------------------------------------------------------------\\n# Endpoint integration (run/stream + serve-key floor)\\n# ---------------------------------------------------------------------------\\n\\nAPI_KEY = \\\"test-api-key\\\"  # pragma: allowlist secret\\nFLOW_ID = \\\"00000000-0000-0000-0000-000000000001\\\"\\n\\n\\n@pytest.fixture\\ndef real_graph():\\n    data_dir = Path(__file__).parent.parent.parent / \\\"data\\\"\\n    with (data_dir / \\\"simple_chat_no_llm.json\\\").open(encoding=\\\"utf-8\\\") as f:\\n        payload = json.load(f)\\n    return Graph.from_payload(payload, flow_id=FLOW_ID)\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _allow_custom_components(monkeypatch):\\n    from lfx.services.deps import get_settings_service\\n\\n    monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n\\ndef _client_with_verifier(real_graph, verifier_obj) -> TestClient:\\n    \\\"\\\"\\\"Build a serve app (off mode) and swap in a test verifier on app.state.\\\"\\\"\\\"\\n    registry = FlowRegistry()\\n    registry.add(real_graph, FlowMeta(id=FLOW_ID, relative_path=\\\"t.json\\\", title=\\\"t\\\", description=None))\\n    app = create_multi_serve_app(registry=registry)\\n    app.state.identity_verifier = verifier_obj  # None \u21d2 off\\n    return TestClient(app)\\n\\n\\nclass TestServeCli:\\n    \\\"\\\"\\\"The identity options are reachable through the real ``lfx serve`` CLI.\\\"\\\"\\\"\\n\\n    def test_serve_help_lists_identity_options(self):\\n        from lfx.__main__ import app\\n        from typer.testing import CliRunner\\n\\n        # Force a wide terminal so rich does not wrap long option names across lines.\\n        with patch.dict(os.environ, {\\\"COLUMNS\\\": \\\"200\\\"}):\\n            result = CliRunner().invoke(app, [\\\"serve\\\", \\\"--help\\\"])\\n        assert result.exit_code == 0\\n        # Strip ANSI styling: rich colorizes each hyphen-segment of an option name\\n        # (``-``/``-identity``/``-mode``), so the raw output never holds the literal\\n        # ``--identity-mode`` substring when color is forced (as it is in CI).\\n        plain = re.sub(r\\\"\\\\x1b\\\\[[0-9;]*m\\\", \\\"\\\", result.output)\\n        assert \\\"--identity-mode\\\" in plain\\n        assert \\\"--identity-jwt-issuer\\\" in plain\\n\\n    def test_jwt_mode_without_issuer_fails_fast(self):\\n        from lfx.__main__ import app\\n        from typer.testing import CliRunner\\n\\n        env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"LFX_SERVE_\\\")}\\n        env[\\\"LANGFLOW_API_KEY\\\"] = API_KEY\\n        with patch.dict(os.environ, env, clear=True):\\n            result = CliRunner().invoke(app, [\\\"serve\\\", \\\"--identity-mode\\\", \\\"jwt\\\"])\\n        assert result.exit_code != 0\\n        assert \\\"identity-jwt-issuer\\\" in result.output\\n\\n\\nclass TestWorkerEnvRoundTrip:\\n    \\\"\\\"\\\"Identity config must survive the env-var round-trip into uvicorn workers.\\\"\\\"\\\"\\n\\n    def _clean_serve_env(self) -> dict[str, str]:\\n        return {k: v for k, v in os.environ.items() if not k.startswith(\\\"LFX_SERVE_\\\")}\\n\\n    def test_header_mode_round_trips_through_create_serve_app(self):\\n        cfg = IdentityConfig(mode=\\\"header\\\", trusted_header=\\\"X-Consumer-Username\\\")\\n        env = {**self._clean_serve_env(), \\\"LANGFLOW_API_KEY\\\": API_KEY, **cfg.to_env()}\\n        with patch.dict(os.environ, env, clear=True):\\n            app = create_serve_app()\\n        assert app.state.identity_config == cfg\\n        assert app.state.identity_verifier is not None\\n\\n    def test_jwt_mode_round_trips_through_create_serve_app(self, jwks):\\n        cfg = IdentityConfig(\\n            mode=\\\"jwt\\\",\\n            jwt_issuer=ISSUER,\\n            jwt_audience=AUDIENCE,\\n            jwt_jwks_url=\\\"https://accounts.example.com/jwks\\\",\\n            claim=\\\"email\\\",\\n            jwt_header=\\\"X-Auth-Request-Access-Token\\\",\\n        )\\n        env = {**self._clean_serve_env(), \\\"LANGFLOW_API_KEY\\\": API_KEY, **cfg.to_env()}\\n        # Patch the network fetcher so the worker's startup prefetch stays offline.\\n        with (\\n            patch.dict(os.environ, env, clear=True),\\n            patch(\\\"lfx.cli.serve_identity._fetch_json\\\", return_value=jwks),\\n        ):\\n            app = create_serve_app()\\n        # Every field reconstructed identically in the worker.\\n        assert app.state.identity_config == cfg\\n        assert app.state.identity_verifier is not None\\n\\n\\nclass TestServeAppIdentityEndpoints:\\n    def test_off_mode_requires_no_identity_and_threads_none(self, real_graph):\\n        captured: dict = {}\\n\\n        async def mock_execute(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"user_id\\\"] = user_id\\n            return [], \\\"\\\"\\n\\n        client = _client_with_verifier(real_graph, None)\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": API_KEY}),\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute),\\n        ):\\n            resp = client.post(f\\\"/flows/{FLOW_ID}/run\\\", json={\\\"input_value\\\": \\\"hi\\\"}, headers={\\\"x-api-key\\\": API_KEY})\\n        assert resp.status_code != 401\\n        assert captured[\\\"user_id\\\"] is None  # off mode \u21d2 no identity threaded\\n\\n    def test_jwt_valid_token_threads_identity_into_run(self, real_graph, verifier, keypair):\\n        captured: dict = {}\\n\\n        async def mock_execute(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"user_id\\\"] = user_id\\n            return [], \\\"\\\"\\n\\n        token = _sign(keypair, {\\\"email\\\": \\\"alice@example.com\\\"})\\n        client = _client_with_verifier(real_graph, verifier)\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": API_KEY}),\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute),\\n        ):\\n            resp = client.post(\\n                f\\\"/flows/{FLOW_ID}/run\\\",\\n                json={\\\"input_value\\\": \\\"hi\\\"},\\n                headers={\\\"x-api-key\\\": API_KEY, \\\"Authorization\\\": f\\\"Bearer {token}\\\"},\\n            )\\n        assert resp.status_code != 401\\n        assert captured[\\\"user_id\\\"] == \\\"alice@example.com\\\"\\n\\n    def test_jwt_valid_token_threads_identity_into_stream(self, real_graph, verifier, keypair):\\n        captured: dict = {}\\n\\n        async def mock_execute(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"user_id\\\"] = user_id\\n            return [], \\\"\\\"\\n\\n        token = _sign(keypair, {\\\"email\\\": \\\"bob@example.com\\\"})\\n        client = _client_with_verifier(real_graph, verifier)\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": API_KEY}),\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute),\\n            client.stream(\\n                \\\"POST\\\",\\n                f\\\"/flows/{FLOW_ID}/stream\\\",\\n                json={\\\"input_value\\\": \\\"hi\\\"},\\n                headers={\\\"x-api-key\\\": API_KEY, \\\"Authorization\\\": f\\\"Bearer {token}\\\"},\\n            ) as resp,\\n        ):\\n            assert resp.status_code == 200\\n            for _ in resp.iter_bytes():\\n                pass\\n        assert captured[\\\"user_id\\\"] == \\\"bob@example.com\\\"\\n\\n    def test_jwt_invalid_token_rejected_before_execution(self, real_graph, verifier):\\n        execute = MagicMock()\\n        client = _client_with_verifier(real_graph, verifier)\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": API_KEY}),\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", execute),\\n        ):\\n            resp = client.post(\\n                f\\\"/flows/{FLOW_ID}/run\\\",\\n                json={\\\"input_value\\\": \\\"hi\\\"},\\n                headers={\\\"x-api-key\\\": API_KEY, \\\"Authorization\\\": \\\"Bearer garbage.token.here\\\"},\\n            )\\n        assert resp.status_code == 401\\n        execute.assert_not_called()\\n\\n    def test_serve_key_floor_enforced_even_with_valid_token(self, real_graph, verifier, keypair):\\n        \\\"\\\"\\\"A valid identity token must NOT bypass the serve API key.\\\"\\\"\\\"\\n        execute = MagicMock()\\n        token = _sign(keypair, {\\\"email\\\": \\\"alice@example.com\\\"})\\n        client = _client_with_verifier(real_graph, verifier)\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": API_KEY}),\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", execute),\\n        ):\\n            resp = client.post(\\n                f\\\"/flows/{FLOW_ID}/run\\\",\\n                json={\\\"input_value\\\": \\\"hi\\\"},\\n                headers={\\\"Authorization\\\": f\\\"Bearer {token}\\\"},  # no x-api-key\\n            )\\n        assert resp.status_code == 401\\n        execute.assert_not_called()\\n\\n    def test_header_mode_threads_identity(self, real_graph):\\n        captured: dict = {}\\n\\n        async def mock_execute(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n            captured[\\\"user_id\\\"] = user_id\\n            return [], \\\"\\\"\\n\\n        cfg = IdentityConfig(mode=\\\"header\\\", trusted_header=\\\"X-Consumer-Username\\\")\\n        client = _client_with_verifier(real_graph, build_identity_verifier(cfg))\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": API_KEY}),\\n            patch(\\\"lfx.cli.serve_app.execute_graph_with_capture\\\", mock_execute),\\n        ):\\n            resp = client.post(\\n                f\\\"/flows/{FLOW_ID}/run\\\",\\n                json={\\\"input_value\\\": \\\"hi\\\"},\\n                headers={\\\"x-api-key\\\": API_KEY, \\\"X-Consumer-Username\\\": \\\"kong-user-7\\\"},\\n            )\\n        assert resp.status_code != 401\\n        assert captured[\\\"user_id\\\"] == \\\"kong-user-7\\\"\\n\\n    def test_workflow_invalid_token_rejected_before_execution(self, real_graph, verifier):\\n        \\\"\\\"\\\"POST /workflows must enforce the identity mode like /flows/{id}/run (no bypass).\\\"\\\"\\\"\\n        run = MagicMock()\\n        client = _client_with_verifier(real_graph, verifier)\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": API_KEY}),\\n            patch(\\\"lfx.workflow.router.run_graph_internal\\\", run),\\n        ):\\n            resp = client.post(\\n                \\\"/api/v2/workflows\\\",\\n                json={\\\"flow_id\\\": FLOW_ID, \\\"input_value\\\": \\\"hi\\\", \\\"mode\\\": \\\"sync\\\"},\\n                headers={\\\"x-api-key\\\": API_KEY, \\\"Authorization\\\": \\\"Bearer garbage.token.here\\\"},\\n            )\\n        assert resp.status_code == 401\\n        run.assert_not_called()\\n\\n    def test_workflow_sync_threads_identity(self, real_graph, verifier, keypair):\\n        captured: dict = {}\\n\\n        async def mock_run(graph, flow_id, **_kwargs):  # noqa: ARG001\\n            captured[\\\"user_id\\\"] = graph.user_id\\n            return [], \\\"sess\\\"\\n\\n        token = _sign(keypair, {\\\"email\\\": \\\"carol@example.com\\\"})\\n        client = _client_with_verifier(real_graph, verifier)\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": API_KEY}),\\n            patch(\\\"lfx.workflow.router.run_graph_internal\\\", mock_run),\\n        ):\\n            resp = client.post(\\n                \\\"/api/v2/workflows\\\",\\n                json={\\\"flow_id\\\": FLOW_ID, \\\"input_value\\\": \\\"hi\\\", \\\"mode\\\": \\\"sync\\\"},\\n                headers={\\\"x-api-key\\\": API_KEY, \\\"Authorization\\\": f\\\"Bearer {token}\\\"},\\n            )\\n        assert resp.status_code != 401\\n        assert captured[\\\"user_id\\\"] == \\\"carol@example.com\\\"\\n\\n    def test_workflow_stream_threads_identity(self, real_graph, verifier, keypair):\\n        captured: dict = {}\\n\\n        async def mock_execute(graph, input_value, session_id=None, user_id=None, event_manager=None):  # noqa: ARG001\\n            captured[\\\"user_id\\\"] = user_id\\n            return [], \\\"\\\"\\n\\n        token = _sign(keypair, {\\\"email\\\": \\\"dave@example.com\\\"})\\n        client = _client_with_verifier(real_graph, verifier)\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": API_KEY}),\\n            patch(\\\"lfx.workflow.router.execute_graph_with_capture\\\", mock_execute),\\n            client.stream(\\n                \\\"POST\\\",\\n                \\\"/api/v2/workflows\\\",\\n                json={\\\"flow_id\\\": FLOW_ID, \\\"input_value\\\": \\\"hi\\\", \\\"mode\\\": \\\"stream\\\"},\\n                headers={\\\"x-api-key\\\": API_KEY, \\\"Authorization\\\": f\\\"Bearer {token}\\\"},\\n            ) as resp,\\n        ):\\n            assert resp.status_code == 200\\n            for _ in resp.iter_bytes():\\n                pass\\n        assert captured[\\\"user_id\\\"] == \\\"dave@example.com\\\"\\n\\n\\nclass TestExecuteGraphUserIdThreading:\\n    \\\"\\\"\\\"The user_id contract in execute_graph_with_capture.\\n\\n    Covers the off-mode preservation the docstrings describe: None keeps the\\n    graph's existing user_id, a verified value overwrites it. async_start is\\n    stubbed so only the apply_run_defaults stamping logic runs, not a full flow.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _stub_async_start(real_graph):\\n        async def _no_results(*_args, **_kwargs):\\n            return\\n            yield  # make it an (empty) async generator\\n\\n        real_graph.async_start = _no_results\\n\\n    async def test_none_user_id_preserves_existing_graph_user_id(self, real_graph):\\n        self._stub_async_start(real_graph)\\n        real_graph.user_id = \\\"preexisting-user\\\"\\n        await execute_graph_with_capture(real_graph, \\\"hi\\\", user_id=None)\\n        assert real_graph.user_id == \\\"preexisting-user\\\"\\n\\n    async def test_verified_user_id_overwrites_graph_user_id(self, real_graph):\\n        self._stub_async_start(real_graph)\\n        real_graph.user_id = \\\"preexisting-user\\\"\\n        await execute_graph_with_capture(real_graph, \\\"hi\\\", user_id=\\\"alice@example.com\\\")\\n        assert real_graph.user_id == \\\"alice@example.com\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_process_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2a073bc7685c6e03113ab51da917887344b922d5c9c9cf3c7942b8cedb3707b1\",\"content\":\"\\\"\\\"\\\"Process-model tests for `lfx serve` per-request-isolated execution.\\n\\nCovers the preload/warm/guard/fork-safety pieces of the gunicorn\\n``--preload`` + ``max_requests=1`` architecture:\\n\\n- ``build_registry_from_env`` builds and warms a registry from the LFX_SERVE_*\\n  environment (the single source reused by the uvicorn factory and the gunicorn\\n  preload master).\\n- ``serve_preloaded_app`` builds the warm app at import time (freezing happens in\\n  the gunicorn ``pre_fork`` hook, not at import).\\n- ``LFXGunicornApp`` translates options into a gunicorn config and runs the\\n  ``pre_fork`` fork-safety hook (gc.freeze + ghost-thread/connection diagnostics).\\n- The single-in-flight execute guard serializes the env-sensitive section.\\n- Fork-safety regressions: DB-less serve, uuid4-based ids, preload must not open\\n  the DB or start background threads, and the pre_fork guardrail must fire.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n\\ndef _write_flow(flow_dir: Path, flow_id: str) -> None:\\n    \\\"\\\"\\\"Write a minimal empty-graph flow JSON into *flow_dir* as ``{flow_id}.json``.\\n\\n    An empty graph (no nodes/edges) reconstructs via ``load_flow_from_json`` +\\n    ``graph.prepare()`` without requiring the component-type cache to be\\n    initialised, so warming exercises the real ``FilesystemFlowStore`` round-trip\\n    without external setup. This mirrors the reconstructable fixtures used by the\\n    existing serve tests.\\n    \\\"\\\"\\\"\\n    raw = {\\n        \\\"name\\\": flow_id,\\n        \\\"description\\\": None,\\n        \\\"id\\\": flow_id,\\n        \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n    }\\n    (flow_dir / f\\\"{flow_id}.json\\\").write_text(json.dumps(raw), encoding=\\\"utf-8\\\")\\n\\n\\ndef test_build_registry_from_env_warms_store(tmp_path, monkeypatch):\\n    from lfx.cli import serve_app\\n\\n    flow_dir = tmp_path / \\\"flows\\\"\\n    flow_dir.mkdir()\\n    _write_flow(flow_dir, \\\"flow-1\\\")\\n    monkeypatch.setenv(serve_app._SERVE_FLOW_DIR_ENV, str(flow_dir))\\n    monkeypatch.setenv(serve_app._SERVE_NO_ENV_FALLBACK_ENV, \\\"1\\\")\\n    monkeypatch.setenv(serve_app._SERVE_STARTUP_PATHS_ENV, \\\"\\\")\\n\\n    registry = serve_app.build_registry_from_env()\\n\\n    assert registry.get(\\\"flow-1\\\") is not None  # warm, not lazy\\n    assert registry._no_env_fallback is True\\n\\n\\ndef test_preloaded_app_module_builds_warm_app(tmp_path, monkeypatch):\\n    import importlib\\n\\n    from fastapi import FastAPI\\n    from lfx.cli import serve_app\\n\\n    flow_dir = tmp_path / \\\"flows\\\"\\n    flow_dir.mkdir()\\n    _write_flow(flow_dir, \\\"flow-1\\\")\\n    monkeypatch.setenv(serve_app._SERVE_FLOW_DIR_ENV, str(flow_dir))\\n    monkeypatch.setenv(serve_app._SERVE_NO_ENV_FALLBACK_ENV, \\\"0\\\")\\n    monkeypatch.setenv(serve_app._SERVE_STARTUP_PATHS_ENV, \\\"\\\")\\n\\n    import lfx.cli.serve_preloaded_app as mod\\n\\n    importlib.reload(mod)  # re-run import-time build under patched env\\n\\n    assert isinstance(mod.app, FastAPI)\\n    assert mod.registry.get(\\\"flow-1\\\") is not None\\n    # The module does NOT freeze at import; freezing happens in the gunicorn\\n    # pre_fork hook (see test_gunicorn_pre_fork_freezes_heap).\\n\\n    # Reset the module's import-time state so the warm app/registry built here don't\\n    # leak into later tests that import lfx.cli.serve_preloaded_app without reloading.\\n    for key in (\\n        serve_app._SERVE_FLOW_DIR_ENV,\\n        serve_app._SERVE_NO_ENV_FALLBACK_ENV,\\n        serve_app._SERVE_STARTUP_PATHS_ENV,\\n    ):\\n        monkeypatch.delenv(key, raising=False)\\n    importlib.reload(mod)\\n\\n\\n@pytest.mark.skipif(sys.platform == \\\"win32\\\", reason=\\\"gunicorn is Unix-only\\\")\\ndef test_gunicorn_pre_fork_freezes_heap_and_runs_clean(monkeypatch):\\n    \\\"\\\"\\\"The pre_fork hook calls gc.freeze() (preserving COW) and runs without raising.\\n\\n    Spies on gc.freeze directly rather than gc.get_freeze_count(): the hook also\\n    calls gc.collect(), which by itself bumps the freeze count, so a count-based\\n    assertion would pass even if gc.freeze() were removed.\\n    \\\"\\\"\\\"\\n    import gc\\n    from unittest.mock import MagicMock\\n\\n    from lfx.cli.serve_gunicorn import LFXGunicornApp\\n\\n    class _FakeLog:\\n        def warning(self, *_a, **_k):\\n            pass\\n\\n        def debug(self, *_a, **_k):\\n            pass\\n\\n    class _FakeServer:\\n        log = _FakeLog()\\n\\n    freeze_spy = MagicMock()\\n    monkeypatch.setattr(gc, \\\"freeze\\\", freeze_spy)\\n\\n    LFXGunicornApp.pre_fork(_FakeServer(), None)\\n\\n    freeze_spy.assert_called_once()  # gc.freeze() ran in the hook\\n\\n\\n@pytest.mark.skipif(sys.platform == \\\"win32\\\", reason=\\\"gunicorn is Unix-only\\\")\\ndef test_gunicorn_app_registers_pre_fork_hook():\\n    from lfx.cli.serve_gunicorn import LFXGunicornApp\\n\\n    gapp = LFXGunicornApp(\\\"lfx.cli.serve_preloaded_app:app\\\", {\\\"workers\\\": 2})\\n    gapp.load_config()\\n    # The pre_fork hook is wired into gunicorn's config so it runs before each fork.\\n    # (Bound classmethods aren't identity-equal across accesses; compare the function.\\n    # getattr default keeps this a clean assertion failure if the hook isn't wired,\\n    # since gunicorn's default pre_fork is a plain function with no __func__.)\\n    assert getattr(gapp.cfg.pre_fork, \\\"__func__\\\", None) is LFXGunicornApp.pre_fork.__func__\\n\\n\\n@pytest.mark.skipif(sys.platform == \\\"win32\\\", reason=\\\"gunicorn is Unix-only\\\")\\ndef test_gunicorn_app_sets_options():\\n    from lfx.cli.serve_gunicorn import LFXGunicornApp\\n\\n    opts = {\\n        \\\"bind\\\": \\\"127.0.0.1:7860\\\",\\n        \\\"workers\\\": 4,\\n        \\\"worker_class\\\": \\\"uvicorn.workers.UvicornWorker\\\",\\n        \\\"preload_app\\\": True,\\n        \\\"max_requests\\\": 1,\\n        \\\"max_requests_jitter\\\": 0,\\n        \\\"loglevel\\\": \\\"info\\\",\\n    }\\n    gapp = LFXGunicornApp(\\\"lfx.cli.serve_preloaded_app:app\\\", opts)\\n    gapp.load_config()\\n    assert gapp.cfg.workers == 4\\n    assert gapp.cfg.max_requests == 1\\n    assert gapp.cfg.preload_app is True\\n    # gunicorn resolves worker_class to the loaded class; the original import\\n    # string is preserved on worker_class_str.\\n    assert gapp.cfg.worker_class_str == \\\"uvicorn.workers.UvicornWorker\\\"\\n\\n\\ndef _assert_worker_env_cleaned():\\n    import os as _os\\n\\n    from lfx.cli.serve_app import (\\n        _SERVE_FLOW_DIR_ENV,\\n        _SERVE_NO_ENV_FALLBACK_ENV,\\n        _SERVE_RESET_ENVIRON_ENV,\\n        _SERVE_STARTUP_PATHS_ENV,\\n    )\\n\\n    for key in (_SERVE_FLOW_DIR_ENV, _SERVE_NO_ENV_FALLBACK_ENV, _SERVE_RESET_ENVIRON_ENV, _SERVE_STARTUP_PATHS_ENV):\\n        assert key not in _os.environ\\n\\n\\ndef test_windows_multiworker_default_falls_back_to_uvicorn(monkeypatch, tmp_path):\\n    \\\"\\\"\\\"On Windows with no --max-requests, multi-worker falls back to uvicorn (no isolation).\\\"\\\"\\\"\\n    from lfx.cli import commands\\n\\n    monkeypatch.setattr(commands.sys, \\\"platform\\\", \\\"win32\\\")\\n\\n    called = {}\\n\\n    def fake_uvicorn_run(app_str, **kwargs):\\n        called[\\\"app\\\"] = app_str\\n        called[\\\"kwargs\\\"] = kwargs\\n\\n    monkeypatch.setattr(commands.uvicorn, \\\"run\\\", fake_uvicorn_run)\\n\\n    commands._launch_workers(\\n        host=\\\"127.0.0.1\\\",\\n        port=8000,\\n        workers=2,\\n        log_level=\\\"warning\\\",\\n        flow_dir=tmp_path,\\n        no_env_fallback=False,\\n        script_paths=None,\\n        temp_file_to_cleanup=None,\\n        verbose_print=lambda *_a, **_k: None,\\n        max_requests=None,\\n    )\\n\\n    # Falls back to the uvicorn factory multi-worker path, not gunicorn.\\n    assert called[\\\"app\\\"] == \\\"lfx.cli.serve_app:create_serve_app\\\"\\n    assert called[\\\"kwargs\\\"].get(\\\"workers\\\") == 2\\n    assert called[\\\"kwargs\\\"].get(\\\"factory\\\") is True\\n    _assert_worker_env_cleaned()\\n\\n\\ndef test_windows_multiworker_with_max_requests_errors(monkeypatch, tmp_path, capsys):\\n    \\\"\\\"\\\"On Windows, requesting isolation via --max-requests is refused (gunicorn unavailable).\\n\\n    The refusal must be visible without ``-v`` (verbose_print is a no-op by default), so the\\n    message goes to stderr via typer.echo \u2014 assert it actually reaches the user.\\n    \\\"\\\"\\\"\\n    import typer\\n    from lfx.cli import commands\\n\\n    monkeypatch.setattr(commands.sys, \\\"platform\\\", \\\"win32\\\")\\n\\n    with pytest.raises(typer.Exit):\\n        commands._launch_workers(\\n            host=\\\"127.0.0.1\\\",\\n            port=8000,\\n            workers=2,\\n            log_level=\\\"warning\\\",\\n            flow_dir=tmp_path,\\n            no_env_fallback=False,\\n            script_paths=None,\\n            temp_file_to_cleanup=None,\\n            verbose_print=lambda *_a, **_k: None,\\n            max_requests=1,\\n        )\\n\\n    # Loud failure: the error reaches stderr even though verbose_print is a no-op.\\n    assert \\\"--max-requests\\\" in capsys.readouterr().err\\n    _assert_worker_env_cleaned()\\n\\n\\nasync def test_guarded_execute_serializes(monkeypatch):\\n    import asyncio\\n\\n    from lfx.cli import serve_app\\n\\n    timeline = []\\n\\n    async def fake_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n        timeline.append((\\\"enter\\\", input_value))\\n        await asyncio.sleep(0.05)\\n        timeline.append((\\\"exit\\\", input_value))\\n        return ([], \\\"\\\")\\n\\n    monkeypatch.setattr(serve_app, \\\"execute_graph_with_capture\\\", fake_capture)\\n\\n    await asyncio.gather(\\n        serve_app.guarded_execute(object(), \\\"a\\\", None),\\n        serve_app.guarded_execute(object(), \\\"b\\\", None),\\n    )\\n\\n    # No interleave: each enter is immediately followed by its own exit.\\n    assert timeline in (\\n        [(\\\"enter\\\", \\\"a\\\"), (\\\"exit\\\", \\\"a\\\"), (\\\"enter\\\", \\\"b\\\"), (\\\"exit\\\", \\\"b\\\")],\\n        [(\\\"enter\\\", \\\"b\\\"), (\\\"exit\\\", \\\"b\\\"), (\\\"enter\\\", \\\"a\\\"), (\\\"exit\\\", \\\"a\\\")],\\n    )\\n\\n\\ndef test_upload_visible_to_fresh_worker(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"Upload via one registry must be reconstructable by a freshly forked worker.\\n\\n    The fresh worker builds its registry from the same shared store. This is the\\n    multi-worker upload contract under per-request recycling: the\\n    uploading worker persists raw_json to the FilesystemFlowStore; any later\\n    worker rebuilds the graph from the store on a cache miss.\\n    \\\"\\\"\\\"\\n    from lfx.cli import serve_app\\n    from lfx.cli.flow_store import FilesystemFlowStore\\n    from lfx.load import load_flow_from_json\\n\\n    store_dir = tmp_path / \\\"store\\\"\\n    store_dir.mkdir()\\n\\n    raw = {\\\"name\\\": \\\"uploaded\\\", \\\"id\\\": \\\"uploaded-1\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n\\n    # Registry A \\\"uploads\\\" the flow: registry.add persists raw_json to the store.\\n    registry_a = serve_app.FlowRegistry(store=FilesystemFlowStore(store_dir))\\n    graph_a = load_flow_from_json(raw)\\n    graph_a.prepare()\\n    meta_a = serve_app.FlowMeta(id=\\\"uploaded-1\\\", relative_path=\\\"<upload>\\\", title=\\\"uploaded\\\", description=None)\\n    registry_a.add(graph_a, meta_a, raw_json=raw)\\n\\n    # Registry B simulates a freshly forked worker: build from the same store via env.\\n    monkeypatch.setenv(serve_app._SERVE_FLOW_DIR_ENV, str(store_dir))\\n    monkeypatch.setenv(serve_app._SERVE_NO_ENV_FALLBACK_ENV, \\\"0\\\")\\n    monkeypatch.setenv(serve_app._SERVE_STARTUP_PATHS_ENV, \\\"\\\")\\n    registry_b = serve_app.build_registry_from_env()\\n\\n    assert registry_b.get(\\\"uploaded-1\\\") is not None\\n\\n\\ndef test_serve_context_is_db_less():\\n    \\\"\\\"\\\"`lfx serve` is DB-less: get_db_service() returns a NoopDatabaseService.\\n\\n    Guards against a future change that would make per-fork DB connection reinit\\n    necessary (preload + fork would then need a post-fork pool reset).\\n    \\\"\\\"\\\"\\n    from lfx.services.database.service import NoopDatabaseService\\n    from lfx.services.deps import get_db_service\\n\\n    assert isinstance(get_db_service(), NoopDatabaseService)\\n\\n\\ndef test_uuid4_is_unique_and_fork_safe():\\n    \\\"\\\"\\\"uuid4 (os.urandom-backed) is fork-safe and collision-free for flow ids.\\n\\n    A forked worker must not reproduce the parent's RNG stream. uuid4 draws from\\n    os.urandom, which is re-seeded per process, so generated ids stay unique.\\n    \\\"\\\"\\\"\\n    import uuid\\n\\n    ids = {str(uuid.uuid4()) for _ in range(10_000)}\\n    assert len(ids) == 10_000\\n\\n\\ndef _build_preloaded(monkeypatch, tmp_path):\\n    \\\"\\\"\\\"Run the exact work the gunicorn preload master does: build + warm the app.\\\"\\\"\\\"\\n    from lfx.cli import serve_app\\n\\n    flow_dir = tmp_path / \\\"flows\\\"\\n    flow_dir.mkdir()\\n    _write_flow(flow_dir, \\\"flow-1\\\")\\n    monkeypatch.setenv(serve_app._SERVE_FLOW_DIR_ENV, str(flow_dir))\\n    monkeypatch.setenv(serve_app._SERVE_NO_ENV_FALLBACK_ENV, \\\"0\\\")\\n    monkeypatch.setenv(serve_app._SERVE_STARTUP_PATHS_ENV, \\\"\\\")\\n    registry = serve_app.build_registry_from_env()\\n    return serve_app.create_multi_serve_app(registry=registry)\\n\\n\\ndef test_preload_does_not_open_the_database(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"Fork-safety invariant: building/warming the preload app must NOT open a DB session.\\n\\n    This is the property that keeps lfx serve fork-safe with a pluggable DB: if the\\n    preload master opened a session, an eager-engine DB service would create its\\n    connection pool pre-fork and every forked worker would inherit/corrupt it. A\\n    spy on get_db_service() catches all DB access (session_scope resolves it at\\n    call-time), so this fails loudly if any future preload step touches the DB.\\n    \\\"\\\"\\\"\\n    from contextlib import asynccontextmanager\\n\\n    from lfx.services import deps\\n\\n    opened = {\\\"count\\\": 0}\\n\\n    class _SpyDB:\\n        @asynccontextmanager\\n        async def _with_session(self):\\n            opened[\\\"count\\\"] += 1\\n            from lfx.services.session import NoopSession\\n\\n            async with NoopSession() as session:\\n                yield session\\n\\n    monkeypatch.setattr(deps, \\\"get_db_service\\\", lambda: _SpyDB())\\n\\n    _build_preloaded(monkeypatch, tmp_path)\\n\\n    assert opened[\\\"count\\\"] == 0, \\\"preload opened a DB session \u2014 fork-unsafe with a real DB service\\\"\\n\\n\\ndef test_preload_starts_no_fork_unsafe_background_threads(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"Fork-safety invariant: building the preload app must not leave non-benign threads.\\n\\n    Background threads (telemetry, threaded logging, schedulers) are NOT inherited\\n    by forks, so any started during preload would silently die in workers \u2014 and one\\n    holding a lock at fork could deadlock the child.\\n    \\\"\\\"\\\"\\n    import threading\\n\\n    from lfx.cli.serve_gunicorn import LFXGunicornApp\\n\\n    before = {t.ident for t in threading.enumerate()}\\n    _build_preloaded(monkeypatch, tmp_path)\\n    new_alive = [t for t in threading.enumerate() if t.ident not in before and t.is_alive()]\\n    suspicious = [t for t in new_alive if not LFXGunicornApp._is_benign_thread(t)]\\n\\n    assert not suspicious, f\\\"preload started fork-unsafe background threads: {[t.name for t in suspicious]}\\\"\\n\\n\\n@pytest.mark.skipif(sys.platform == \\\"win32\\\", reason=\\\"gunicorn is Unix-only\\\")\\ndef test_pre_fork_flags_ghost_thread_but_not_benign():\\n    \\\"\\\"\\\"The pre_fork guardrail warns about a ghost thread but not a benign one.\\n\\n    It must warn about a non-benign thread alive before fork and must NOT flag a\\n    benign-named one.\\n    \\\"\\\"\\\"\\n    import threading\\n\\n    from lfx.cli.serve_gunicorn import LFXGunicornApp\\n\\n    warnings: list[str] = []\\n\\n    class _Log:\\n        def warning(self, msg, *args):\\n            warnings.append(msg % args if args else msg)\\n\\n        def debug(self, *_a, **_k):\\n            pass\\n\\n    class _Server:\\n        log = _Log()\\n\\n    stop = threading.Event()\\n    ghost = threading.Thread(target=stop.wait, name=\\\"EvilGhostThread\\\", daemon=True)\\n    benign = threading.Thread(target=stop.wait, name=\\\"OTel-benign\\\", daemon=True)\\n    ghost.start()\\n    benign.start()\\n    try:\\n        LFXGunicornApp.pre_fork(_Server(), None)\\n    finally:\\n        stop.set()\\n        ghost.join(timeout=2)\\n        benign.join(timeout=2)\\n\\n    blob = \\\"\\\\n\\\".join(warnings)\\n    assert \\\"Ghost threads\\\" in blob, warnings\\n    assert \\\"EvilGhostThread\\\" in blob, warnings\\n    assert \\\"OTel-benign\\\" not in blob  # benign-named threads are filtered out\\n\\n\\n@pytest.mark.skipif(sys.platform == \\\"win32\\\", reason=\\\"gunicorn is Unix-only\\\")\\ndef test_pre_fork_does_not_flag_gunicorn_own_threads():\\n    \\\"\\\"\\\"Gunicorn's own master-only threads (target in the gunicorn package) must not be flagged.\\\"\\\"\\\"\\n    import threading\\n\\n    from lfx.cli.serve_gunicorn import LFXGunicornApp\\n\\n    stop = threading.Event()\\n\\n    def _run_loop():  # mimics gunicorn.ctl.server.ControlSocketServer._run_loop\\n        stop.wait()\\n\\n    _run_loop.__module__ = \\\"gunicorn.ctl.server\\\"  # benign discriminator: target owned by gunicorn\\n    gthread = threading.Thread(target=_run_loop, daemon=True)\\n    gthread.start()\\n    try:\\n        assert LFXGunicornApp._is_benign_thread(gthread) is True\\n    finally:\\n        stop.set()\\n        gthread.join(timeout=2)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Opt-in flags: --reset-environ (os.environ snapshot/restore) and --use-sync-workers\\n# (gunicorn sync worker + a2wsgi bridge). Both default OFF so the committed\\n# behavior is unchanged; these tests assert the opt-in wiring.\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_guarded_execute_restores_environ_when_enabled(monkeypatch):\\n    \\\"\\\"\\\"With LFX_SERVE_RESET_ENVIRON=1, a flow's os.environ mutation is rolled back.\\\"\\\"\\\"\\n    from lfx.cli import serve_app\\n\\n    monkeypatch.setenv(serve_app._SERVE_RESET_ENVIRON_ENV, \\\"1\\\")\\n    monkeypatch.delenv(\\\"LEAKED_BY_FLOW\\\", raising=False)\\n\\n    async def fake_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n        os.environ[\\\"LEAKED_BY_FLOW\\\"] = \\\"secret\\\"\\n        return ([], \\\"\\\")\\n\\n    monkeypatch.setattr(serve_app, \\\"execute_graph_with_capture\\\", fake_capture)\\n    await serve_app.guarded_execute(object(), \\\"a\\\", None)\\n\\n    # The mutation made during the run is restored after it (no cross-request leak).\\n    assert \\\"LEAKED_BY_FLOW\\\" not in os.environ\\n\\n\\nasync def test_guarded_execute_restore_never_clears_environ(monkeypatch):\\n    \\\"\\\"\\\"The reset-environ restore is diff-based and must never call os.environ.clear().\\n\\n    verify_api_key is a sync dependency FastAPI runs on a threadpool thread, so if the\\n    restore emptied os.environ key-by-key a concurrent auth check could see the API key\\n    transiently gone and 401. This locks the fix in CI (the integration harness is\\n    CI-skipped): keys the run never touched stay put, and clear() is never used.\\n    \\\"\\\"\\\"\\n    from lfx.cli import serve_app\\n\\n    monkeypatch.setenv(serve_app._SERVE_RESET_ENVIRON_ENV, \\\"1\\\")\\n    monkeypatch.setenv(\\\"GUARD_UNTOUCHED\\\", \\\"keep\\\")  # a key the flow never mutates (e.g. the API key)\\n    monkeypatch.setenv(\\\"GUARD_CHANGED\\\", \\\"original\\\")\\n    monkeypatch.setenv(\\\"GUARD_DELETED\\\", \\\"present\\\")\\n    monkeypatch.delenv(\\\"GUARD_ADDED\\\", raising=False)\\n\\n    cleared = False\\n    real_clear = os.environ.clear\\n\\n    def _tracking_clear():\\n        nonlocal cleared\\n        cleared = True\\n        real_clear()\\n\\n    monkeypatch.setattr(os.environ, \\\"clear\\\", _tracking_clear)\\n\\n    async def fake_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n        # A custom component can add, change, or delete env vars mid-run \u2014 all three roll back.\\n        os.environ[\\\"GUARD_ADDED\\\"] = \\\"leak\\\"\\n        os.environ[\\\"GUARD_CHANGED\\\"] = \\\"mutated\\\"\\n        del os.environ[\\\"GUARD_DELETED\\\"]\\n        return ([], \\\"\\\")\\n\\n    monkeypatch.setattr(serve_app, \\\"execute_graph_with_capture\\\", fake_capture)\\n    await serve_app.guarded_execute(object(), \\\"a\\\", None)\\n\\n    assert cleared is False, \\\"restore must not use os.environ.clear() (races with threadpool auth)\\\"\\n    assert os.environ[\\\"GUARD_UNTOUCHED\\\"] == \\\"keep\\\"  # untouched key never removed\\n    assert os.environ[\\\"GUARD_CHANGED\\\"] == \\\"original\\\"  # changed key reverted\\n    assert os.environ[\\\"GUARD_DELETED\\\"] == \\\"present\\\"  # deleted key restored\\n    assert \\\"GUARD_ADDED\\\" not in os.environ  # added key removed\\n\\n\\nasync def test_guarded_execute_does_not_reset_environ_by_default(monkeypatch):\\n    \\\"\\\"\\\"Default (flag off): os.environ mutations persist \u2014 committed behavior is unchanged.\\\"\\\"\\\"\\n    from lfx.cli import serve_app\\n\\n    monkeypatch.delenv(serve_app._SERVE_RESET_ENVIRON_ENV, raising=False)\\n    monkeypatch.delenv(\\\"LEAKED_BY_FLOW\\\", raising=False)\\n\\n    async def fake_capture(graph, input_value, session_id=None, user_id=None):  # noqa: ARG001\\n        os.environ[\\\"LEAKED_BY_FLOW\\\"] = \\\"secret\\\"\\n        return ([], \\\"\\\")\\n\\n    monkeypatch.setattr(serve_app, \\\"execute_graph_with_capture\\\", fake_capture)\\n    try:\\n        await serve_app.guarded_execute(object(), \\\"a\\\", None)\\n        assert os.environ.get(\\\"LEAKED_BY_FLOW\\\") == \\\"secret\\\"  # not restored\\n    finally:\\n        monkeypatch.delenv(\\\"LEAKED_BY_FLOW\\\", raising=False)\\n\\n\\ndef _capture_gunicorn_launch(monkeypatch, **launch_overrides):\\n    \\\"\\\"\\\"Run ``_launch_workers`` on the Unix gunicorn path with a fake LFXGunicornApp.\\n\\n    Returns a dict with the captured ``app_import_string``, gunicorn ``options``,\\n    and a snapshot of ``os.environ`` taken inside ``run()`` (i.e. what forked\\n    workers would inherit).\\n    \\\"\\\"\\\"\\n    from lfx.cli import commands\\n\\n    captured: dict = {}\\n\\n    class FakeGunicornApp:\\n        def __init__(self, app_import_string, options):\\n            captured[\\\"app_import_string\\\"] = app_import_string\\n            captured[\\\"options\\\"] = options\\n\\n        def run(self):\\n            captured[\\\"env\\\"] = dict(os.environ)\\n\\n    monkeypatch.setattr(\\\"lfx.cli.serve_gunicorn.LFXGunicornApp\\\", FakeGunicornApp)\\n    kwargs = {\\n        \\\"host\\\": \\\"127.0.0.1\\\",\\n        \\\"port\\\": 8000,\\n        \\\"workers\\\": 2,\\n        \\\"log_level\\\": \\\"warning\\\",\\n        \\\"flow_dir\\\": None,\\n        \\\"no_env_fallback\\\": False,\\n        \\\"script_paths\\\": None,\\n        \\\"temp_file_to_cleanup\\\": None,\\n        \\\"verbose_print\\\": lambda *_a, **_k: None,\\n        \\\"max_requests\\\": None,\\n    }\\n    kwargs.update(launch_overrides)\\n    commands._launch_workers(**kwargs)\\n    return captured\\n\\n\\ndef test_launch_workers_default_uses_async_uvicorn_worker(monkeypatch):\\n    \\\"\\\"\\\"Default (no --use-sync-workers): the async LFXUvicornWorker serves the ASGI app.\\\"\\\"\\\"\\n    captured = _capture_gunicorn_launch(monkeypatch)\\n    assert captured[\\\"app_import_string\\\"] == \\\"lfx.cli.serve_preloaded_app:app\\\"\\n    assert captured[\\\"options\\\"][\\\"worker_class\\\"] == \\\"lfx.cli.serve_gunicorn.LFXUvicornWorker\\\"\\n\\n\\ndef test_launch_workers_sync_workers_uses_sync_worker(monkeypatch):\\n    \\\"\\\"\\\"--use-sync-workers swaps in gunicorn's sync worker serving the a2wsgi WSGI bridge.\\\"\\\"\\\"\\n    captured = _capture_gunicorn_launch(monkeypatch, sync_workers=True)\\n    assert captured[\\\"app_import_string\\\"] == \\\"lfx.cli.serve_preloaded_app:wsgi_application\\\"\\n    assert captured[\\\"options\\\"][\\\"worker_class\\\"] == \\\"sync\\\"\\n\\n\\ndef test_launch_workers_sync_workers_without_a2wsgi_errors(monkeypatch, capsys):\\n    \\\"\\\"\\\"--use-sync-workers fails fast in the parent when a2wsgi is not installed.\\\"\\\"\\\"\\n    import typer\\n\\n    monkeypatch.setitem(sys.modules, \\\"a2wsgi\\\", None)  # forces `import a2wsgi` to raise ImportError\\n    with pytest.raises(typer.Exit):\\n        _capture_gunicorn_launch(monkeypatch, sync_workers=True)\\n    # Loud failure: the install hint reaches stderr (not gated behind -v / verbose_print).\\n    assert \\\"a2wsgi\\\" in capsys.readouterr().err\\n    # env vars set before the failed launch are still cleaned up\\n    from lfx.cli.serve_app import _SERVE_RESET_ENVIRON_ENV\\n\\n    assert _SERVE_RESET_ENVIRON_ENV not in os.environ\\n\\n\\ndef test_launch_workers_reset_environ_exports_env_for_workers(monkeypatch):\\n    \\\"\\\"\\\"--reset-environ exports LFX_SERVE_RESET_ENVIRON=1 (inherited by workers), then cleans up.\\\"\\\"\\\"\\n    from lfx.cli.serve_app import _SERVE_RESET_ENVIRON_ENV\\n\\n    captured = _capture_gunicorn_launch(monkeypatch, reset_environ=True)\\n    assert captured[\\\"env\\\"].get(_SERVE_RESET_ENVIRON_ENV) == \\\"1\\\"\\n    assert _SERVE_RESET_ENVIRON_ENV not in os.environ  # cleaned up after launch\\n\\n\\ndef test_launch_workers_reset_environ_off_by_default(monkeypatch):\\n    \\\"\\\"\\\"Without --reset-environ, the env var is exported as \\\"0\\\" (snapshot/restore disabled).\\\"\\\"\\\"\\n    from lfx.cli.serve_app import _SERVE_RESET_ENVIRON_ENV\\n\\n    captured = _capture_gunicorn_launch(monkeypatch)\\n    assert captured[\\\"env\\\"].get(_SERVE_RESET_ENVIRON_ENV) == \\\"0\\\"\\n\\n\\ndef test_launch_workers_timeout_defaults_to_120(monkeypatch):\\n    \\\"\\\"\\\"Without --timeout, gunicorn's worker timeout is 120s (long-flow safe default).\\\"\\\"\\\"\\n    captured = _capture_gunicorn_launch(monkeypatch)\\n    assert captured[\\\"options\\\"][\\\"timeout\\\"] == 120\\n\\n\\ndef test_launch_workers_timeout_propagates(monkeypatch):\\n    \\\"\\\"\\\"--timeout N is forwarded to gunicorn's worker timeout.\\\"\\\"\\\"\\n    captured = _capture_gunicorn_launch(monkeypatch, timeout=600)\\n    assert captured[\\\"options\\\"][\\\"timeout\\\"] == 600\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_simple.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c57180d4e932e97ce9a3f0ba3d5bd53c72b2175fea72a6ba2ce6de07c7fa9f10\",\"content\":\"\\\"\\\"\\\"Simple tests for LFX serve command focusing on CLI functionality.\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport tempfile\\nfrom pathlib import Path\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom typer.testing import CliRunner\\n\\n# Tests that invoke `serve` with valid-looking input may hang while langflow\\n# initialises async server infrastructure.  Skip those in CI only; all\\n# import/help/utility/fast-error tests run everywhere.\\n_ci_env = os.environ.get(\\\"CI\\\", \\\"\\\")\\n_is_ci = _ci_env.lower() in {\\\"1\\\", \\\"true\\\", \\\"yes\\\"}\\n_skip_in_ci = pytest.mark.skipif(\\n    _is_ci,\\n    reason=\\\"serve startup hangs in CI \u2014 pending root-cause fix\\\",\\n)\\n\\n\\ndef test_cli_imports():\\n    \\\"\\\"\\\"Test that we can import the CLI components.\\\"\\\"\\\"\\n    from lfx.__main__ import app, main\\n\\n    assert main is not None\\n    assert app is not None\\n\\n\\ndef test_serve_command_help():\\n    \\\"\\\"\\\"Test that serve command shows help without starting a server.\\\"\\\"\\\"\\n    from lfx.__main__ import app\\n\\n    runner = CliRunner()\\n    result = runner.invoke(app, [\\\"serve\\\", \\\"--help\\\"])\\n\\n    assert result.exit_code == 0\\n    assert \\\"Serve a flow as an API\\\" in result.output\\n\\n\\ndef test_serve_command_invalid_json():\\n    \\\"\\\"\\\"Test serve command fails fast on unparseable JSON (before any server init).\\\"\\\"\\\"\\n    from lfx.__main__ import app\\n\\n    invalid_json = '{\\\"invalid\\\": json}'\\n\\n    with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}):  # pragma: allowlist secret\\n        runner = CliRunner()\\n        result = runner.invoke(app, [\\\"serve\\\", \\\"--flow-json\\\", invalid_json], catch_exceptions=False)\\n\\n        assert result.exit_code == 1\\n\\n\\ndef test_serve_command_nonexistent_file():\\n    \\\"\\\"\\\"Test serve command fails fast when the flow file does not exist.\\\"\\\"\\\"\\n    from lfx.__main__ import app\\n\\n    with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}):  # pragma: allowlist secret\\n        runner = CliRunner()\\n        result = runner.invoke(app, [\\\"serve\\\", \\\"/path/to/nonexistent/file.json\\\"], catch_exceptions=False)\\n\\n        assert result.exit_code == 1\\n\\n\\ndef test_cli_utility_functions():\\n    \\\"\\\"\\\"Test port/host/flow-ID utilities \u2014 no server involved.\\\"\\\"\\\"\\n    from lfx.cli.common import (\\n        flow_id_from_path,\\n        get_best_access_host,\\n        get_free_port,\\n        is_port_in_use,\\n    )\\n\\n    assert not is_port_in_use(0)\\n\\n    port = get_free_port(8000)\\n    assert 8000 <= port < 65535\\n\\n    assert get_best_access_host(\\\"0.0.0.0\\\") == \\\"localhost\\\"\\n    assert get_best_access_host(\\\"\\\") == \\\"localhost\\\"\\n    assert get_best_access_host(\\\"127.0.0.1\\\") == \\\"127.0.0.1\\\"\\n\\n    root = Path(\\\"/tmp/flows\\\")\\n    path = root / \\\"test.json\\\"\\n    flow_id = flow_id_from_path(path, root)\\n    assert isinstance(flow_id, str)\\n    assert len(flow_id) == 36  # UUID\\n\\n\\n@_skip_in_ci\\ndef test_serve_command_missing_api_key():\\n    \\\"\\\"\\\"Serve command must exit 1 and mention LANGFLOW_API_KEY when no key is set.\\\"\\\"\\\"\\n    from lfx.__main__ import app\\n\\n    flow_data = {\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n\\n    with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".json\\\", delete=False) as f:\\n        json.dump(flow_data, f)\\n        temp_path = f.name\\n\\n    try:\\n        with patch.dict(os.environ, {}, clear=True):\\n            runner = CliRunner()\\n            result = runner.invoke(app, [\\\"serve\\\", temp_path])\\n\\n            assert result.exit_code == 1\\n            assert \\\"LANGFLOW_API_KEY\\\" in str(result.output or result.exception or \\\"\\\")\\n    finally:\\n        Path(temp_path).unlink()\\n\\n\\n@_skip_in_ci\\ndef test_serve_command_with_flow_json():\\n    \\\"\\\"\\\"Serve command with a valid payload should attempt to call uvicorn.run.\\\"\\\"\\\"\\n    from lfx.__main__ import app\\n\\n    flow_json = '{\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}'\\n\\n    env = {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}  # pragma: allowlist secret\\n    with patch.dict(os.environ, env), patch(\\\"uvicorn.run\\\") as mock_uvicorn:\\n        runner = CliRunner()\\n        result = runner.invoke(app, [\\\"serve\\\", \\\"--flow-json\\\", flow_json])\\n\\n        assert mock_uvicorn.called or result.exit_code != 0\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve_sync_contract.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c0db6c4089adf91df837a59609ff45b070d694c56bc71c6533de9d52ee9ccd51\",\"content\":\"\\\"\\\"\\\"Contract test locking the synchronous semantics of ``POST /flows/{id}/run``.\\n\\n``lfx serve``'s run endpoint executes the flow and returns the completed result\\nin the response body \u2014 it is NOT a job-submission endpoint that returns a task id\\nto poll. This contract underpins the per-request-isolation model (a request maps\\nto exactly one synchronous execution that finishes before the worker recycles),\\nso it is locked with an explicit test. Streaming clients use\\n``POST /flows/{id}/stream`` instead.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nfrom pathlib import Path\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom fastapi.testclient import TestClient\\nfrom lfx.cli.serve_app import FlowMeta, FlowRegistry, create_multi_serve_app\\nfrom lfx.graph import Graph\\nfrom lfx.graph.schema import ResultData\\nfrom lfx.schema.message import Message\\n\\nFLOW_ID = \\\"00000000-0000-0000-0000-000000000001\\\"\\nDATA_DIR = Path(__file__).parent.parent.parent / \\\"data\\\"\\n\\n\\n@pytest.fixture\\ndef warmed_client(monkeypatch):\\n    \\\"\\\"\\\"A TestClient over a single warmed flow with a real graph + mocked execution.\\\"\\\"\\\"\\n    from lfx.services.deps import get_settings_service\\n\\n    with (DATA_DIR / \\\"simple_chat_no_llm.json\\\").open() as f:\\n        simple_chat_json = json.load(f)\\n\\n    graph = Graph.from_payload(simple_chat_json, flow_id=FLOW_ID)\\n\\n    async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n        result_data = ResultData(\\n            results={\\\"message\\\": Message(text=\\\"Hello from flow\\\")},\\n            component_display_name=\\\"Chat Output\\\",\\n            component_id=graph.vertices[-1].id if graph.vertices else \\\"test-123\\\",\\n        )\\n        mock_result = MagicMock()\\n        mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_result.vertex.id = result_data.component_id\\n        mock_result.result_dict = result_data\\n        yield mock_result\\n\\n    graph.async_start = mock_async_start\\n\\n    registry = FlowRegistry()\\n    registry.add(graph, FlowMeta(id=FLOW_ID, relative_path=\\\"test.json\\\", title=\\\"Test Flow\\\", description=None))\\n\\n    app = create_multi_serve_app(registry=registry)\\n    monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", True)\\n\\n    with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}):  # pragma: allowlist secret\\n        yield TestClient(app)\\n\\n\\ndef test_run_endpoint_returns_completed_result(warmed_client):\\n    headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n    with (\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n        patch(\\\"lfx.cli.common.extract_structured_result\\\") as mock_extract,\\n    ):\\n        mock_extract.return_value = {\\n            \\\"result\\\": \\\"Hello from flow\\\",\\n            \\\"success\\\": True,\\n            \\\"type\\\": \\\"message\\\",\\n            \\\"component\\\": \\\"Chat Output\\\",\\n        }\\n        resp = warmed_client.post(f\\\"/flows/{FLOW_ID}/run\\\", json={\\\"input_value\\\": \\\"hi\\\"}, headers=headers)\\n\\n    assert resp.status_code == 200\\n    body = resp.json()\\n    # A completed result, not a job/task handle to poll.\\n    assert \\\"result\\\" in body\\n    assert \\\"success\\\" in body\\n    assert \\\"task_id\\\" not in body\\n    assert \\\"job_id\\\" not in body\\n\\n\\ndef test_run_endpoint_error_is_synchronous_not_a_job(warmed_client):\\n    \\\"\\\"\\\"A failing run still returns a synchronous error body, not a job/task handle to poll.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": \\\"test-api-key\\\"}\\n\\n    with (\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}),  # pragma: allowlist secret\\n        # Raise inside execution so run_flow takes its except-Exception path.\\n        patch(\\\"lfx.cli.serve_app.guarded_execute\\\", side_effect=RuntimeError(\\\"boom\\\")),\\n    ):\\n        resp = warmed_client.post(f\\\"/flows/{FLOW_ID}/run\\\", json={\\\"input_value\\\": \\\"hi\\\"}, headers=headers)\\n\\n    assert resp.status_code == 500\\n    body = resp.json()\\n    # Failure is reported in-band (success=False/type=error), never deferred to a poll handle.\\n    assert body[\\\"success\\\"] is False\\n    assert body[\\\"type\\\"] == \\\"error\\\"\\n    assert \\\"task_id\\\" not in body\\n    assert \\\"job_id\\\" not in body\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_status_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0c5a59c541ed6faea3a2088d0b82aff0b2b6ff72b479df43baa2221439f88063\",\"content\":\"\\\"\\\"\\\"Unit tests for lfx status -- status_command and helpers.\\n\\nAll tests run entirely in-process; no real Langflow instance or SDK required.\\nThe SDK is replaced via patch so only the status logic (file collection, hash\\ncomparison, table rendering, exit-code rules) is exercised.\\n\\\"\\\"\\\"\\n# pragma: allowlist secret -- all credentials in this file are fake test data\\n\\nfrom __future__ import annotations\\n\\nimport io\\nimport json\\nfrom typing import TYPE_CHECKING\\nfrom unittest.mock import MagicMock, patch\\nfrom uuid import UUID\\n\\nimport pytest\\nimport typer\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n# ---------------------------------------------------------------------------\\n# Shared constants\\n# ---------------------------------------------------------------------------\\n\\n_BASE_URL = \\\"http://langflow.test\\\"\\n_API_KEY = \\\"test-key\\\"  # pragma: allowlist secret\\n_FLOW_ID = UUID(\\\"aaaaaaaa-0000-0000-0000-000000000001\\\")\\n_FLOW_ID_2 = UUID(\\\"aaaaaaaa-0000-0000-0000-000000000002\\\")\\n\\n_FLOW_DICT: dict = {\\n    \\\"id\\\": str(_FLOW_ID),\\n    \\\"name\\\": \\\"My Test Flow\\\",\\n    \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n}\\n\\n_FLOW_DICT_2: dict = {\\n    \\\"id\\\": str(_FLOW_ID_2),\\n    \\\"name\\\": \\\"Second Flow\\\",\\n    \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"n1\\\"}], \\\"edges\\\": []},\\n}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Fake exception class \u2014 avoids importing langflow_sdk in isolation mode\\n# ---------------------------------------------------------------------------\\n\\n\\nclass _FakeLangflowNotFoundError(Exception):\\n    \\\"\\\"\\\"Stand-in for langflow_sdk.exceptions.LangflowNotFoundError in unit tests.\\\"\\\"\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Test helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _write_flow(tmp_path: Path, name: str, flow: dict | None = None) -> Path:\\n    p = tmp_path / name\\n    p.parent.mkdir(parents=True, exist_ok=True)\\n    p.write_text(json.dumps(flow if flow is not None else _FLOW_DICT), encoding=\\\"utf-8\\\")\\n    return p\\n\\n\\ndef _fake_env_config(url: str = _BASE_URL, api_key: str = _API_KEY, name: str = \\\"test-env\\\") -> MagicMock:\\n    \\\"\\\"\\\"Return a MagicMock that looks like an lfx EnvConfig.\\\"\\\"\\\"\\n    cfg = MagicMock()\\n    cfg.url = url\\n    cfg.api_key = api_key\\n    cfg.name = name\\n    return cfg\\n\\n\\ndef _fake_remote_flow(flow_id: UUID = _FLOW_ID, flow_dict: dict | None = None) -> MagicMock:\\n    \\\"\\\"\\\"Return a MagicMock that looks like a langflow_sdk Flow model.\\\"\\\"\\\"\\n    remote = MagicMock()\\n    remote.id = flow_id\\n    remote.name = (flow_dict or _FLOW_DICT).get(\\\"name\\\", \\\"Remote Flow\\\")\\n    remote.updated_at = None\\n    # model_dump returns a copy of the dict so hash comparison works correctly\\n    remote.model_dump.return_value = dict(flow_dict or _FLOW_DICT)\\n    return remote\\n\\n\\ndef _identity_normalize(flow: dict) -> dict:\\n    \\\"\\\"\\\"Identity normalize_flow function for tests.\\\"\\\"\\\"\\n    return flow\\n\\n\\ndef _json_flow_to_json(flow: dict) -> str:\\n    \\\"\\\"\\\"Deterministic flow_to_json function for tests.\\\"\\\"\\\"\\n    return json.dumps(flow, sort_keys=True)\\n\\n\\ndef _make_client_mock(\\n    *,\\n    remote_flow: MagicMock | None = None,\\n    get_flow_side_effect: BaseException | None = None,\\n    list_flows_result: list | None = None,\\n) -> MagicMock:\\n    \\\"\\\"\\\"Return a mock SDK client.\\\"\\\"\\\"\\n    client = MagicMock()\\n    if get_flow_side_effect is not None:\\n        client.get_flow.side_effect = get_flow_side_effect\\n    else:\\n        client.get_flow.return_value = remote_flow if remote_flow is not None else _fake_remote_flow()\\n    client.list_flows.return_value = list_flows_result if list_flows_result is not None else []\\n    return client\\n\\n\\ndef _make_sdk_triple(\\n    client_mock: MagicMock | None = None,\\n) -> tuple[object, object, MagicMock, type[Exception]]:\\n    \\\"\\\"\\\"Return the mocked _load_sdk() payload for status_command tests.\\\"\\\"\\\"\\n    if client_mock is None:\\n        client_mock = _make_client_mock()\\n    client_cls = MagicMock(return_value=client_mock)\\n    return _identity_normalize, _json_flow_to_json, client_cls, _FakeLangflowNotFoundError\\n\\n\\nclass _CloseAwareClient:\\n    \\\"\\\"\\\"Minimal client that raises if used after close().\\\"\\\"\\\"\\n\\n    def __init__(self, remote_flow: MagicMock, list_flows_result: list | None = None) -> None:\\n        self._remote_flow = remote_flow\\n        self._list_flows_result = list_flows_result if list_flows_result is not None else []\\n        self.closed = False\\n        self.get_flow_calls: list[UUID] = []\\n        self.list_flows_calls: list[dict] = []\\n\\n    def get_flow(self, flow_id: UUID) -> MagicMock:\\n        if self.closed:\\n            msg = \\\"client already closed\\\"\\n            raise RuntimeError(msg)\\n        self.get_flow_calls.append(flow_id)\\n        return self._remote_flow\\n\\n    def list_flows(self, **kwargs) -> list:\\n        if self.closed:\\n            msg = \\\"client already closed\\\"\\n            raise RuntimeError(msg)\\n        self.list_flows_calls.append(kwargs)\\n        return self._list_flows_result\\n\\n    def close(self) -> None:\\n        self.closed = True\\n\\n\\ndef _run_status(\\n    flow_paths: list[str],\\n    *,\\n    dir_path: str | None = None,\\n    env: str | None = None,\\n    environments_file: str | None = None,\\n    show_remote_only: bool = False,\\n    sdk_triple: tuple | None = None,\\n    env_cfg: MagicMock | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Invoke status_command with fully mocked SDK and config resolution.\\n\\n    The status command now expects _load_sdk() to provide the not-found exception\\n    alongside the serialization helpers and client class.\\n    \\\"\\\"\\\"\\n    from lfx.cli.status import status_command\\n\\n    triple = sdk_triple if sdk_triple is not None else _make_sdk_triple()\\n    cfg = env_cfg if env_cfg is not None else _fake_env_config()\\n\\n    with (\\n        patch(\\\"lfx.cli.status._load_sdk\\\", return_value=triple),\\n        patch(\\\"lfx.config.resolve_environment\\\", return_value=cfg),\\n    ):\\n        status_command(\\n            dir_path=dir_path,\\n            flow_paths=flow_paths,\\n            env=env,\\n            environments_file=environments_file,\\n            target=_BASE_URL,\\n            api_key=_API_KEY,\\n            show_remote_only=show_remote_only,\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# FlowStatus dataclass\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestFlowStatus:\\n    def test_required_fields(self):\\n        from lfx.cli.status import FlowStatus\\n\\n        s = FlowStatus(name=\\\"MyFlow\\\", status=\\\"synced\\\")\\n        assert s.name == \\\"MyFlow\\\"\\n        assert s.status == \\\"synced\\\"\\n\\n    def test_path_defaults_to_none(self):\\n        from lfx.cli.status import FlowStatus\\n\\n        s = FlowStatus(name=\\\"F\\\", status=\\\"new\\\")\\n        assert s.path is None\\n\\n    def test_flow_id_defaults_to_none(self):\\n        from lfx.cli.status import FlowStatus\\n\\n        s = FlowStatus(name=\\\"F\\\", status=\\\"new\\\")\\n        assert s.flow_id is None\\n\\n    def test_detail_defaults_to_empty_string(self):\\n        from lfx.cli.status import FlowStatus\\n\\n        s = FlowStatus(name=\\\"F\\\", status=\\\"error\\\")\\n        assert s.detail == \\\"\\\"\\n\\n    def test_all_fields_assignable(self, tmp_path):\\n        from pathlib import Path\\n\\n        from lfx.cli.status import FlowStatus\\n\\n        p = Path(tmp_path / \\\"flow.json\\\")\\n        s = FlowStatus(name=\\\"X\\\", status=\\\"ahead\\\", path=p, flow_id=_FLOW_ID, detail=\\\"local change\\\")\\n        assert s.path == p\\n        assert s.flow_id == _FLOW_ID\\n        assert s.detail == \\\"local change\\\"\\n\\n    def test_status_constants_exist(self):\\n        import lfx.cli.status as m\\n\\n        assert m._STATUS_SYNCED == \\\"synced\\\"\\n        assert m._STATUS_AHEAD == \\\"ahead\\\"\\n        assert m._STATUS_NEW == \\\"new\\\"\\n        assert m._STATUS_REMOTE_ONLY == \\\"remote-only\\\"\\n        assert m._STATUS_NO_ID == \\\"no-id\\\"\\n        assert m._STATUS_ERROR == \\\"error\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# _flow_hash\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestFlowHash:\\n    def test_returns_12_char_string(self):\\n        from lfx.cli.status import _flow_hash\\n\\n        result = _flow_hash(_FLOW_DICT, _identity_normalize, _json_flow_to_json)\\n        assert isinstance(result, str)\\n        assert len(result) == 12\\n\\n    def test_deterministic_for_same_input(self):\\n        from lfx.cli.status import _flow_hash\\n\\n        h1 = _flow_hash(_FLOW_DICT, _identity_normalize, _json_flow_to_json)\\n        h2 = _flow_hash(_FLOW_DICT, _identity_normalize, _json_flow_to_json)\\n        assert h1 == h2\\n\\n    def test_different_for_different_input(self):\\n        from lfx.cli.status import _flow_hash\\n\\n        h1 = _flow_hash(_FLOW_DICT, _identity_normalize, _json_flow_to_json)\\n        h2 = _flow_hash(_FLOW_DICT_2, _identity_normalize, _json_flow_to_json)\\n        assert h1 != h2\\n\\n    def test_normalize_fn_is_called(self):\\n        from lfx.cli.status import _flow_hash\\n\\n        normalize_mock = MagicMock(return_value=_FLOW_DICT)\\n        _flow_hash(_FLOW_DICT, normalize_mock, _json_flow_to_json)\\n        normalize_mock.assert_called_once_with(_FLOW_DICT)\\n\\n    def test_flow_to_json_fn_is_called(self):\\n        from lfx.cli.status import _flow_hash\\n\\n        to_json_mock = MagicMock(return_value=json.dumps(_FLOW_DICT))\\n        _flow_hash(_FLOW_DICT, _identity_normalize, to_json_mock)\\n        to_json_mock.assert_called_once_with(_FLOW_DICT)\\n\\n    def test_hash_is_hexadecimal(self):\\n        from lfx.cli.status import _flow_hash\\n\\n        result = _flow_hash(_FLOW_DICT, _identity_normalize, _json_flow_to_json)\\n        int(result, 16)  # raises ValueError if not hex\\n\\n\\n# ---------------------------------------------------------------------------\\n# _collect_files\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCollectFiles:\\n    def test_dir_path_returns_json_files(self, tmp_path):\\n        from lfx.cli.status import _collect_files\\n\\n        d = tmp_path / \\\"flows\\\"\\n        d.mkdir()\\n        (d / \\\"a.json\\\").write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        (d / \\\"b.json\\\").write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        (d / \\\"notes.txt\\\").write_text(\\\"ignore\\\", encoding=\\\"utf-8\\\")\\n        result = _collect_files(str(d), [])\\n        assert len(result) == 2\\n        assert all(p.suffix == \\\".json\\\" for p in result)\\n\\n    def test_dir_path_returns_sorted_files(self, tmp_path):\\n        from lfx.cli.status import _collect_files\\n\\n        d = tmp_path / \\\"flows\\\"\\n        d.mkdir()\\n        (d / \\\"z.json\\\").write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        (d / \\\"a.json\\\").write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        result = _collect_files(str(d), [])\\n        assert result[0].name == \\\"a.json\\\"\\n        assert result[1].name == \\\"z.json\\\"\\n\\n    def test_flow_paths_returned_as_paths(self, tmp_path):\\n        from pathlib import Path\\n\\n        from lfx.cli.status import _collect_files\\n\\n        p1 = _write_flow(tmp_path, \\\"x.json\\\")\\n        p2 = _write_flow(tmp_path, \\\"y.json\\\", _FLOW_DICT_2)\\n        result = _collect_files(None, [str(p1), str(p2)])\\n        assert Path(str(p1)) in result\\n        assert Path(str(p2)) in result\\n\\n    def test_empty_args_uses_flows_cwd_when_exists(self, tmp_path, monkeypatch):\\n        from lfx.cli.status import _collect_files\\n\\n        flows_dir = tmp_path / \\\"flows\\\"\\n        flows_dir.mkdir()\\n        (flows_dir / \\\"test.json\\\").write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        monkeypatch.chdir(tmp_path)\\n        result = _collect_files(None, [])\\n        assert len(result) == 1\\n        assert result[0].name == \\\"test.json\\\"\\n\\n    def test_empty_args_no_flows_dir_returns_empty(self, tmp_path, monkeypatch):\\n        from lfx.cli.status import _collect_files\\n\\n        monkeypatch.chdir(tmp_path)\\n        result = _collect_files(None, [])\\n        assert result == []\\n\\n    def test_nonexistent_dir_exits_1(self, tmp_path):\\n        from lfx.cli.status import _collect_files\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _collect_files(str(tmp_path / \\\"does_not_exist\\\"), [])\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_dir_path_takes_priority_over_flow_paths(self, tmp_path):\\n        from lfx.cli.status import _collect_files\\n\\n        d = tmp_path / \\\"flows\\\"\\n        d.mkdir()\\n        (d / \\\"dir_flow.json\\\").write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        extra = _write_flow(tmp_path, \\\"extra.json\\\")\\n        # When dir_path is provided, flow_paths is ignored per code path (elif)\\n        result = _collect_files(str(d), [str(extra)])\\n        names = [p.name for p in result]\\n        assert \\\"dir_flow.json\\\" in names\\n\\n    def test_empty_dir_returns_empty_list(self, tmp_path):\\n        from lfx.cli.status import _collect_files\\n\\n        d = tmp_path / \\\"empty\\\"\\n        d.mkdir()\\n        result = _collect_files(str(d), [])\\n        assert result == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# _render_table\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRenderTable:\\n    @staticmethod\\n    def _capture_render(statuses, env_label):\\n        \\\"\\\"\\\"Render the table to a string buffer and return the plain-text output.\\\"\\\"\\\"\\n        from lfx.cli.status import _render_table\\n        from rich.console import Console\\n\\n        buf = io.StringIO()\\n        fake_console = Console(file=buf, width=200, no_color=True)\\n        with patch(\\\"lfx.cli.status.console\\\", fake_console):\\n            _render_table(statuses, env_label)\\n        return buf.getvalue()\\n\\n    def test_empty_list_does_not_crash(self):\\n        from lfx.cli.status import _render_table\\n\\n        _render_table([], \\\"test-env\\\")\\n\\n    def test_synced_status_contains_flow_name_and_label(self, tmp_path):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [FlowStatus(name=\\\"MyFlow\\\", status=\\\"synced\\\", path=tmp_path / \\\"f.json\\\", flow_id=_FLOW_ID)]\\n        output = self._capture_render(statuses, \\\"test-env\\\")\\n        assert \\\"MyFlow\\\" in output\\n        assert \\\"synced\\\" in output.lower()\\n\\n    def test_ahead_status_contains_label(self, tmp_path):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [FlowStatus(name=\\\"AheadFlow\\\", status=\\\"ahead\\\", path=tmp_path / \\\"f.json\\\", flow_id=_FLOW_ID)]\\n        output = self._capture_render(statuses, \\\"test-env\\\")\\n        assert \\\"AheadFlow\\\" in output\\n        assert \\\"ahead\\\" in output.lower()\\n\\n    def test_new_status_contains_label(self, tmp_path):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [FlowStatus(name=\\\"NewFlow\\\", status=\\\"new\\\", path=tmp_path / \\\"f.json\\\", flow_id=_FLOW_ID)]\\n        output = self._capture_render(statuses, \\\"test-env\\\")\\n        assert \\\"NewFlow\\\" in output\\n        assert \\\"new\\\" in output.lower()\\n\\n    def test_remote_only_status_contains_label(self):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [FlowStatus(name=\\\"RemoteFlow\\\", status=\\\"remote-only\\\", flow_id=_FLOW_ID)]\\n        output = self._capture_render(statuses, \\\"test-env\\\")\\n        assert \\\"RemoteFlow\\\" in output\\n        assert \\\"remote only\\\" in output.lower()\\n\\n    def test_no_id_status_contains_detail(self, tmp_path):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [\\n            FlowStatus(\\n                name=\\\"OrphanFlow\\\",\\n                status=\\\"no-id\\\",\\n                path=tmp_path / \\\"f.json\\\",\\n                detail=\\\"run lfx export first\\\",\\n            )\\n        ]\\n        output = self._capture_render(statuses, \\\"test-env\\\")\\n        assert \\\"OrphanFlow\\\" in output\\n        assert \\\"no id\\\" in output.lower()\\n        assert \\\"run lfx export first\\\" in output\\n\\n    def test_error_status_contains_detail(self, tmp_path):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [FlowStatus(name=\\\"BadFlow\\\", status=\\\"error\\\", path=tmp_path / \\\"f.json\\\", detail=\\\"parse error\\\")]\\n        output = self._capture_render(statuses, \\\"test-env\\\")\\n        assert \\\"BadFlow\\\" in output\\n        assert \\\"error\\\" in output.lower()\\n        assert \\\"parse error\\\" in output\\n\\n    def test_all_statuses_together_contains_all_names(self, tmp_path):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [\\n            FlowStatus(name=\\\"Synced\\\", status=\\\"synced\\\", path=tmp_path / \\\"s.json\\\", flow_id=_FLOW_ID),\\n            FlowStatus(name=\\\"Ahead\\\", status=\\\"ahead\\\", path=tmp_path / \\\"a.json\\\", flow_id=_FLOW_ID_2),\\n            FlowStatus(name=\\\"New\\\", status=\\\"new\\\", path=tmp_path / \\\"n.json\\\"),\\n            FlowStatus(name=\\\"Remote\\\", status=\\\"remote-only\\\", flow_id=_FLOW_ID),\\n            FlowStatus(name=\\\"NoId\\\", status=\\\"no-id\\\", path=tmp_path / \\\"noid.json\\\"),\\n            FlowStatus(name=\\\"Err\\\", status=\\\"error\\\", path=tmp_path / \\\"e.json\\\", detail=\\\"oops\\\"),\\n        ]\\n        output = self._capture_render(statuses, \\\"production\\\")\\n        for s in statuses:\\n            assert s.name in output\\n\\n    def test_env_label_appears_in_title(self, tmp_path):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [FlowStatus(name=\\\"F\\\", status=\\\"synced\\\", path=tmp_path / \\\"f.json\\\", flow_id=_FLOW_ID)]\\n        output = self._capture_render(statuses, \\\"my-staging\\\")\\n        assert \\\"my-staging\\\" in output\\n\\n    def test_status_with_no_path_shows_dash(self):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [FlowStatus(name=\\\"Ghost\\\", status=\\\"remote-only\\\", flow_id=_FLOW_ID)]\\n        output = self._capture_render(statuses, \\\"env\\\")\\n        assert \\\"Ghost\\\" in output\\n\\n    def test_status_with_no_flow_id_shows_dash(self, tmp_path):\\n        from lfx.cli.status import FlowStatus\\n\\n        statuses = [FlowStatus(name=\\\"NoIdFlow\\\", status=\\\"no-id\\\", path=tmp_path / \\\"f.json\\\")]\\n        output = self._capture_render(statuses, \\\"env\\\")\\n        assert \\\"NoIdFlow\\\" in output\\n\\n\\n# ---------------------------------------------------------------------------\\n# status_command \u2014 synced (exits 0)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStatusCommandSynced:\\n    def test_synced_flow_exits_0(self, tmp_path):\\n        \\\"\\\"\\\"When local and remote hashes match, exits 0 (no Exit raised by typer).\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        remote = _fake_remote_flow(flow_dict=_FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote)\\n        triple = _make_sdk_triple(client)\\n        # Should complete without raising Exit(1)\\n        _run_status([str(p)], sdk_triple=triple)\\n\\n    def test_synced_multiple_flows_exits_0(self, tmp_path):\\n        \\\"\\\"\\\"All synced flows \u2192 no Exit raised (exit 0).\\\"\\\"\\\"\\n        p1 = _write_flow(tmp_path, \\\"a.json\\\", _FLOW_DICT)\\n        p2 = _write_flow(tmp_path, \\\"b.json\\\", _FLOW_DICT_2)\\n\\n        remote1 = _fake_remote_flow(_FLOW_ID, _FLOW_DICT)\\n        remote2 = _fake_remote_flow(_FLOW_ID_2, _FLOW_DICT_2)\\n        client = _make_client_mock()\\n        client.get_flow.side_effect = [remote1, remote2]\\n        triple = _make_sdk_triple(client)\\n        _run_status([str(p1), str(p2)], sdk_triple=triple)\\n\\n    def test_synced_calls_get_flow_with_correct_id(self, tmp_path):\\n        \\\"\\\"\\\"get_flow is called with the UUID from the flow file.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        remote = _fake_remote_flow(flow_dict=_FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote)\\n        triple = _make_sdk_triple(client)\\n        _run_status([str(p)], sdk_triple=triple)\\n        client.get_flow.assert_called_once_with(_FLOW_ID)\\n\\n    def test_client_constructed_with_env_url_and_key(self, tmp_path):\\n        \\\"\\\"\\\"SDK Client is created with the resolved env URL and API key.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        remote = _fake_remote_flow(flow_dict=_FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote)\\n        normalize_fn, to_json_fn, client_cls, not_found_error = _make_sdk_triple(client)\\n        cfg = _fake_env_config(url=\\\"http://custom.test\\\", api_key=\\\"my-key\\\")  # pragma: allowlist secret\\n\\n        with (\\n            patch(\\\"lfx.cli.status._load_sdk\\\", return_value=(normalize_fn, to_json_fn, client_cls, not_found_error)),\\n            patch(\\\"lfx.config.resolve_environment\\\", return_value=cfg),\\n        ):\\n            from lfx.cli.status import status_command\\n\\n            status_command(\\n                dir_path=None,\\n                flow_paths=[str(p)],\\n                env=None,\\n                environments_file=None,\\n                target=\\\"http://custom.test\\\",\\n                api_key=\\\"my-key\\\",  # pragma: allowlist secret\\n                show_remote_only=False,\\n            )\\n        client_cls.assert_called_once_with(base_url=\\\"http://custom.test\\\", api_key=\\\"my-key\\\")  # pragma: allowlist secret\\n\\n    def test_client_is_closed_after_requests_finish(self, tmp_path):\\n        \\\"\\\"\\\"The client stays usable during status checks and is closed at the end.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        remote = _fake_remote_flow(flow_dict=_FLOW_DICT)\\n        client = _CloseAwareClient(remote)\\n        triple = _identity_normalize, _json_flow_to_json, MagicMock(return_value=client), _FakeLangflowNotFoundError\\n\\n        _run_status([str(p)], sdk_triple=triple)\\n\\n        assert client.get_flow_calls == [_FLOW_ID]\\n        assert client.closed is True\\n\\n\\n# ---------------------------------------------------------------------------\\n# status_command \u2014 ahead (exits 1)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStatusCommandAhead:\\n    def test_ahead_flow_exits_1(self, tmp_path):\\n        \\\"\\\"\\\"Local hash differs from remote \u2192 exits 1.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", _FLOW_DICT)\\n        # Remote has different data so hashes won't match\\n        remote_dict = dict(_FLOW_DICT)\\n        remote_dict[\\\"data\\\"] = {\\\"nodes\\\": [{\\\"id\\\": \\\"different\\\"}], \\\"edges\\\": []}\\n        remote = _fake_remote_flow(_FLOW_ID, remote_dict)\\n        client = _make_client_mock(remote_flow=remote)\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p)], sdk_triple=triple)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_ahead_status_in_mixed_results_exits_1(self, tmp_path):\\n        \\\"\\\"\\\"Even one 'ahead' flow among synced ones \u2192 exits 1.\\\"\\\"\\\"\\n        p_synced = _write_flow(tmp_path, \\\"synced.json\\\", _FLOW_DICT)\\n        p_ahead = _write_flow(tmp_path, \\\"ahead.json\\\", _FLOW_DICT_2)\\n\\n        remote_synced = _fake_remote_flow(_FLOW_ID, _FLOW_DICT)\\n        remote_ahead_dict = dict(_FLOW_DICT_2)\\n        remote_ahead_dict[\\\"data\\\"] = {\\\"nodes\\\": [{\\\"id\\\": \\\"old\\\"}], \\\"edges\\\": []}\\n        remote_ahead = _fake_remote_flow(_FLOW_ID_2, remote_ahead_dict)\\n\\n        client = _make_client_mock()\\n        client.get_flow.side_effect = [remote_synced, remote_ahead]\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p_synced), str(p_ahead)], sdk_triple=triple)\\n        assert exc_info.value.exit_code == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# status_command \u2014 new (exits 1)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStatusCommandNew:\\n    def test_not_found_on_remote_gives_new_status(self, tmp_path):\\n        \\\"\\\"\\\"Remote raises LangflowNotFoundError \u2192 status 'new' \u2192 exits 1.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock(get_flow_side_effect=_FakeLangflowNotFoundError(\\\"not found\\\"))\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p)], sdk_triple=triple)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_not_found_does_not_call_model_dump(self, tmp_path):\\n        \\\"\\\"\\\"When flow is new (not found), no model_dump call is made.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        remote = _fake_remote_flow(flow_dict=_FLOW_DICT)\\n        client = _make_client_mock(get_flow_side_effect=_FakeLangflowNotFoundError(\\\"not found\\\"))\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit):\\n            _run_status([str(p)], sdk_triple=triple)\\n        remote.model_dump.assert_not_called()\\n\\n\\n# ---------------------------------------------------------------------------\\n# status_command \u2014 no-id (exits 1)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStatusCommandNoId:\\n    def test_flow_without_id_gives_no_id_status(self, tmp_path):\\n        \\\"\\\"\\\"Flow file with no 'id' field \u2192 status 'no-id' \u2192 exits 1.\\\"\\\"\\\"\\n        p = tmp_path / \\\"no_id.json\\\"\\n        p.write_text(json.dumps({\\\"name\\\": \\\"Orphan\\\", \\\"data\\\": {}}), encoding=\\\"utf-8\\\")\\n        client = _make_client_mock()\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p)], sdk_triple=triple)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_flow_with_null_id_gives_no_id_status(self, tmp_path):\\n        \\\"\\\"\\\"Flow file with id=null \u2192 status 'no-id' \u2192 exits 1.\\\"\\\"\\\"\\n        p = tmp_path / \\\"null_id.json\\\"\\n        p.write_text(json.dumps({\\\"id\\\": None, \\\"name\\\": \\\"NullId\\\"}), encoding=\\\"utf-8\\\")\\n        client = _make_client_mock()\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p)], sdk_triple=triple)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_no_id_flow_does_not_call_get_flow(self, tmp_path):\\n        \\\"\\\"\\\"get_flow is never called when a flow has no id.\\\"\\\"\\\"\\n        p = tmp_path / \\\"no_id.json\\\"\\n        p.write_text(json.dumps({\\\"name\\\": \\\"Orphan\\\"}), encoding=\\\"utf-8\\\")\\n        client = _make_client_mock()\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit):\\n            _run_status([str(p)], sdk_triple=triple)\\n        client.get_flow.assert_not_called()\\n\\n\\n# ---------------------------------------------------------------------------\\n# status_command \u2014 error cases (exits 1)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStatusCommandErrors:\\n    def test_invalid_json_gives_error_status(self, tmp_path):\\n        \\\"\\\"\\\"Malformed JSON \u2192 status 'error' \u2192 exits 1.\\\"\\\"\\\"\\n        p = tmp_path / \\\"bad.json\\\"\\n        p.write_text(\\\"this is not json{{\\\", encoding=\\\"utf-8\\\")\\n        client = _make_client_mock()\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p)], sdk_triple=triple)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_invalid_uuid_in_id_gives_error_status(self, tmp_path):\\n        \\\"\\\"\\\"Flow with a non-UUID 'id' value \u2192 status 'error' \u2192 exits 1.\\\"\\\"\\\"\\n        p = tmp_path / \\\"bad_uuid.json\\\"\\n        p.write_text(json.dumps({\\\"id\\\": \\\"not-a-valid-uuid\\\", \\\"name\\\": \\\"BadId\\\"}), encoding=\\\"utf-8\\\")\\n        client = _make_client_mock()\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p)], sdk_triple=triple)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_generic_client_get_flow_exception_gives_error_status(self, tmp_path):\\n        \\\"\\\"\\\"Unexpected exception from client.get_flow \u2192 status 'error' \u2192 exits 1.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock(get_flow_side_effect=RuntimeError(\\\"network timeout\\\"))\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p)], sdk_triple=triple)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_error_on_one_flow_still_processes_others(self, tmp_path):\\n        \\\"\\\"\\\"An error on flow 1 doesn't abort processing of flow 2.\\\"\\\"\\\"\\n        p_bad = tmp_path / \\\"bad.json\\\"\\n        p_bad.write_text(\\\"{{invalid\\\", encoding=\\\"utf-8\\\")\\n        p_good = _write_flow(tmp_path, \\\"good.json\\\")\\n        remote = _fake_remote_flow(flow_dict=_FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote)\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p_bad), str(p_good)], sdk_triple=triple)\\n        # Exits 1 due to the error flow; the good flow was also processed\\n        assert exc_info.value.exit_code == 1\\n        client.get_flow.assert_called_once()\\n\\n    def test_missing_file_in_flow_paths_gives_error_status(self, tmp_path):\\n        \\\"\\\"\\\"A path that doesn't exist \u2192 error status \u2192 exits 1.\\\"\\\"\\\"\\n        nonexistent = tmp_path / \\\"ghost.json\\\"\\n        client = _make_client_mock()\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(nonexistent)], sdk_triple=triple)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_invalid_json_does_not_call_get_flow(self, tmp_path):\\n        \\\"\\\"\\\"get_flow is never called when JSON parsing fails.\\\"\\\"\\\"\\n        p = tmp_path / \\\"bad.json\\\"\\n        p.write_text(\\\"not json\\\", encoding=\\\"utf-8\\\")\\n        client = _make_client_mock()\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit):\\n            _run_status([str(p)], sdk_triple=triple)\\n        client.get_flow.assert_not_called()\\n\\n\\n# ---------------------------------------------------------------------------\\n# status_command \u2014 no local files\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStatusCommandNoLocalFiles:\\n    def test_empty_dir_no_paths_exits_0_with_warning(self, tmp_path):\\n        \\\"\\\"\\\"No flow files found and show_remote_only=False \u2192 exits 0 (via typer.Exit(0)).\\\"\\\"\\\"\\n        d = tmp_path / \\\"empty\\\"\\n        d.mkdir()\\n        client = _make_client_mock()\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([], dir_path=str(d), sdk_triple=triple, show_remote_only=False)\\n        assert exc_info.value.exit_code == 0\\n\\n    def test_empty_dir_no_paths_does_not_call_get_flow(self, tmp_path):\\n        \\\"\\\"\\\"When no files found, get_flow is never invoked.\\\"\\\"\\\"\\n        d = tmp_path / \\\"empty\\\"\\n        d.mkdir()\\n        client = _make_client_mock()\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit):\\n            _run_status([], dir_path=str(d), sdk_triple=triple, show_remote_only=False)\\n        client.get_flow.assert_not_called()\\n\\n    def test_no_files_with_show_remote_only_continues(self, tmp_path):\\n        \\\"\\\"\\\"show_remote_only=True with no local files \u2192 proceeds to list_flows.\\\"\\\"\\\"\\n        d = tmp_path / \\\"empty\\\"\\n        d.mkdir()\\n        remote = MagicMock()\\n        remote.id = _FLOW_ID\\n        remote.name = \\\"RemoteFlow\\\"\\n        client = _make_client_mock(list_flows_result=[remote])\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([], dir_path=str(d), sdk_triple=triple, show_remote_only=True)\\n        # remote-only entries are not synced \u2192 exits 1\\n        assert exc_info.value.exit_code == 1\\n        client.list_flows.assert_called_once()\\n\\n\\n# ---------------------------------------------------------------------------\\n# status_command \u2014 remote-only\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStatusCommandRemoteOnly:\\n    def test_show_remote_only_calls_list_flows(self, tmp_path):\\n        \\\"\\\"\\\"show_remote_only=True \u2192 client.list_flows(get_all=True) is called.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        remote_local = _fake_remote_flow(flow_dict=_FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote_local, list_flows_result=[])\\n        triple = _make_sdk_triple(client)\\n\\n        _run_status([str(p)], sdk_triple=triple, show_remote_only=True)\\n        client.list_flows.assert_called_once_with(get_all=True)\\n\\n    def test_without_show_remote_only_does_not_call_list_flows(self, tmp_path):\\n        \\\"\\\"\\\"show_remote_only=False \u2192 list_flows is never called.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        remote = _fake_remote_flow(flow_dict=_FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote)\\n        triple = _make_sdk_triple(client)\\n\\n        _run_status([str(p)], sdk_triple=triple, show_remote_only=False)\\n        client.list_flows.assert_not_called()\\n\\n    def test_remote_only_flows_excluded_if_seen_locally(self, tmp_path):\\n        \\\"\\\"\\\"Flows already tracked locally are not added as remote-only entries.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", _FLOW_DICT)\\n        remote_local = _fake_remote_flow(_FLOW_ID, _FLOW_DICT)\\n        # list_flows returns the same flow that's tracked locally\\n        list_entry = MagicMock()\\n        list_entry.id = _FLOW_ID\\n        list_entry.name = \\\"My Test Flow\\\"\\n        client = _make_client_mock(remote_flow=remote_local, list_flows_result=[list_entry])\\n        triple = _make_sdk_triple(client)\\n\\n        # All synced, no remote-only \u2192 exits 0 (no Exit raised)\\n        _run_status([str(p)], sdk_triple=triple, show_remote_only=True)\\n\\n    def test_remote_only_untracked_flow_appended(self, tmp_path):\\n        \\\"\\\"\\\"Flows on remote that have no local file appear as remote-only \u2192 exits 1.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", _FLOW_DICT)\\n        remote_local = _fake_remote_flow(_FLOW_ID, _FLOW_DICT)\\n\\n        # A second remote flow that has no local counterpart\\n        remote_extra = MagicMock()\\n        remote_extra.id = _FLOW_ID_2\\n        remote_extra.name = \\\"Remote Only Flow\\\"\\n\\n        local_entry = MagicMock()\\n        local_entry.id = _FLOW_ID\\n        local_entry.name = \\\"My Test Flow\\\"\\n\\n        client = _make_client_mock(remote_flow=remote_local, list_flows_result=[local_entry, remote_extra])\\n        triple = _make_sdk_triple(client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_status([str(p)], sdk_triple=triple, show_remote_only=True)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_list_flows_exception_prints_warning_and_continues(self, tmp_path):\\n        \\\"\\\"\\\"If list_flows raises, a warning is printed but the command continues.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", _FLOW_DICT)\\n        remote_local = _fake_remote_flow(_FLOW_ID, _FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote_local)\\n        client.list_flows.side_effect = RuntimeError(\\\"list_flows failed\\\")\\n        triple = _make_sdk_triple(client)\\n\\n        # Should not raise an unexpected exception \u2014 synced flow still exits 0\\n        _run_status([str(p)], sdk_triple=triple, show_remote_only=True)\\n\\n\\n# ---------------------------------------------------------------------------\\n# status_command \u2014 config error\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStatusCommandConfigError:\\n    def test_config_error_exits_1(self, tmp_path):\\n        \\\"\\\"\\\"ConfigError from resolve_environment \u2192 exits 1.\\\"\\\"\\\"\\n        from lfx.cli.status import status_command\\n        from lfx.config import ConfigError\\n\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        triple = _make_sdk_triple()\\n\\n        with (\\n            patch(\\\"lfx.cli.status._load_sdk\\\", return_value=triple),\\n            patch(\\\"lfx.config.resolve_environment\\\", side_effect=ConfigError(\\\"bad config\\\")),\\n            pytest.raises(typer.Exit) as exc_info,\\n        ):\\n            status_command(\\n                dir_path=None,\\n                flow_paths=[str(p)],\\n                env=\\\"nonexistent\\\",\\n                environments_file=str(tmp_path / \\\"missing.toml\\\"),\\n                target=None,\\n                api_key=None,\\n                show_remote_only=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_missing_environments_file_exits_1(self, tmp_path):\\n        \\\"\\\"\\\"A non-existent --environments-file passed through config \u2192 exits 1.\\\"\\\"\\\"\\n        from lfx.cli.status import status_command\\n\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        triple = _make_sdk_triple()\\n\\n        with (\\n            patch(\\\"lfx.cli.status._load_sdk\\\", return_value=triple),\\n            pytest.raises(typer.Exit) as exc_info,\\n        ):\\n            status_command(\\n                dir_path=None,\\n                flow_paths=[str(p)],\\n                env=\\\"ci\\\",\\n                environments_file=str(tmp_path / \\\"does_not_exist.toml\\\"),\\n                target=None,\\n                api_key=None,\\n                show_remote_only=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# status_command \u2014 all synced \u2192 exits 0\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStatusCommandAllSynced:\\n    def test_all_synced_no_exit_raised(self, tmp_path):\\n        \\\"\\\"\\\"When every local flow matches remote, status_command returns normally (exit 0).\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", _FLOW_DICT)\\n        remote = _fake_remote_flow(_FLOW_ID, _FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote)\\n        triple = _make_sdk_triple(client)\\n\\n        # Must NOT raise typer.Exit\\n        _run_status([str(p)], sdk_triple=triple)\\n\\n    def test_all_synced_does_not_raise_exit_1(self, tmp_path):\\n        \\\"\\\"\\\"Confirm that Exit(1) is specifically not raised for all-synced scenario.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", _FLOW_DICT)\\n        remote = _fake_remote_flow(_FLOW_ID, _FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote)\\n        triple = _make_sdk_triple(client)\\n\\n        try:\\n            _run_status([str(p)], sdk_triple=triple)\\n        except typer.Exit as exc:\\n            pytest.fail(f\\\"Expected no Exit for all-synced but got Exit({exc.exit_code})\\\")\\n\\n    def test_dir_with_all_synced_files_exits_0(self, tmp_path):\\n        \\\"\\\"\\\"--dir with all synced flows \u2192 no Exit raised.\\\"\\\"\\\"\\n        d = tmp_path / \\\"flows\\\"\\n        d.mkdir()\\n        (d / \\\"flow1.json\\\").write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n\\n        remote = _fake_remote_flow(_FLOW_ID, _FLOW_DICT)\\n        client = _make_client_mock(remote_flow=remote)\\n        triple = _make_sdk_triple(client)\\n\\n        _run_status([], dir_path=str(d), sdk_triple=triple)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_validate_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"60bd104741a737ae6b5ba5ee1142669557cb7b7b277b74d066f365b668205250\",\"content\":\"\\\"\\\"\\\"Unit tests for lfx validate \u2014 structural, extended checks, directory scanning, strict mode.\\n\\nAll tests run entirely in-process (no running Langflow instance or component\\nregistry required).  Level-2 component checks are skipped via skip_components=True\\nso the registry never needs to be loaded.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom importlib.metadata import PackageNotFoundError\\nfrom pathlib import Path\\nfrom unittest.mock import call, patch\\n\\nimport pytest\\nfrom lfx.cli.validate import (\\n    ValidationResult,\\n    _check_missing_credentials,\\n    _check_orphaned_nodes,\\n    _check_unused_nodes,\\n    _check_version_mismatch,\\n    _expand_paths,\\n    _get_lf_version,\\n    validate_command,\\n    validate_flow_file,\\n)\\n\\n# ---------------------------------------------------------------------------\\n# Fixtures / helpers\\n# ---------------------------------------------------------------------------\\n\\n_MINIMAL_VALID = {\\n    \\\"id\\\": \\\"11111111-1111-1111-1111-111111111111\\\",\\n    \\\"name\\\": \\\"Test Flow\\\",\\n    \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n}\\n\\n_NODE = {\\n    \\\"id\\\": \\\"node-a\\\",\\n    \\\"data\\\": {\\n        \\\"id\\\": \\\"node-a\\\",\\n        \\\"type\\\": \\\"ChatInput\\\",\\n        \\\"node\\\": {\\n            \\\"display_name\\\": \\\"Chat Input\\\",\\n            \\\"template\\\": {},\\n        },\\n    },\\n    \\\"position\\\": {\\\"x\\\": 0, \\\"y\\\": 0},\\n}\\n\\n\\ndef _write_flow(tmp_path: Path, name: str, flow: dict) -> Path:\\n    p = tmp_path / name\\n    p.write_text(json.dumps(flow), encoding=\\\"utf-8\\\")\\n    return p\\n\\n\\ndef _make_result(issues=None) -> ValidationResult:\\n    result = ValidationResult(path=Path(\\\"test.json\\\"))\\n    if issues:\\n        result.issues = issues\\n    return result\\n\\n\\ndef test_installed_version_falls_back_to_base_distribution():\\n    versions = {\\\"langflow-base\\\": \\\"1.12.0\\\"}\\n\\n    def get_version(package: str) -> str:\\n        if package not in versions:\\n            raise PackageNotFoundError(package)\\n        return versions[package]\\n\\n    with patch(\\\"importlib.metadata.version\\\", side_effect=get_version) as version_mock:\\n        assert _get_lf_version() == \\\"1.12.0\\\"\\n\\n    assert version_mock.call_args_list == [\\n        call(\\\"langflow\\\"),\\n        call(\\\"langflow-nightly\\\"),\\n        call(\\\"langflow-base\\\"),\\n    ]\\n\\n\\n# ---------------------------------------------------------------------------\\n# validate_flow_file \u2014 Level 1: structural\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestStructural:\\n    def test_valid_minimal_flow(self, tmp_path):\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", _MINIMAL_VALID)\\n        result = validate_flow_file(p, level=1)\\n        assert result.ok\\n        assert not result.errors\\n\\n    def test_invalid_json(self, tmp_path):\\n        p = tmp_path / \\\"bad.json\\\"\\n        p.write_text(\\\"{not valid json\\\", encoding=\\\"utf-8\\\")\\n        result = validate_flow_file(p, level=1)\\n        assert not result.ok\\n        assert any(\\\"Invalid JSON\\\" in i.message for i in result.errors)\\n\\n    def test_missing_top_level_id(self, tmp_path):\\n        flow = {k: v for k, v in _MINIMAL_VALID.items() if k != \\\"id\\\"}\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", flow)\\n        result = validate_flow_file(p, level=1)\\n        assert not result.ok\\n        assert any(\\\"id\\\" in i.message for i in result.errors)\\n\\n    def test_missing_top_level_name(self, tmp_path):\\n        flow = {k: v for k, v in _MINIMAL_VALID.items() if k != \\\"name\\\"}\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", flow)\\n        result = validate_flow_file(p, level=1)\\n        assert not result.ok\\n\\n    def test_missing_data_nodes(self, tmp_path):\\n        flow = {**_MINIMAL_VALID, \\\"data\\\": {\\\"edges\\\": []}}\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", flow)\\n        result = validate_flow_file(p, level=1)\\n        assert not result.ok\\n        assert any(\\\"data.nodes\\\" in i.message for i in result.errors)\\n\\n    def test_missing_data_edges(self, tmp_path):\\n        flow = {**_MINIMAL_VALID, \\\"data\\\": {\\\"nodes\\\": []}}\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", flow)\\n        result = validate_flow_file(p, level=1)\\n        assert not result.ok\\n\\n    def test_data_not_object(self, tmp_path):\\n        flow = {**_MINIMAL_VALID, \\\"data\\\": \\\"not-an-object\\\"}\\n        p = _write_flow(tmp_path, \\\"flow.json\\\", flow)\\n        result = validate_flow_file(p, level=1)\\n        assert not result.ok\\n\\n    def test_file_not_found(self, tmp_path):\\n        result = validate_flow_file(tmp_path / \\\"missing.json\\\", level=1)\\n        assert not result.ok\\n        assert any(\\\"Cannot read\\\" in i.message for i in result.errors)\\n\\n\\n# -----";
